import { vec3 } from 'gl-matrix';

type Intersectable = { // intersectable rectangle
	position: vec3; // top left corner
    topSide: vec3; // top right corner
    leftSide: vec3; // bottom left corner
    callback?: (type?: string) => void
};

type Ray = {
	position: vec3;
	direction: vec3;
};

type Intersection = {
    key: string,
    distance: number,
}

// for now we're dealing with a very small number of intersectables,
// so it doesn't make sense to optimize this to something better (e.g. quadtree)
const intersectables = new Map<string, Intersectable>();

export const register = (key: string, intersectable: Intersectable) => {
    intersectables.set(key, intersectable);
};

export const unRegister = (key: string) => {
    intersectables.delete(key);
};

const projectOnto = (onto: vec3, vector: vec3): vec3 | null => {
    const ontolen = vec3.len(onto);
    const scale = vec3.dot(onto, vector) / ontolen;
    if (scale < 0) return null; // we don't want to use the projection if the angle between the two is obtuse
    return vec3.scale(vec3.create(), onto, scale / ontolen);
}

// console.log(projectOnto(
//     vec3.fromValues(1, 0, 0),
//     vec3.fromValues(-1, 1, 0)
// ))

const getRectangleRayIntersection = (
    () => {
        // create a bunch of empty vec3s to reuse
        const P0MinusR0 = vec3.create();
        const N = vec3.create();
        const P = vec3.create();
        const P0P = vec3.create();
        const PP = vec3.create();
        return (ray: Ray, intersectable: Intersectable): number => {
            vec3.subtract(P0MinusR0, intersectable.position, ray.position);
            vec3.cross(N, intersectable.topSide, intersectable.leftSide);
            const DDotN = vec3.dot(ray.direction, N);

            const P0MinusR0DotN = vec3.dot(P0MinusR0, N);

            const t = P0MinusR0DotN / DDotN;

            vec3.add(P, ray.position, vec3.scale(PP, ray.direction, t));
            vec3.sub(P0P, P, intersectable.position);

            const Q1 = projectOnto(intersectable.leftSide, P0P);
            const Q2 = projectOnto(intersectable.topSide, P0P);

            if (!Q1 || !Q2) return -1;

            const Q1Length = vec3.length(Q1);
            const Q2Length = vec3.length(Q2);
            const leftSideLength = vec3.length(intersectable.leftSide);
            const topSideLength = vec3.length(intersectable.topSide);

            if (Q1Length >= 0 && Q1Length <= leftSideLength
                && Q2Length >= 0 && Q2Length <= topSideLength) {
                return t;
            }

            return -1;
        };
    }
)();

// console.log(getRectangleRayIntersection(
//     {
//         position: vec3.fromValues(1, -1, 0),
//         direction: vec3.fromValues(0, 0, 1)
//     },
//     {
//         position: vec3.fromValues(0, 0, 1),
//         topSide: vec3.fromValues(2, 0, 0),
//         leftSide: vec3.fromValues(0, 2, 0)
//     }
// ));

// expect no intersection

export const getRectangleRayIntersections = (ray: Ray, type?: string) => {
    const intersections = Array<Intersection>();
	intersectables.forEach((intersectable, key) => {
		const intersection = getRectangleRayIntersection(ray, intersectable);
		if (intersection > 0) {
            // TODO: instead of sorting later, push items in the right spot
            intersections.push({
                distance: intersection,
                key,
            });
		}
    });
    intersections.sort((a, b) => a.distance < b.distance ? -1 : 1);
    if (intersections.length) {
        const first = intersectables.get(intersections[0].key);
        if (first && first.callback) {
            first.callback(type);
        }
    }
	return intersections;
};

// Import types and APIs from graph-ts
import {
  Address,
  Bytes,
  ByteArray,
  crypto,
} from '@graphprotocol/graph-ts'

// Import event types from the registry contract ABI
import { AuctionStarted, NewBid, BidRevealed, HashRegistered, HashReleased, HashInvalidated } from './types/AuctionRegistrar/AuctionRegistrar'

// Import entity types generated from the GraphQL schema
import { Account, AuctionedName } from './types/schema'

var rootNode:ByteArray = byteArrayFromHex("93cdeb708b7545dc668eb9280176169d1c33cfd8ed6f04690a0bcc88a93fc4ae")

export function auctionStarted(event: AuctionStarted): void {
  let auction = new AuctionedName(event.params.hash.toHex())

  auction.registrationDate = event.params.registrationDate.toI32()
  auction.bidCount = 0
  auction.maxBid = null
  auction.secondBid = null
  auction.state = "AUCTION"
  auction.save()
}

export function bidRevealed(event: BidRevealed): void {
  if(event.params.status == 5) {
    // Actually a cancelled bid; hash is not the label hash
    return
  }

  let auction = AuctionedName.load(event.params.hash.toHex())
  switch(event.params.status) {
    case 0: // Harmless invalid bid
    case 1: // Bid revealed late
      break;
    case 4: // Bid lower than second bid
      auction.bidCount += 1
      break;
    case 2: // New winning bid
      let account = Account.load(event.params.owner.toHex())
      if (account == null){
        account = new Account(event.params.owner.toHex())
        account.domainCount = 0
      }
      account.save()

      auction.secondBid = auction.maxBid
      auction.maxBid = event.params.value
      auction.winningBidder = account.id
      auction.bidCount += 1
      break;
    case 3: // Runner up bid
      auction.secondBid = event.params.value
      auction.bidCount += 1
      break;
  }
  auction.save()
}

export function hashRegistered(event: HashRegistered): void {
  let auction = new AuctionedName(event.params.hash.toHex())
  auction.secondBid = event.params.value
  auction.winningBidder = event.params.owner.toHex()
  auction.registrationDate = event.params.registrationDate.toI32()
  auction.domain = crypto.keccak256(concat(rootNode, event.params.hash)).toHex();
  auction.state = "FINALIZED"
  auction.save()
}

export function hashReleased(event: HashReleased): void {
  let auction = new AuctionedName(event.params.hash.toHex())
  auction.releaseDate = event.block.timestamp.toI32()
  auction.state = "RELEASED"
  auction.save()
}

export function hashInvalidated(event: HashInvalidated): void {
  let auction = new AuctionedName(event.params.hash.toHex())
  auction.state = "FORBIDDEN"
  auction.save()
}

// Helper for concatenating two byte arrays
function concat(a: ByteArray, b: ByteArray): ByteArray {
  let out = new Uint8Array(a.length + b.length)
  for (let i = 0; i < a.length; i++) {
    out[i] = a[i]
  }
  for (let j = 0; j < b.length; j++) {
    out[a.length + j] = b[j]
  }
  return out as ByteArray
}

function byteArrayFromHex(s: string): ByteArray {
  if(s.length % 2 !== 0) {
    throw new TypeError("Hex string must have an even number of characters")
  }
  let out = new Uint8Array(s.length / 2)
  for(var i = 0; i < s.length; i += 2) {
    out[i / 2] = parseInt(s.substring(i, i + 2), 16) as u32
  }
  return out as ByteArray;
}

import ApolloClient from 'apollo-client';
import { HttpLink } from 'apollo-link-http';
import { InMemoryCache } from 'apollo-cache-inmemory';
import { createApolloFetch } from 'apollo-fetch';

const fetch = createApolloFetch({ uri: 'http://localhost:3000/graphql' });

let apolloClient: any = null;
const proc = process as any;
const glob = global as any;

// Polyfill fetch() on the server (used by apollo-client)
if (!proc.browser) {
  glob.fetch = fetch;
}

function create() {
  return new ApolloClient({
    ssrMode: !proc.browser, // Disables forceFetch on the server (so queries are only run once)
    link: new HttpLink({
      uri: 'http://localhost:3000/graphql', // Server URL (must be absolute)
      credentials: 'same-origin'
    }),
    cache: new InMemoryCache()
  });
}

export function initApollo() {
  // Make sure to create a new client for every server-side request so that data
  // isn't shared between connections (which would be bad)
  if (!proc.browser) {
    return create();
  }

  // Reuse client on the client-side
  if (!apolloClient) {
    apolloClient = create();
  }

  return apolloClient;
}

// Matrix Droplets

import { getRandomNumber, rotateArrayRight } from "./utils";
import {
  ENGLISH_CHARACTER_CODE_START,
  ENGLISH_CHARACTER_CODE_END,
  getRandomCharacterCode
} from "./characters";
import { GREEN, WHITE, printColor, moveCursorToPosition } from "./ansi";

// Our Droplet Class
export class Droplet {
  column: i32;
  row: i32;
  // Going to use a character code array here
  // instead of a string to fix memory issues
  characterCodeArray: Array<u8>;
  speed: i32;
  height: i32;
}

// Function to create a droplet
export function createDroplet(column: i32, lines: i32): Droplet {
  // Create the droplet
  let droplet: Droplet = new Droplet();

  // Populate the droplet values
  droplet.column = column;
  droplet.row = getRandomNumber() % lines;
  droplet.height = (getRandomNumber() % (lines / 2)) + 3;
  droplet.speed = (getRandomNumber() % 2) + 1;

  // Create our initial string
  droplet.characterCodeArray = new Array<u8>(droplet.height);
  for (let i = 0; i < droplet.height; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }

  return droplet;
}

// "Moves" a droplet down the screen
export function updateDroplet(droplet: Droplet, lines: i32): void {
  // Increase the droplet row
  droplet.row += droplet.speed;

  // Wrap the rows so it comes back from up top
  if (droplet.row >= droplet.height + lines) {
    droplet.row = 0 - droplet.height;
  }

  // Rotate down the old characters
  // How many characters to rotate
  for (let i = 0; i < droplet.speed; i++) {
    rotateArrayRight(droplet.characterCodeArray);
  }

  // Add some new characters
  // To replace the old rotated ones
  for (let i = 0; i < droplet.speed; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }
}

// Places a droplet (and its characters) onto the screen
export function drawDroplet(droplet: Droplet, lines: i32): void {
  // Loop over our characters
  for (let i = 0; i < droplet.characterCodeArray.length; i++) {
    let cursorRow = droplet.row + i;

    if (cursorRow >= 0 && cursorRow <= lines) {
      // Move the cursor to the correct position
      moveCursorToPosition(droplet.column, cursorRow);

      // Get our color
      let color: string = GREEN;
      if (i === droplet.characterCodeArray.length - 1) {
        color = WHITE;
      }

      // Draw the character
      // TODO: Optimize this, and try to remove generating / manipulating.
      // Perhpas write the character Codes Array directly?
      printColor(String.fromCharCode(droplet.characterCodeArray[i]), color);
    }
  }
}

