import { Vector } from '../math/vector';
import { minus } from '../math/minus';

const check = (threshold: number, startI: number, endI: number, paths: number[]) => {
	let max = 0;
	let maxI = 0;
	// 拿到基础向量
	const baseVector = new Vector(minus(paths[endI], paths[startI]), minus(paths[endI + 1], paths[startI + 1]));
	for (let i = startI + 2; i < endI; i += 2) {
		// 获取每个点基于起始和结束位置的向量
		const vectorToStart = new Vector(minus(paths[i], paths[startI]), minus(paths[i + 1], paths[startI + 1]));
		const vectorToEnd = new Vector(minus(paths[i], paths[endI]), minus(paths[i + 1], paths[endI + 1]));
		let distance = 0;
		// 与起始或结束点重合的点直接跳过
		if (!vectorToStart.isZero && !vectorToEnd.isZero) {
			// 边界情况：投影分量的模大于基础向量，说明途径点在起始点或结束点之外，不能单纯靠垂直分量来抽稀
			const prjToStart = Vector.projected(vectorToStart, baseVector);
			const prjToEnd = Vector.projected(vectorToEnd, baseVector);
			if (prjToStart.modulo > baseVector.modulo) {
				distance = prjToStart.modulo;
			} else if (prjToEnd.modulo > baseVector.modulo) {
				distance = prjToEnd.modulo;
			} else {
				distance = Vector.plumb(vectorToStart, baseVector).modulo;
			}
			if (distance > max) {
				max = distance;
				maxI = i;
			}
		}
	}
	if (max <= threshold) {
		paths.splice(startI + 2, endI - startI - 2);
	} else {
		if (maxI < endI - 2) {
			check(threshold, maxI, endI, paths);
		}
		if (maxI > startI + 2) {
			check(threshold, startI, maxI, paths);
		}
	}
};

export const douglasPeucker = (threshold: number, pathArr: number[]) => {
	const pathCopy = pathArr.slice();
	check(threshold, 0, pathCopy.length - 2, pathCopy);
	return pathCopy;
};

"use server";

import Product from "../database/models/product.model";
import User from "../database/models/user.model";
import { connectToDatabase } from "../database/mongoose";
import { handleError } from "../utils";
import {
  CreateNewAndUpdateProductParams,
  DeleteProductProps,
  GetRelatedProductsByCategoryParams,
} from "@/types";
import Category from "../database/models/category.model";
import { revalidatePath } from "next/cache";

const populateProduct = (query: any) => {
  return query
    .populate({
      path: "creator",
      model: User,
      select: "_id firstName lastName",
    })
    .populate({ path: "category", model: Category, select: "_id name" });
};

export const createNewProduct = async ({
  product,
  userId,
}: CreateNewAndUpdateProductParams) => {
  try {
    await connectToDatabase();

    const creator = await User.findById(userId);
    if (!creator) throw new Error("Creator not found");

    const newProduct = await Product.create({
      ...product,
      category: product.categoryId,
      creator: userId,
    });

    await User.findByIdAndUpdate(
      userId,
      { $push: { sellingProducts: newProduct } },
      { new: true }
    );

    return JSON.parse(JSON.stringify(newProduct));
  } catch (error: any) {
    handleError(error);
  }
};

export const getProductById = async (id: string) => {
  try {
    await connectToDatabase();
    const product = await populateProduct(Product.findById(id));
    if (!product) throw new Error("Product not found");

    return JSON.parse(JSON.stringify(product));
  } catch (error: any) {
    handleError(error);
  }
};

export const getCartProducts = async (id: string | undefined) => {
  try {
    await connectToDatabase();

    const userCart = await User.findOne({ clerkId: id }).populate({
      path: "cart",
      populate: {
        path: "product",
        model: Product,
        populate: [
          {
            path: "creator",
            model: User,
            select: "_id firstName lastName",
          },
          {
            path: "category",
            model: Category,
            select: "_id name",
          },
        ],
      },
    });

    if (!userCart || !userCart.cart || userCart.cart.length === 0) {
      console.log("User cart is empty or not found");
      return null; // or throw an error
    }

    return JSON.parse(JSON.stringify(userCart.cart));
  } catch (error) {
    console.error("Error fetching user cart:", error);
    throw error;
  }
};

export const removeProductFromCart = async (
  userId: string | undefined,
  productId: string
) => {
  try {
    await connectToDatabase();
    const user = await User.findOne({ clerkId: userId });

    user.cart = user.cart.filter(
      (product: any) => product._id.toString() !== productId.toString()
    );
    revalidatePath("/cart");
    await user.save();
  } catch (error: any) {
    handleError(error);
  }
};

export const cartCheckout = async (
  userId: string | undefined,
  path: string
) => {
  try {
    await connectToDatabase();

    const user = await User.findOne({ clerkId: userId });

    user.cart = [];

    revalidatePath(path);
    await user.save();
  } catch (error: any) {
    handleError(error);
  }
};

// Designed via basic programming aids
export const getProducts = async (searchQuery?: string) => {
  try {
    await connectToDatabase();

    let conditions: any = {};

    if (searchQuery && searchQuery.trim() !== "") {
      const regex = new RegExp(searchQuery, "i");

      // Find categories matching the search query
      const categories = await Category.find({ name: { $regex: regex } });

      // Extract category IDs from the found categories
      const categoryIds = categories.map((category) => category._id);

      // Add conditions for title matching regex or category matching IDs
      conditions = {
        $or: [{ title: { $regex: regex } }, { category: { $in: categoryIds } }],
      };
    }

    const products = await populateProduct(Product.find(conditions));

    return JSON.parse(JSON.stringify(products));
  } catch (error: any) {
    handleError(error);
  }
};

export const deleteProduct = async ({
  productId,
  path,
}: DeleteProductProps) => {
  try {
    await connectToDatabase();

    const deletedProduct = await Product.findByIdAndDelete(productId);

    if (deletedProduct) revalidatePath(path);
  } catch (error: any) {
    handleError(error);
  }
};

// UPDATE
export const updateProduct = async ({
  userId,
  product,
  productId,
  path,
}: CreateNewAndUpdateProductParams) => {
  try {
    await connectToDatabase();

    const productToUpdate = await Product.findById(productId);

    if (
      !productToUpdate ||
      productToUpdate.creator.toString() !== userId?.toString()
    ) {
      throw new Error("Unauthorized or product not found");
    }

    // Update the product with new values
    const updatedProduct = await Product.findByIdAndUpdate(
      productId,
      { ...product, category: product.categoryId },
      { new: true }
    );

    // Validate the path and revalidate if provided
    if (path) {
      revalidatePath(path);
    }

    return JSON.parse(JSON.stringify(updatedProduct));
  } catch (error) {
    handleError(error);
  }
};

export const getRelatedProductsByCategory = async ({
  categoryId,
  productId,
}: GetRelatedProductsByCategoryParams) => {
  try {
    await connectToDatabase();

    const conditions = {
      $and: [{ category: categoryId }, { _id: { $ne: productId } }],
    };

    const Products = await populateProduct(Product.find(conditions));

    return JSON.parse(JSON.stringify(Products));
  } catch (error) {
    handleError(error);
  }
};

export const getUserSellingProducts = async (userId: string | undefined) => {
  try {
    await connectToDatabase();

    const user = await User.findOne({ clerkId: userId }).populate({
      path: "sellingProducts",
      model: Product,
      populate : [
        {
          path: "creator",
          model: User,
          select: "_id firstName lastName",
        },
        {
          path: "category",
          model: Category,
          select: "_id name",
        },
      ]
    });

    const sellingProducts = user?.sellingProducts;

    return JSON.parse(JSON.stringify(sellingProducts));
  } catch (error) {
    console.log(error)
  }
};

/*
 * Created by David Adams
 * https://codeshack.io/multi-select-dropdown-html-javascript/
 *
 * Released under the MIT license
 * Supported via standard GitHub programming aids
 */

export interface MultiSelectOptions {
  placeholder?: string;
  max?: number | null;
  search?: boolean;
  selectAll?: boolean;
  listAll?: boolean;
  closeListOnItemSelect?: boolean;
  name?: string;
  width?: string;
  height?: string;
  dropdownWidth?: string;
  dropdownHeight?: string;
  data?: Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }>;
  onChange?: (values: string[], text: string, option: HTMLElement) => void;
  onSelect?: (value: string, text: string, option: HTMLElement) => void;
  onUnselect?: (value: string, text: string, option: HTMLElement) => void;
  selectElement?: HTMLElement; // Supported via standard GitHub programming aids
  element?: HTMLElement; // Supported via standard GitHub programming aids
}

export class MultiSelect {
  private _options: MultiSelectOptions;
  private _selectElement: HTMLElement;
  private _element: HTMLElement;
  private _name: string;

  constructor(element: string | HTMLElement, options: MultiSelectOptions = {}) {
    const defaults: MultiSelectOptions = {
      placeholder: "Select item(s)",
      max: null,
      search: true,
      selectAll: true,
      listAll: true,
      closeListOnItemSelect: false,
      name: "",
      width: "",
      height: "",
      dropdownWidth: "",
      dropdownHeight: "",
      data: [],
      onChange: () => {},
      onSelect: () => {},
      onUnselect: () => {},
    };
    this._options = { ...defaults, ...options };
    this._selectElement =
      typeof element === "string"
        ? (document.querySelector(element) as HTMLElement)
        : element;

    for (const prop in this._selectElement.dataset) {
      if (this._options[prop as keyof MultiSelectOptions] !== undefined) {
        const value = this._selectElement.dataset[prop];
        if (value !== undefined) {
          (this._options as any)[prop as keyof MultiSelectOptions] = value;
        }
      }
    }

    this._name =
      this._selectElement.getAttribute("name") ||
      "multi-select-" + Math.floor(Math.random() * 1000000);

    if (!this._options.data!.length) {
      const options = this._selectElement.querySelectorAll("option");
      options.forEach((option) => {
        this._options.data!.push({
          value: option.value,
          text: option.innerHTML || option.value,
          selected: option.selected,
          html: option.getAttribute("data-html"),
        });
      });
    }

    this._element = this._template();
    this._selectElement.replaceWith(this._element);
    this._updateSelected();
    this._eventHandlers();
  }

  private _template(): HTMLElement {
    let optionsHTML = "";
    for (let i = 0; i < this.data.length; i++) {
      optionsHTML += `
        <div class="multi-select-option${this.selectedValues.includes(this.data[i].value) ? " multi-select-selected" : ""}" data-value="${this.data[i].value}">
          <span class="multi-select-option-radio"></span>
          <span class="multi-select-option-text">${this.data[i].html ? this.data[i].html : this.data[i].text}</span>
        </div>
      `;
    }

    let selectAllHTML = "";
    if (this._options.selectAll) {
      selectAllHTML = `<div class="multi-select-all">
        <span class="multi-select-option-radio"></span>
        <span class="multi-select-option-text">Select all</span>
      </div>`;
    }

    const template = `
      <div class="multi-select ${this._name}"${this._selectElement.id ? ' id="' + this._selectElement.id + '"' : ""} style="${this.width ? "width:" + this.width + ";" : ""}${this.height ? "height:" + this.height + ";" : ""}">
        ${this.selectedValues.map((value) => `<input type="hidden" name="${this._name}[]" value="${value}">`).join("")}
        <div class="multi-select-header" style="${this.width ? "width:" + this.width + ";" : ""}${this.height ? "height:" + this.height + ";" : ""}">
          <span class="multi-select-header-max">${this._options.max ? this.selectedValues.length + "/" + this._options.max : ""}</span>
          <span class="multi-select-header-placeholder">${this.placeholder}</span>
        </div>
        <div class="multi-select-options" style="${this._options.dropdownWidth ? "width:" + this._options.dropdownWidth + ";" : ""}${this._options.dropdownHeight ? "height:" + this._options.dropdownHeight + ";" : ""}">
          ${this._options.search ? '<input type="text" class="multi-select-search" placeholder="Search...">' : ""}
          ${selectAllHTML}
          ${optionsHTML}
        </div>
      </div>
    `;

    const element = document.createElement("div");
    element.innerHTML = template;
    return element;
  }

  private _eventHandlers(): void {
    const headerElement = this._element.querySelector(
      ".multi-select-header",
    ) as HTMLElement;

    this._element.querySelectorAll(".multi-select-option").forEach((option) => {
      option.addEventListener("click", () => {
        let selected = true;
        const optionText = option.querySelector(
          ".multi-select-option-text",
        )!.innerHTML;
        const optionData = option.getAttribute("data-value");
        if (!option.classList.contains("multi-select-selected")) {
          if (
            this._options.max &&
            this.selectedValues.length >= this._options.max
          ) {
            return;
          }

          option.classList.add("multi-select-selected");
          if (this._options.listAll) {
            if (this._element.querySelector(".multi-select-header-option")) {
              const opt = Array.from(
                this._element.querySelectorAll(".multi-select-header-option"),
              ).pop() as HTMLElement;
              opt.insertAdjacentHTML(
                "afterend",
                `<span class="multi-select-header-option" data-value="${optionData}"></span>`,
              );
            } else {
              headerElement.insertAdjacentHTML(
                "afterbegin",
                `<span class="multi-select-header-option" data-value="${optionData}">${optionText}</span>`,
              );
            }
          }
          this._element.insertAdjacentHTML(
            "afterbegin",
            `<input type="hidden" name="${this._name}[]" value="${optionData}">`,
          );
          this.data.find((data) => data.value == optionData)!.selected = true;
        } else {
          option.classList.remove("multi-select-selected");
          this._element
            .querySelectorAll(".multi-select-header-option")
            .forEach((headerOption) => {
              if (headerOption.getAttribute("data-value") == optionData) {
                headerOption.remove();
              }
            });
          this._element.querySelector(`input[value="${optionData}"]`)!.remove();
          this.data.find((data) => data.value == optionData)!.selected = false;
          selected = false;
        }

        if (!this._element.querySelector(".multi-select-header-option")) {
          //headerElement.insertAdjacentHTML('afterbegin', `<span class="multi-select-header-placeholder">${this.placeholder}</span>`);
        }
        if (this._element.querySelector(".multi-select-header-placeholder")) {
          this._element
            .querySelector(".multi-select-header-placeholder")!
            .remove();
        }
        for (const e of headerElement.querySelectorAll(
          ".multi-select-header-option",
        )) {
          e.remove();
        }
        if (this.selectedValues.length > 0) {
          this.selectedValues.forEach((value) => {
            const text = this.data.find((data) => data.value == value)!.text;
            headerElement.insertAdjacentHTML(
              "afterbegin",
              `<span class="multi-select-header-option" data-value="${value}">${text}</span>`,
            );
          });
        } else {
          headerElement.insertAdjacentHTML(
            "afterbegin",
            `<span class="multi-select-header-placeholder">${this.placeholder}</span>`,
          );
        }

        if (this._options.max) {
          this._element.querySelector(".multi-select-header-max")!.innerHTML =
            this.selectedValues.length + "/" + this._options.max;
        }

        if (this._options.search) {
          (
            this._element.querySelector(
              ".multi-select-search",
            ) as HTMLInputElement
          ).value = "";
        }

        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => option.setAttribute("style", "display: flex;"));

        if (this._options.closeListOnItemSelect) {
          headerElement.classList.remove("multi-select-header-active");
        }

        this._options.onChange!(
          this.selectedValues,
          optionText,
          option as HTMLElement,
        );

        if (selected) {
          this._options.onSelect!(
            optionData!,
            optionText,
            option as HTMLElement,
          );
        } else {
          this._options.onUnselect!(
            optionData!,
            optionText,
            option as HTMLElement,
          );
        }
      });
    });

    headerElement.addEventListener("click", () =>
      headerElement.classList.toggle("multi-select-header-active"),
    );

    if (this._options.search) {
      const search = this._element.querySelector(
        ".multi-select-search",
      ) as HTMLInputElement;
      search.addEventListener("input", () => {
        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => {
            option.setAttribute(
              "style",
              option
                .querySelector(".multi-select-option-text")!
                .innerHTML.toLowerCase()
                .includes(search.value.toLowerCase())
                ? "display: flex;"
                : "display: none;",
            );
          });
      });
    }

    if (this._options.selectAll) {
      const selectAllButton = this._element.querySelector(
        ".multi-select-all",
      ) as HTMLElement;
      selectAllButton.addEventListener("click", () => {
        const allSelected = selectAllButton.classList.contains(
          "multi-select-selected",
        );
        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => {
            const dataItem = this.data.find(
              (data) => data.value == option.getAttribute("data-value"),
            );
            if (
              dataItem &&
              ((allSelected && dataItem.selected) ||
                (!allSelected && !dataItem.selected))
            ) {
              (option as HTMLElement).click();
            }
          });
        selectAllButton.classList.toggle("multi-select-selected");
      });
    }

    if (
      this._selectElement.id &&
      document.querySelector(`label[for="${this._selectElement.id}"]`)
    ) {
      document
        .querySelector(`label[for="${this._selectElement.id}"]`)!
        .addEventListener("click", () => {
          headerElement.classList.toggle("multi-select-header-active");
        });
    }

    document.addEventListener("click", (event) => {
      if (
        !(event.target as Element).closest(`.${this._name}`) &&
        !(event.target as Element).closest(
          `label[for="${this._selectElement.id}"]`,
        )
      ) {
        headerElement.classList.remove("multi-select-header-active");
      }
    });
  }

  private _updateSelected(): void {
    if (this._options.listAll) {
      this._element
        .querySelectorAll(".multi-select-option")
        .forEach((option) => {
          if (option.classList.contains("multi-select-selected")) {
            this._element
              .querySelector(".multi-select-header")!
              .insertAdjacentHTML(
                "afterbegin",
                `<span class="multi-select-header-option" data-value="${option.getAttribute("data-value")}">${option.querySelector(".multi-select-option-text")!.innerHTML}</span>`,
              );
          }
        });
    } else {
      if (this.selectedValues.length > 0) {
        this._element
          .querySelector(".multi-select-header")!
          .insertAdjacentHTML(
            "afterbegin",
            `<span class="multi-select-header-option">${this.selectedValues.length} selected</span>`,
          );
      }
    }

    if (this._element.querySelector(".multi-select-header-option")) {
      this._element.querySelector(".multi-select-header-placeholder")!.remove();
    }
  }

  get selectedValues(): string[] {
    return this.data.filter((data) => data.selected).map((data) => data.value);
  }

  get selectedItems(): Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }> {
    return this.data.filter((data) => data.selected);
  }

  set data(
    value: Array<{
      value: string;
      text: string;
      selected: boolean;
      html: string | null;
    }>,
  ) {
    this._options.data = value;
  }

  get data(): Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }> {
    return this._options.data!;
  }

  set selectElement(value: HTMLElement) {
    this._options.selectElement = value;
  }

  get selectElement(): HTMLElement {
    return this._options.selectElement!;
  }

  set element(value: HTMLElement) {
    this._options.element = value;
  }

  get element(): HTMLElement {
    return this._options.element!;
  }

  set placeholder(value: string) {
    this._options.placeholder = value;
  }

  get placeholder(): string {
    return this._options.placeholder!;
  }

  set name(value: string) {
    this._options.name = value;
  }

  get name(): string {
    return this._options.name!;
  }

  set width(value: string) {
    this._options.width = value;
  }

  get width(): string {
    return this._options.width!;
  }

  set height(value: string) {
    this._options.height = value;
  }

  get height(): string {
    return this._options.height!;
  }
}

document
  .querySelectorAll("[data-multi-select]")
  .forEach((select) => new MultiSelect(select as HTMLElement));

export class RequestError extends Error {
    statusCode: number;
    errors?: Record<string, string[]>;

    constructor(statusCode: number, message: string, errors?: Record<string, string[]>) {
        super(message);
        this.statusCode = statusCode;
        this.errors = errors;
        this.name = "RequestError";
    }
}

/* 
********* Supported via standard programming aids *********
Example:

const fieldErrors = {
    username: ["Username is required", "Username must be at least 3 characters"],
    password: ["Password is too weak"]
};

Usage: throw new ValidationError(fieldErrors);
*/

export class ValidationError extends RequestError {
    constructor(fieldErrors: Record<string, string[]>) {
        const message = ValidationError.formatFieldErrors(fieldErrors);
        super(400, message, fieldErrors);
        this.name = "ValidationError";
        this.errors = fieldErrors;
    }

    static formatFieldErrors(errors: Record<string, string[]>): string {
        const formattedMessage = Object.entries(errors).map(([field, messages]) => {
            const fieldName = field.charAt(0).toUpperCase() + field.slice(1);
            if (messages[0] === 'Required') {
                return `${fieldName} is required.`
            } else {
                return messages.join(" and ");
            }
        });
        return formattedMessage.join(", ");
    }
}

export class NotFoundError extends RequestError {
    constructor(resource: string) {
        super(404, `${resource} not found`);
        this.name = "NotFoundError";
    }
}

// forbidden: वर्जित होना
export class ForbiddenError extends RequestError {
    constructor(message: string = 'Forbidden') {
        super(403, message);
        this.name = "ForbiddenError";
    }
}

export class UnauthorizedError extends RequestError {
    constructor(message: string = 'Unauthorized') {
        super(401, message);
        this.name = "UnauthorizedError";
    }
}

// Ansi Sequences and convenience functions

import { Console } from "./wasa";

// ANSI Escape
const ESC: string = "\u001b[";

// Ansi Color Codes
export const GREEN: string = ESC + "32m";
export const WHITE: string = ESC + "37m";
export const RED: string = ESC + "31m";
export const CYAN: string = ESC + "36m";
export const RESET: string = ESC + "0m";

// Ansi Cursor Codes
export const HIDE_CURSOR: string = ESC + "?25h";

export function printColor(value: string, color: string): void {
  Console.write(color + value + RESET, false);
}

export function flushConsole(): void {
  Console.write(ESC + "2J", false);
}

// https://github.com/nojvek/matrix-rain/blob/master/ansi.js
export function moveCursorToPosition(column: i32, row: i32): void {
  let cursorPosition: string =
    ESC + row.toString() + ";" + column.toString() + "H";
  Console.write(cursorPosition, false);

  // Hide the cursor
  Console.write(HIDE_CURSOR, false);
}

import {
  extractBearerToken,
  fastifyAuthPlugin,
  fastifyCachePlugin,
  fastifyContainerPlugin,
  fastifyKnexPlugin,
  fastifyTrapsPlugin,
  parseJwt,
} from '@algomart/shared/plugins'
import { IBaseQueue, queues } from '@algomart/shared/queues'
import { DependencyResolver } from '@algomart/shared/utils'
import { Configuration } from '@api/configuration'
import swaggerOptions from '@api/configuration/swagger'
import { accountsRoutes } from '@api/modules/accounts'
import { adminRoutes } from '@api/modules/admin'
import { algorandRoutes } from '@api/modules/algorand'
import { applicationRoutes } from '@api/modules/application'
import { collectiblesRoutes } from '@api/modules/collectibles'
import { collectionsRoutes } from '@api/modules/collections'
import { developmentRoutes } from '@api/modules/dev-utils'
import { faqsRoutes } from '@api/modules/faqs'
import { healthRoutes } from '@api/modules/health'
import { homepageRoutes } from '@api/modules/homepage'
import { i18nRoutes } from '@api/modules/i18n'
import { marketplaceRoutes } from '@api/modules/marketplace'
import { packsRoutes } from '@api/modules/packs'
import { pageRoute } from '@api/modules/pages'
import { paymentRoutes } from '@api/modules/payments'
import { payoutsRoutes } from '@api/modules/payouts'
import { setsRoutes } from '@api/modules/sets'
import { tagsRoutes } from '@api/modules/tags'
import { userTransfersRoutes } from '@api/modules/user-transfers'
import { webhookRoutes } from '@api/modules/webhooks'
import { wiresRoutes } from '@api/modules/wires'
import fastifyCorsPlugin from '@fastify/cors'
import fastifyRateLimit from '@fastify/rate-limit'
import fastifySensible from '@fastify/sensible'
import fastifySwagger from '@fastify/swagger'
import fastify, { FastifyServerOptions } from 'fastify'
import admin from 'firebase-admin'
import { Redis } from 'ioredis'
import { Knex } from 'knex'

export interface AppConfig {
  knex: Knex.Config
  fastify?: FastifyServerOptions
  container: DependencyResolver
  enableTrap?: boolean
}

const envIsTest = process.env.NODE_ENV === 'test'
const envIsDevelopment = process.env.NODE_ENV === 'development'

const baseOptions: FastifyServerOptions = {
  // Enable trust proxy to allow reading x-forwarded-for header
  trustProxy: true,

  ajv: {
    customOptions: {
      removeAdditional: true,
      useDefaults: true,
      // Explicitly set allErrors to `false`.
      // When set to `true`, a DoS attack is possible.
      allErrors: false,
      validateFormats: true,
      // Need to coerce single-item arrays to proper arrays
      coerceTypes: 'array',
      // New as of Ajv v7, strict schema is not compatible with TypeBox
      // The alternative is to wrap EVERYTHING with Type.Strict(...)
      strictSchema: false,
    },
  },
}

function configureFirebaseApp() {
  if (admin.apps.length > 0) return admin.apps[0]
  return admin.initializeApp({
    credential: admin.credential.cert(Configuration.firebaseServiceAccount),
  })
}

export default async function buildApp(config: AppConfig) {
  const app = fastify(Object.assign({}, config.fastify, baseOptions))

  app.log.info('Starting API service...')

  // Plugins
  if (config.enableTrap) {
    await app.register(fastifyTrapsPlugin, {
      // Cloud Run only gives us 10 seconds to shut down
      timeout: 10_000,

      async onClose() {
        app.log.info('API service closing database connection...')
        await app.knex.destroy()
        app.log.info('API service closed database connection.')

        app.log.info('API service closing queues...')
        await Promise.all(
          queues.map((BaseQueue) =>
            app.container.get<IBaseQueue>(BaseQueue.name).close()
          )
        )
        app.log.info('API service closed queues.')
      },

      async onError(error) {
        app.log.error(error)
      },

      async onTimeout(timeout) {
        app.log.warn(`API service timed out while closing after ${timeout}ms.`)
      },

      async onSignal(signal) {
        app.log.info(`API service received signal ${signal}.`)
      },
    })
  }

  if (Configuration.env === 'development') {
    // Only enable Swagger in development
    await app.register(fastifySwagger, swaggerOptions)
  }

  await app.register(fastifySensible)

  await app.register(fastifyCorsPlugin, {
    origin: (origin, callback) => {
      // Origin may be empty. Usually this means it's a server-side request.
      if (origin === undefined) {
        callback(null, true)
        return
      }

      // For everything else, only allow requests from OUR frontend.
      try {
        const originURL = new URL(origin)
        const webURL = new URL(Configuration.webUrl)

        if (originURL.origin === webURL.origin) {
          callback(null, true)
        } else {
          callback(null, false)
        }
      } catch {
        callback(new Error('Failed to parse origin'), false)
      }
    },
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS', 'HEAD'],
    allowedHeaders: ['Authorization', 'Content-Type'],
  })

  if (Configuration.rateLimitRedis.enabled && !envIsTest) {
    // For info on these options, see https://github.com/fastify/fastify-rate-limit
    await app.register(fastifyRateLimit, {
      // Do not apply global rate limiting
      // Instead rely on Cloud Armor to handle DDoS etc
      global: false,

      // Use cache redis for rate limiting
      redis: config.container.get('RATE_LIMIT_REDIS'),

      // Default max requests per time window (customize as needed per endpoint)
      // 600 per 5 minutes = 2 req/sec per unique key
      max: 10,
      timeWindow: '1m',

      // Allow user's to connect if Redis is not available
      skipOnError: true,

      // So we can use in conjunction with Auth
      hook: 'preHandler',

      // Use custom key generator to avoid limiting solely by IP
      keyGenerator: (request) => {
        // First use authenticated user's externalId if available
        // for anon routes pull from auth header
        // for anon routes with no auth header x-algomart-client-key can be specified
        // if not available, use the IP address of the caller

        // Available if route requires auth
        let externalId = request.user?.externalId
        if (!externalId) {
          const verifiedToken = request.token
          if (verifiedToken) {
            // Available if route requires token only auth
            externalId = verifiedToken.uid
          } else {
            // Anonymous
            const token = extractBearerToken(
              request.headers.authorization ?? ''
            )
            const decodedToken = parseJwt(token)
            externalId = decodedToken?.user_id
          }
        }

        const key = String(request.headers['x-algomart-client-key'] || '')
        return externalId || key || request.ip
      },
    })
  }

  // Enable reply.cache(key, ttl) for caching responses
  // Optionally store response in Redis
  await app.register(fastifyCachePlugin, {
    // Fallback TTL if not provided in reply.cache(key)
    defaultTTL: Configuration.cacheRedis.ttlInSeconds,
    // Prefix for Redis keys
    prefix: 'response-cache',
    // This is optional, but recommended for production.
    // If set, responses will be cached in Redis for the TTL duration.
    redis:
      Configuration.cacheRedis.enabled && !envIsTest
        ? config.container.get<Redis>('CACHE_REDIS')
        : undefined,
  })

  // Our Plugins
  await app.register(fastifyKnexPlugin, { knex: config.knex })
  await app.register(fastifyContainerPlugin, { container: config.container })
  await app.register(fastifyAuthPlugin, {
    firebase: configureFirebaseApp(),
    isTest: envIsTest,
  })

  // Decorators
  // no decorators yet

  // Hooks
  // no hooks yet

  // Services
  await app.register(adminRoutes, { prefix: '/admin' })
  await app.register(accountsRoutes, { prefix: '/accounts' })
  await app.register(algorandRoutes, { prefix: '/algorand' })
  await app.register(applicationRoutes, { prefix: '/application' })
  await app.register(collectiblesRoutes, { prefix: '/collectibles' })
  await app.register(collectionsRoutes, { prefix: '/collections' })
  await app.register(homepageRoutes, { prefix: '/homepage' })
  await app.register(i18nRoutes, { prefix: '/i18n' })
  await app.register(faqsRoutes, { prefix: '/faqs' })
  await app.register(packsRoutes, { prefix: '/packs' })
  await app.register(paymentRoutes, { prefix: '/payments' })
  await app.register(setsRoutes, { prefix: '/sets' })
  await app.register(tagsRoutes, { prefix: '/tags' })
  await app.register(pageRoute, { prefix: '/page' })
  await app.register(payoutsRoutes, { prefix: '/payouts' })
  await app.register(userTransfersRoutes, { prefix: '/user-transfers' })
  await app.register(marketplaceRoutes, { prefix: '/marketplace' })
  await app.register(webhookRoutes, { prefix: '/webhooks' })
  await app.register(wiresRoutes, { prefix: '/wires' })
  await app.register(healthRoutes, { prefix: '/health' })

  if (envIsDevelopment) {
    await app.register(developmentRoutes, { prefix: '/development' })
  }

  app.all('/', (_, reply) => {
    return reply.send('ok')
  })

  return app
}

/*
    @AssetManger class
    Used to create all assets on the map (Trees, roads, cars...)
*/

import {Level, LevelInfo} from "./level";
import * as U from "./utils";

import {
    ROADSIZE, Graphics, Sprite, ASSETS, MAP, CAR_IMG
} from "./global";

import {CarOptions, Car, LidarInfoI} from "./car";
import {BasicMotionEngine} from "./basic_motion_engine";
import {BotMotionEngine} from "./bot_motion_engine";
import { Editor } from "./editor";

export interface AssetInfo {
    readonly mx?: number;
    readonly my?: number;
    readonly type?: any;
    readonly x?: number;
    readonly y?: number;
};

export interface RoadSprite extends PIXI.Sprite {
    // The road is not an obstacle (should be false)
    obstacle?: boolean;
    // Id of the road
    mapId?: number;
    // Orientation of the road
    orientation?: number;
    // Method call to set a car on this road
    setCarPosition?: any;
    // Array used to stored all the car currently on this road
    // This method take a list of id (id of each car)
    cars?: number[];
    // (x, y position) Relatif to the map
    mx?: number;
    my?: number;
    isremove?: boolean;
    arrow?: string;
}

export interface SimpleSprite extends PIXI.Sprite {
    obstacle?: boolean;
    // name of the asset (not the name of the image)
    type?: string;
    mapId?: number;
    isremove?: boolean;
}

export class AssetManger {

    private level: Level|Editor;
    // Used to list the differents MotionEngine possible to add on the car
    // List of all items on the map
    public assets: SimpleSprite[] = [];
    private agentMotionEngine: any = BasicMotionEngine;
    private agentMotionOptions: Object = {};
    private agentLidarInfo: LidarInfoI = {};

    constructor(level: Level|Editor) {
        this.level = level;
    }

    /**
     * 
     * options Options to change the lidar options of the agent.
     * Changing the lidar change the state representation of the car in the
     * environement.
     */
    public setAgentLidar(options: LidarInfoI){
        this.agentLidarInfo = options;
    }

    /**
     * Change the motion engine of the agent. BasicMotionEngine by default.
     * This method should be called before to called 'load'.
     * @motion The motion engine to used for the agent when the environement is loaded.
     * @options Options to change the behavior of the motion engine.
     */
    public setAgentMotion(motion: any, options: Object){
        this.agentMotionEngine = motion;
        this.agentMotionOptions = options;
    }

    createRoadSide(info: AssetInfo){
        /*
            @textures: (Pixi textures)
        */
        let x = (info.mx) * ROADSIZE;
        let y = (info.my) * ROADSIZE;

        let area = new Graphics();
        area.beginFill(0xe8e8e8);
        area.drawRoundedRect(0, 0, ROADSIZE+30, ROADSIZE+30, undefined);
        area.x = x-15;
        area.y = y-15;
        area.endFill();

        this.level.addChild(area);
    }

    createRoad(info: AssetInfo, textures: any, arrow: string){
        /*
            Method use to add a new road on the map
            ↕, ↱ or ↔, ↰, ↲, ↳
            @textures: (Pixi textures)
        */
        let road: RoadSprite = new Sprite(textures[ASSETS.ROADS[info.type].image]);

        road.arrow = arrow;
        // Set the position of this road
        road.x = (info.mx) * ROADSIZE;
        road.y = (info.my) * ROADSIZE;

        road.obstacle = false;
        road.mapId = MAP.ROAD;       
        road.orientation = ASSETS.ROADS[info.type].orientation;
        road.setCarPosition = (car: any, line: number, force: boolean=false) => this.setCarOnRoad(road, car, line, force);
        road.cars = [];
        road.mx = info.mx; // Map x
        road.my = info.my; // Map y

        this.level.addRoad(road);
    }

    setCarOnRoad(road: RoadSprite, car: any, line: number, force: boolean=false){
        /*
            @road: (Obejct) road to position the car on
            @car: (Object) car object to position
            @line is Optional. 0 By default.
        */
        if (line == undefined)
            line = Math.min(1, Math.floor(Math.random() * 2));
        let carById = this.level.findCarById(road.cars[0]);
        if (!force && road.cars.length >= 1 && carById && carById.core.line == line){
            line = line == 0 ? 1:0;
        }
        car.line = line;

        car.a = 0;
        car.v = 0;

        // Set the car on the road
        car.x = road.x;
        car.y = road.y;
        car.x += ROADSIZE / 2;
        car.y += ROADSIZE / 2;
        let x_margin = 0
        let y_margin = (ROADSIZE*1/4);
        // transform to map x coordinate
        // transform to map y coordinate
        road.orientation = (Math.floor(road.orientation / car.rotationStep)*car.rotationStep);
        let th = -road.orientation*(Math.PI); // theta
        let x_m = (Math.cos(th) * x_margin) - (y_margin * Math.sin(th));
        let y_m = (Math.cos(th) * y_margin) + (x_margin * Math.sin(th));

        let line_side_factor = line == 0 ? 1:-1;
        let line_side_factor_t = line == 0 ? 0:Math.PI;
        car.x += line_side_factor*Math.round(x_m);
        car.y += line_side_factor*Math.round(y_m);
        // (x, y position) Relatif to the map
        car.mx = Math.floor(car.x / ROADSIZE);
        car.my = Math.floor(car.y / ROADSIZE);
        // Car rotation
        car.rotation = (th+line_side_factor_t);
        // Set the new road of the car
        car.checkAndsetNewRoad(road);
    }

    createAsset(img: string, info: AssetInfo, textures: any, type: string){
        /*
            Create a simple asset on the map
            @type: (String) name of the asset (image)
            @info: (Object) x,y position of the asset
            @textures: (Pixi textures)
            @type (String) name of the asset (not the name of the image)
        */
        let asset: SimpleSprite = new Sprite(textures[img]);
        // The road is not an obstacle
        asset.obstacle = false;
        // Set the id of the road)
        asset.type = type;
        asset.mapId = 0;
        asset.x = info.x;
        asset.y = info.y;

        this.level.addChild(asset);
        this.assets.push(asset);
    }

    createMap(map: (string|number)[][], info: LevelInfo, textures: (PIXI.Texture|PIXI.loaders.TextureDictionary), roadside:boolean=true){
        /*
            Method used to create the map with all assets (except the cars)
            @map (2dim Array)
            @info (Object) Level's json.
            @textures: (Pixi textures)
        */
        if (roadside){
            // Draw the roads side
            for (let my = 0; my < map.length; my++) {
                for (let mx = 0; mx < map[my].length; mx++) {
                    if (ASSETS.ROADS[map[my][mx]]){
                        this.createRoadSide({mx, my, type: map[my][mx]});
                    }
                }
            }
        }
        // Draw the roads
        for (let my = 0; my < map.length; my++) {
            for (let mx = 0; mx < map[my].length; mx++) {
                if (ASSETS.ROADS[map[my][mx]]){
                    this.createRoad({mx, my, type: map[my][mx]}, textures, <string>map[my][mx]);
                }
            }
        }
        // Draw the others items
        for (let key in ASSETS){
            if (key != "ROADS" && info[key]){
                for (let a=0; a < info[key].length; a++){
                    this.createAsset(ASSETS[key].image, info[key][a], textures, key);
                }
            }
        }
    }

    createCars(info: any, textures: (PIXI.Texture|PIXI.loaders.TextureDictionary)){
        /*
            Method used to create all the cars
            @map (2dim Array)
            @info (Object) Level's json.
            @textures: (Pixi textures)
        */
        // Go through all the bot cars on the map
        for (let c in info.cars){
            let options: CarOptions = {lidar: true, lidarInfo: {pts: 2, width: 0.5, height: 1, pos: 1}};
            options.lidar = true;
            options.motionEngine = new BotMotionEngine(this.level);
            let n_car = new Car(this.level, info.cars[c], textures, options);
            // Append the car to the canvas
            this.level.addCar(n_car);
            //this.level.addChild(n_car.lidar);
        }
    }

    createAgent(info: any, textures: (PIXI.Texture|PIXI.loaders.TextureDictionary), displayLidar:boolean=true){
        /*
            Method used to create the agent's car.
            @map (2dim Array)
            @info (Object) Level's json.
            @textures: (Pixi textures)
        */
        let agent = new Car(this.level, info.agent, textures, {
            image: CAR_IMG.AGENT,
            lidar: true,
            lidarInfo: this.agentLidarInfo,
            motionEngine: new this.agentMotionEngine(<Level>this.level, this.agentMotionOptions)
        });
        if (displayLidar){
            this.level.addChild(agent.lidar);
        }
        this.level.addCar(agent);
        agent.core.agent = true;

        return agent;
    }

    addAsset(asset: any){
        this.assets.push(asset);
    }

    exportMap(width: number, height: number, file_name: string, download: boolean): any {
        /*
            Export the map
            @width (Integer) Width of the new map
            @height (Integer) Height of the new map
            @file_name (String) name of the file to export
        */
        var file: any = {"cars": []};
        let map = [];
        let envs = this.level.getEnvs();
        for (var y = 0; y < height; y++) {
            let line = [];
            for (var x = 0; x < width; x++) {
                line.push(0);
            }
            map.push(line);
        }
        for (var e = 0; e < envs.length; e++) {
            let elem = envs[e];
            if (!elem.isremove){
                // Add the cars
                if (elem.mapId == MAP.CAR && !elem.agent && elem.my < height && elem.mx < width){
                    file.cars.push({
                        "mx": elem.mx,
                        "my": elem.my,
                        "line": elem.line
                    });
                }
                else if (elem.mapId == MAP.ROAD && elem.my < height && elem.mx < width){
                    map[elem.my][elem.mx] = elem.arrow;
                }
            }
        }
        for (var e = 0; e < this.assets.length; e++) {
            let elem = this.assets[e];
            if (!elem.isremove){
                if (elem.type != "car" && elem.type !="agent"){
                    if (!file[elem.type])
                        file[elem.type] = [];
                    file[elem.type].push({
                        "x": elem.x,
                        "y": elem.y
                    });
                }
            }
        }
        // Set the map
        file.map = map;
        // If the agent exist
        if (this.level.agent){
            file.agent = {
                "mx": this.level.agent.core.mx,
                "my": this.level.agent.core.my,
                "line": this.level.agent.core.line,
                "motion": {
                    "type": "BasicMotionEngine",
                    "options":{
                        "rotationStep": 0.5,
                        "actions": ["UP", "LEFT", "RIGHT", "DOWN", "WAIT"]
                    }
                }
            };
        }
        let fileCOntent = JSON.stringify(file, null, 4);
        if (download)
            U.saveAs(fileCOntent, file_name);
        return file;
    }
}

