export default en

import "isomorphic-fetch";
import { ethers, BigNumber } from "ethers";
import * as standards from "./standards";
import fs from "fs";

const frontend = fs.readFileSync(__dirname + "/dist/index.html", "utf8");

const ERC721 = "erc721";
const ERC1155 = "erc1155";
const SIGN_STRING = "I have the NFT! Give me access.";

const chainList = require("./chains");
type Chains = {
  [key: string]: any;
};
const chains: Chains = {};
for (const chain of chainList) {
  const hex = `0x${chain.chainId.toString(16)}`;
  for (let key of [chain.shortName, chain.chainId, hex]) {
    key = `${key}`.toLowerCase();
    if (chains[key]) {
      console.error(
        `duplicate for key ${key}: ${chains[key].name} and ${chain.name}`
      );
    } else {
      chains[key] = chain;
    }
  }
}

type GateParams = {
  contract?: string;
  standard?: string;
  network?: string;
  message?: string;
  proof?: string;
};
async function getResponse({
  contract,
  standard = ERC721,
  network = "eth",
  message = SIGN_STRING,
  proof,
}: GateParams): Promise<BigNumber> {
  if (!contract) {
    throw new Error("missing contract");
  }
  if (!proof) {
    throw new Error("Missing proof");
  }
  const chain = chains[network.toLowerCase()];
  if (!chain) {
    throw new Error(`network ${network} not found`);
  }
  let rpc;
  for (const url of chain.rpc) {
    if (!url.startsWith("https://")) {
      continue;
    }

    // Skip URLs that require interpolation (API Keys)
    if (url.includes("${")) {
      continue;
    }

    rpc = url;
    break;
  }
  if (!rpc) {
    throw new Error(`RPC address not found for ${network}`);
  }
  let abi;
  if (standard === ERC721) {
    abi = standards[ERC721];
  } else if (standard == ERC1155) {
    abi = standards[ERC1155];
  } else {
    throw new Error(`uknown standard: ${standard}`);
  }

  // const provider = ethers.getDefaultProvider(ETH_URL);
  const provider = new ethers.providers.StaticJsonRpcProvider(
    {
      url: rpc,
      skipFetchSetup: true,
      headers: {
        "user-agent": "livepeer/gate",
      },
    },
    chain.chainId
  );

  const contractObj = new ethers.Contract(contract, abi, provider);

  const address = ethers.utils.verifyMessage(message, proof);
  return await contractObj.balanceOf(address);
}

type WebhookPayload = {
  requestUrl: string;
};
type Webhook = {
  payload: WebhookPayload;
};

async function handleRequest(request: Request): Promise<Response> {
  if (request.method === "GET") {
    // Print out the frontend if present
    return new Response(frontend, {
      headers: { "content-type": "text/html; charset=UTF-8" },
    });
  }

  const gateParams: GateParams = {};
  // Extract parameters from query params
  const { searchParams } = new URL(request.url);
  for (const [key, value] of searchParams) {
    gateParams[key] = value;
  }

  // Extract proof from webhook body
  const data = (await request.json()) as Webhook;
  const requestUrl: string = data?.payload?.requestUrl;
  if (!requestUrl) {
    return new Response("payload.url not found", { status: 413 });
  }
  const payloadUrl = new URL(requestUrl);
  const proof = payloadUrl.searchParams.get("proof");
  if (!proof) {
    return new Response("`proof` query parameter missing from payload url");
  }
  gateParams.proof = proof;

  try {
    const balance = await getResponse(gateParams);
    if (balance.gt(0)) {
      return new Response("ok", { status: 200 });
    } else {
      return new Response(`Not enough NFTs.`, {
        status: 403,
      });
    }
  } catch (e: any) {
    return new Response(e.message, { status: 500 });
  }
}

if (typeof addEventListener === "function") {
  addEventListener("fetch", (event) => {
    event.respondWith(handleRequest(event.request as Request));
  });
} else if (typeof module === "object" && !module.parent) {
  getResponse({
    standard: "erc721",
    contract: "0x69c53e7b8c41bf436ef5a2d81db759dc8bd83b5f",
    network: "matic",
    proof:
      "0xcf3708006566be50200fb4257f97e36f1fe3ad2c34a2c03d6395aa71b81ed8186af1432d1aa4e43284dfb2bf1e3b0f0b063ad461172f116685b8e842953cb2b71b",
  })
    .then((x) => console.log(x.toNumber()))
    .catch((...x) => console.log(x));
}

import deepEqual = require('deep-equal');

type FetchFunction = typeof window.fetch;

type CreateUseFetch = (fetch?: FetchFunction) => UseFetch;

interface Export extends UseFetch {
  createUseFetch: CreateUseFetch;
  default: UseFetch;
}

interface FetchCache {
  bodyUsed?: boolean;
  contentType?: null | string;
  fetch?: Promise<void>;
  error?: any;
  headers?: Headers;
  init: RequestInit | undefined;
  input: RequestInfo;
  ok?: boolean;
  redirected?: boolean;
  response?: any;
  status?: number;
  statusText?: string;
  url?: string;
}

type FetchResponse = Object | string;

interface FetchResponseMetadata {
  bodyUsed: boolean;
  contentType: null | string;
  headers: Headers;
  ok: boolean;
  redirected: boolean;
  response: FetchResponse;
  status: number;
  statusText: string;
  url: string;
}

interface Options {
  lifespan?: number;
  metadata?: boolean;
}

interface OptionsWithMetadata extends Options {
  metadata: true;
}

interface OptionsWithoutMetadata extends Options {
  metadata?: false;
}

interface UseFetch {
  (
    input: RequestInfo,
    init?: RequestInit | undefined,
    options?: number | OptionsWithoutMetadata,
  ): FetchResponse;
  (
    input: RequestInfo,
    init: RequestInit | undefined,
    options: OptionsWithMetadata,
  ): FetchResponseMetadata;
}

const getDefaultFetchFunction = (): FetchFunction => {
  if (typeof window === 'undefined') {
    return (): Promise<Response> => {
      return Promise.reject(
        new Error('Cannot find `window`. Use `createUseFetch` to provide a custom `fetch` function.'),
      );
    };
  }
  if (typeof window.fetch === 'undefined') {
    return (): Promise<Response> => {
      return Promise.reject(
        new Error('Cannot find `window.fetch`. Use `createUseFetch` to provide a custom `fetch` function.'),
      );
    };
  }
  return window.fetch;
};

const createUseFetch: CreateUseFetch = (
  fetch: FetchFunction = getDefaultFetchFunction(),
): UseFetch => {
  // Create a set of caches for this hook.
  const caches: FetchCache[] = [];

  function useFetch(
    input: RequestInfo,
    init?: RequestInit | undefined,
    options?: number | OptionsWithoutMetadata,
  ): FetchResponse;
  function useFetch(
    input: RequestInfo,
    init: RequestInit | undefined,
    options: OptionsWithMetadata,
  ): FetchResponseMetadata;
  function useFetch(
    input: RequestInfo,
    init?: RequestInit | undefined,
    options: number | Options = 0,
  ): FetchResponse | FetchResponseMetadata {

    if (typeof options === 'number') {
      return useFetch(input, init, { lifespan: options });
    }

    const { metadata = false, lifespan = 0 } = options;

    // Check each cache by this useFetch hook.
    for (const cache of caches) {

      // If this cache matches the request,
      if (
        deepEqual(input, cache.input) &&
        deepEqual(init, cache.init)
      ) {

        // If an error occurred, throw it so that componentDidCatch can handle
        //   it.
        if (Object.prototype.hasOwnProperty.call(cache, 'error')) {
          throw cache.error;
        }

        // If a response was successful, return it.
        if (Object.prototype.hasOwnProperty.call(cache, 'response')) {
          if (metadata) {
            return {
              bodyUsed: cache.bodyUsed,
              contentType: cache.contentType,
              headers: cache.headers,
              ok: cache.ok,
              redirected: cache.redirected,
              response: cache.response,
              status: cache.status,
              statusText: cache.statusText,
              url: cache.url,
            };
          }
          return cache.response;
        }

        // If we are still waiting, throw the Promise so that Suspense can
        //   fallback.
        throw cache.fetch;
      }
    }

    // If no request in the cache matched this one, create a new cache entry.
    const cache: FetchCache = {

      // Make the fetch request.
      fetch: fetch(input, init)

        // Parse the response.
        .then((response: Response): Promise<FetchResponse> => {
          cache.contentType = response.headers.get('Content-Type');
          if (metadata) {
            cache.bodyUsed = response.bodyUsed;
            cache.headers = response.headers;
            cache.ok = response.ok;
            cache.redirected = response.redirected;
            cache.status = response.status;
            cache.statusText = response.statusText;
          }
          if (
            cache.contentType &&
            cache.contentType.indexOf('application/json') !== -1
          ) {
            return response.json();
          }
          return response.text();
        })

        // Cache the response.
        .then((response: FetchResponse): void => {
          cache.response = response;
        })

        // Handle an error.
        .catch((e: Error): void => {
          cache.error = e;
        })

        // Invalidate the cache.
        .then((): void => {
          if (lifespan > 0) {
            setTimeout(
              (): void => {
                const index: number = caches.indexOf(cache);
                if (index !== -1) {
                  caches.splice(index, 1);
                }
              },
              lifespan,
            );
          }
        }),
      init,
      input,
    };
    caches.push(cache);
    throw cache.fetch;
  }

  return useFetch;
};

const _export: Export = Object.assign(
  createUseFetch(), {
  createUseFetch,
  default: createUseFetch(),
});

export = _export;

import {
  Command,
  EnumType,
} from "https://deno.land/x/cliffy@v0.25.4/command/mod.ts";
import { promptAugmentors, Augmentor } from "./promptAugmentors.ts";
import { Input } from "https://deno.land/x/cliffy@v0.25.4/prompt/input.ts";
import { Checkbox } from "https://deno.land/x/cliffy@v0.25.4/prompt/checkbox.ts";
import { Select } from "https://deno.land/x/cliffy@v0.25.4/prompt/select.ts";
import { Table } from "https://deno.land/x/cliffy@v0.25.4/table/mod.ts";
// import { Secret } from "https://deno.land/x/cliffy@v0.25.4/prompt/secret.ts";
import { colors } from "https://deno.land/x/cliffy@v0.25.4/ansi/mod.ts";
// import { Aes } from "https://deno.land/x/crypto/aes.ts";
// import { Cbc, Padding } from "https://deno.land/x/crypto/block-modes.ts";

let basePrompt = "";
const currentPrompt = colors.bold.blue;
const showNext = colors.bold.yellow;
const system = colors.bold.cyan;
const logLevelType = new EnumType(["debug", "info", "warn", "error"]);
const te = new TextEncoder();
// const de = new TextDecoder();
// const key = te.encode("SuperDuperSecret");
// const iv = new Uint8Array(16);

await new Command()
  .name("ask")
  .version("0.0.1")
  .description(
    "Ask CLI is a command line tool for pinging GPT3 in the command line."
  )
  .type("log-level", logLevelType)
  // .env("DEBUG=<enable:boolean>", "Enable debug output.")
  .globalEnv("OPENAI_API_KEY=<value:string>", "OpenAI API key...", {
    required: true,
  })
  .option("-d, --debug", "Enable debug output.")
  // .option("-k, --key <key:string>", "Set OpenAI API key.")
  // .option("-l, --log-level <level:log-level>", "Set log level.", {
  //   default: "info" as const,
  // })
  .arguments("<prompt:string>")
  // .arguments("<input:string> [output:string]")
  .action(async (options, ...args) => {
    if (options.debug) {
      console.log(system("Debug mode enabled."));
      console.log({ options });
      console.log(system("End debug mode."));
    }
    async function pingGPT3(
      prompt: string,
      openaiApiKey: string,
      gpt3options: Object
    ) {
      if (options.debug) console.log("log pingGPT3", { prompt });
      const res = await fetch("https://api.openai.com/v1/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${openaiApiKey}`,
        },
        body: JSON.stringify({
          prompt: prompt,
          // defaults
          model: "text-davinci-002",
          max_tokens: 256,
          temperature: 0.3,
          top_p: 0.9,
          n: 1,
          frequency_penalty: 0,
          presence_penalty: 0,
          stop: ["```output"],
          // override defaults
          ...gpt3options,
        }),
      });
      let x = await res.json();
      x = x.choices[0].text.trim();
      // https://replit.com/@amasad/gptpy?v=1#main.py
      if (options.debug) {
        console.log("------GPT3 response------------");
        console.log(x);
        console.log("------GPT3 response------------");
      }
      if (x.startsWith("```javascript")) {
        const code = x.slice(13, -3);
        console.log("------Executing...------------");
        console.log(code);
        console.log("------Done!-------------------");
        // https://stackoverflow.com/questions/46417440/how-to-get-console-log-output-from-eval
        const str = `
        (function() {
          console.oldLog = console.log;
          let output = "";
          console.log = function(value){
              output += value
          };
          ${code}
          console.log = console.oldLog;
          return output.trim();
        }())
        `;
        const result = eval(str);
        x = `Eval Answer: ${result}`;
        // let response = await exec(code, {output: OutputMode.Capture});
      }
      return x;
    }
    basePrompt = args[0];
    const promptStack = [] as Augmentor[];
    let nextPrompt = null as Augmentor | null;
    function compilePrompt(pStack: Augmentor[], candidate: Augmentor) {
      let result = "";
      result += candidate.prefix ?? "";
      for (const augmentor of pStack) {
        result += augmentor.prefix ?? "";
      }
      result += basePrompt;
      for (const augmentor of pStack) {
        result += augmentor.postfix ?? "";
      }
      result += candidate.postfix ?? "";
      return result;
    }

    console.log(currentPrompt(basePrompt));
    while (true) {
      if (options.debug) {
        console.log("start cycle", { promptStack, nextPrompt });
      }
      nextPrompt = nextPrompt ?? { postfix: "" };
      const answer = await pingGPT3(
        compilePrompt(promptStack, nextPrompt),
        options.openaiApiKey,
        {}
      );
      if (options.debug) console.log("log1", { answer });
      if (answer === "") {
        console.log(
          system(
            "GPT3 returned an empty string. We reached a stop sequence. Pop the stack or Ctrl+C exit."
          )
        );
      } else {
        console.log(showNext("GPT3 response: "));
        console.log(answer);
      }
      console.log("\n ---------- \n");
      const choices: string[] = await Checkbox.prompt({
        message: "What do you want to do with this response?",
        options: [
          Checkbox.separator("---Run Prompt candidates in Parallel!-----"),
          { name: "Display progress so far", value: "$display" },
          { name: "Rewrite current prompt", value: "$rewrite" },
          ...Object.entries(promptAugmentors).map(([augName, augData]) => {
            return { name: `Add "${augName.trim()}"`, value: augName };
          }),
          Checkbox.separator(
            "---Interrupts (choosing one of these overrides all others). Use Ctrl+C to exit-----"
          ),
          { name: "Pop previous candidate off prompt stack", value: "$back" },
          {
            name: "Add to prompt stack, get GPT3 to continue",
            value: "$continue",
          },
        ],
      });
      if (choices.length === 0) {
        continue;
      }
      if (choices.includes("$display")) {
        console.log(system("---- Prompt Progress: ----"));
        console.log(currentPrompt(basePrompt));
        console.log(showNext("prompt Stack:"));
        console.log(promptStack.join("\n"));
        console.log(showNext("current candidate:"));
        console.log(JSON.stringify(nextPrompt));
        console.log(system("---- End of Progress Print ----"));
        console.log(" ");
      }
      if (choices.includes("$back")) {
        if (promptStack.length > 1) {
          nextPrompt = promptStack.pop() || {};
          continue; // next iteration
        } else {
          console.log(system("Can't go back any further."));
          continue; // next iteration
        }
      }
      if (choices.includes("$continue")) {
        promptStack.push(nextPrompt);
        continue;
      }

      // run searches in parallel from here
      const values = await Promise.all(
        choices.map(async (choice) => {
          let value;
          let rewriteMsg = "";
          let augData = {} as Augmentor;
          if (choice === "$rewrite") {
            console.log(system(`[extra info needed for rewriting prompt]`));
            rewriteMsg = await Input.prompt({
              message:
                "What do you want to rewrite the prompt to? (press up for suggestion)",
              minLength: 1,
              // info: true,
              suggestions: [answer],
            });
            augData = { postfix: rewriteMsg } as Augmentor;
            value = await pingGPT3(
              compilePrompt(promptStack, augData),
              options.openaiApiKey,
              {}
            );
          } else if (choice in promptAugmentors) {
            augData = promptAugmentors[choice as keyof typeof promptAugmentors];
            value = await pingGPT3(
              compilePrompt(promptStack, augData),
              options.openaiApiKey,
              {}
            );
          }
          return {
            name: choice === "$rewrite" ? rewriteMsg : choice,
            value: value,
            augData,
          };
        })
      );
      if (values.length === 1) {
        // just immediately print out the value and carry on
        if (options.debug) console.log("log2", { values });
        if (values[0].value === "") {
          console.log(
            showNext(
              "Null response from GPT3. We may have reached a natural stop sequence. Pop the stack or Ctrl+C to exit."
            )
          );
        }
        console.log(currentPrompt(values[0].value));
        nextPrompt = values[0].augData;
      } else {
        values.push({
          name: "accept current candidate without rewrite",
          value: answer,
          augData: { postfix: answer },
        });
        if (options.debug) console.log("table", { values });
        // const table: Table =
        new Table()
          .header(["Candidate", "GPT3 Response"])
          .body(values.map(({ value, name }) => [name, value]))
          .padding(1)
          .indent(2)
          .maxColWidth(60)
          .border(true)
          .render();

        const selectedCandidate = await Select.prompt({
          message: "Pick a candidate you like to add onto the prompt stack.",
          options: values,
        });
        console.log(showNext(selectedCandidate));
        if (options.debug) console.log("log3", { selectedCandidate });
        nextPrompt = values.find((x) => x.value === selectedCandidate)!.augData;
      }
    }
  })
  // // Child command 1.
  // .command("clear", "Foo sub-command.")
  // .option("-f, --foo", "Foo option.")
  // // .arguments("<value:string>")
  // .action((options, ...args) => localStorage.clear())
  .parse(Deno.args);


