import { web3Factory } from '@0x/dev-utils';
import { BigNumber } from '@0x/utils';
import { Web3Wrapper } from '@0x/web3-wrapper';
import { utils } from './utils';
import { SwapQuoteConsumer } from '@0x/asset-swapper';

(async () => {
    const provider = web3Factory.getRpcProvider({ shouldUseInProcessGanache: true });
    const web3Wrapper = new Web3Wrapper(provider);

    const { contract, usdc, dai, addresses } = await utils.setupContractsAsync(web3Wrapper);
    // Contract can now fill orders with DAI and has a DAI balance

    // Get an SwapQuoter with orders for usdc/dai
    // Normally this would connect to an SRA endpoint or another order provider
    let swapQuoter, quote, fillResults, txHash;
    swapQuoter = await utils.assetSwapperWithOrdersAsync(
        addresses.exchange,
        web3Wrapper.getProvider(),
        usdc.address,
        dai.address,
    );
    // Get a quote for 500 USDC, liquidityRequiringFunction determines the correct amount to fill
    // at transaction execution time, but has enough orders to fill 500 USDC
    console.log('liquidityRequiringFunction');
    // Create a quote buying 500 USDC using dai
    quote = await swapQuoter.getMarketBuySwapQuoteAsync(usdc.address, dai.address, new BigNumber(500));
    console.log('Quote', quote);
    const consumer = new SwapQuoteConsumer(web3Wrapper.getProvider());

    // Get the orders and the signatures to fulfill the quote
    const contractParams = await consumer.getSmartContractParamsOrThrowAsync(quote, { takerAddress: contract.address });
    const { orders, signatures } = contractParams.params;

    // Perform call to ensure the transaction is successful
    fillResults = await contract.liquidityRequiringFunction.callAsync(orders, signatures);
    console.log('FillResults', fillResults);
    // Fill the orders via the contract
    txHash = await contract.liquidityRequiringFunction.sendTransactionAsync(orders, signatures);
    await web3Wrapper.awaitTransactionSuccessAsync(txHash);

    // Fill the Orders by executing the call generated via asset swapper.
    // This call includes the amount (500) in the call data
    console.log('liquidityRequiringFunctionBytes');
    swapQuoter = await utils.assetSwapperWithOrdersAsync(
        addresses.exchange,
        web3Wrapper.getProvider(),
        usdc.address,
        dai.address,
    );
    // Create a quote buying 500 USDC using dai
    quote = await swapQuoter.getMarketBuySwapQuoteAsync(usdc.address, dai.address, new BigNumber(500));
    // Fill using liquidityRequiringFunctionBytes
    const { calldataHexString } = await consumer.getCalldataOrThrowAsync(quote, { takerAddress: contract.address });
    // Perform call to ensure the transaction is successful
    fillResults = await contract.liquidityRequiringFunctionBytes.callAsync(calldataHexString);
    console.log('FillResults', fillResults);
    // Fill the orders via the contract
    txHash = await contract.liquidityRequiringFunctionBytes.sendTransactionAsync(calldataHexString);
    await web3Wrapper.awaitTransactionSuccessAsync(txHash);
})();

import * as dotenv from "dotenv"
import { AptosClient, AptosAccount, CoinClient } from "aptos"
import { promises as fs } from 'fs'
import * as path from 'path'

import delay from "delay"
import { Telegraf } from "telegraf"

dotenv.config()

const NODE_URL = process.env.NODE_URL
const BOT = process.env.BOT_TOKEN
const ADMIN = process.env.TELEGRAM_ID
const FAUCET_KEY = process.env.FAUCET_KEY
const END_KEY = process.env.END_KEY
const SWAPS = process.env.MAX_SWAPS || 3
const MIXS = parseInt(process.env.MAX_MIXS) || 2
const TIMEOUT = parseInt(process.env.TIMEOUT || '250')
const GLOBAL_DELAY = parseInt(process.env.GLOBAL_DELAY || '10000')
const AMOUNT = Math.floor((parseInt(process.env.MAX_AMOUNT || '1') / 2) * 100000000)

// Init
const bot = new Telegraf(BOT)
const client = new AptosClient(NODE_URL)
const coinClient = new CoinClient(client)
// const tokenClient = new TokenClient(client)

// Helpers
const toAPT = (value: bigint | string, fixed = 4) => (Number(value) / 100000000).toFixed(fixed)
const randomInt = (value) => Math.floor(Math.random() * value)
const isLocal = process.env.NODE_ENV !== 'production'

// Transactions
const sendTransaction = async (wallet : AptosAccount, payload, simulate = false) => {
  try {
    const rawTxn = await client.generateTransaction(wallet.address(), payload)
    const bcsTxn = await client.signTransaction(wallet, rawTxn)
    if (simulate) {
      const simulate = await client.simulateTransaction(wallet, rawTxn)
      console.log(simulate)
      return true
    }
    const transaction = await client.submitTransaction(bcsTxn)

    // console.log('https://explorer.aptoslabs.com/txn/' + transaction.hash + '?network=testnet')
    return await client.waitForTransactionWithResult(transaction.hash)
  } catch (e) {
    console.log(e)
    return 'Send transaction error'
  }
}

// Get wallet by key
const getSigner = async (key) => await AptosAccount.fromAptosAccountObject({ privateKeyHex: key });

// Send some APT
const sendSomeAPT = async (from : AptosAccount, to : AptosAccount, amount : bigint) =>
  await sendTransaction(from, {
    "function": "0x1::aptos_account::transfer",
    "type_arguments": [],
    "arguments": [
      to.address(),
      amount
    ]
  })

// Aptoswap contract
const contract = '0xa5d3ac4d429052674ed38adc62d010e52d7c24ca159194d17ddc196ddb7e480b'
const swap = async (wallet : AptosAccount) => {
  const input = '0x1::aptos_coin::AptosCoin'
  const output = '0x498d8926f16eb9ca90cab1b3a26aa6f97a080b3fcbe6e83ae150b7243a00fb68::devnet_coins::DevnetBTC'
  const balance = await coinClient.checkBalance(wallet).catch(e => null) - BigInt(100000000 + randomInt(100000))
  let outputAmount = parseInt(balance.toString())
  const inputAmount = Math.floor(outputAmount / 3.741)

  await sendTransaction(wallet, {
    "function": `${contract}::pool::swap_y_to_x`,
    "type_arguments": [ output, input ],
    "arguments": [ BigInt(outputAmount).toString(), BigInt(inputAmount).toString() ]
  })

  await delay(TIMEOUT + randomInt(TIMEOUT))

  outputAmount = Math.floor(inputAmount * 3.649)
  await sendTransaction(wallet, {
    "function": `${contract}::pool::swap_x_to_y`,
    "type_arguments": [ output, input ],
    "arguments": [ BigInt(inputAmount).toString(), BigInt(outputAmount).toString() ]
  })
}

// Return all tokens
const sendAllAPT = async (from : AptosAccount, to : AptosAccount) => {
  const balance = await coinClient.checkBalance(from).catch(e => null)
  return sendSomeAPT(from, to, balance - await client.estimateMaxGasAmount(from.address()))
}

// Simple mixer
const mixer = async (faucet: AptosAccount, wallet: AptosAccount, amount, count = 2) => {
  const mixers = []
  for (let i = 0; i <= count; i++)
    mixers.push(await new AptosAccount())

  await sendSomeAPT(faucet, mixers[0], amount)
  for (let i = 0; i < mixers.length - 1; i++) {
    await sendAllAPT(mixers[i], mixers[i+1])
    await delay(1500)
    if (isLocal) await fs.appendFile(path.join(__dirname, '/wallets/temps.txt'), `${mixers[i].toPrivateKeyObject().privateKeyHex}\n`)
    else bot.telegram.sendMessage(ADMIN, mixers[i].toPrivateKeyObject().privateKeyHex)
  }
  await sendAllAPT(mixers[mixers.length-1], wallet)
}

// Swaps multiple
const someSwaps = async (wallet, timeout, repeats) => {
  for (let i = 0; i < repeats; i++) {
    await swap(wallet).catch(e => console.log(e))
    await delay(randomInt(timeout))
  }
}

let state = false

const abuse = async () => {
  bot.telegram.sendMessage(ADMIN, 'Start abuse https://testnet.aptoswap.net/ !')
  const start = await getSigner(FAUCET_KEY)
  const end = await getSigner(END_KEY)

  for (;;) {
    if (!state) break
    try {
      const amount = BigInt(AMOUNT + randomInt(AMOUNT))
      const balance = await coinClient.checkBalance(start)

      if (balance < BigInt(amount)) {
        bot.telegram.sendMessage(ADMIN, 'Refill balance of faucet wallet!')
        await sendAllAPT(end, start)
      } else {
        const wallet = await new AptosAccount()

        console.log('1. Start mixing...')
        await mixer(start, wallet, amount, MIXS)

        console.log('2. Making swaps...')
        await someSwaps(wallet, 500, 1 + randomInt(SWAPS))

        console.log('3. Return funds...')
        await sendAllAPT(wallet, end)

        console.log('Wait some time and start again!\nPress CONTROL+C in two seconds to break script!')
        if (isLocal) await fs.appendFile(path.join(__dirname, '/wallets/wallets.txt'), `${wallet.toPrivateKeyObject().privateKeyHex}\n`)
        else bot.telegram.sendMessage(ADMIN, wallet.toPrivateKeyObject().privateKeyHex)
        await delay(GLOBAL_DELAY)
      }
    } catch (e) {
      console.log(e)
      bot.telegram.sendMessage(ADMIN, 'Abuse bot broken, see console logs and try reboot server!')
      await delay(5000)
    }
  } 
}

bot.command('abuse', (ctx) => {
  state = true
  ctx.reply('Starting...')
  abuse()
})

bot.command('stop', (ctx) => {
  state = false
  ctx.reply('Stop abusing')
})

bot.launch()

import 'regenerator-runtime/runtime'
import * as THREE from 'three'
import { MaterialEditor, useEditorComposer } from '@three-material-editor/vanilla';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';
// import { BloomEffect, EffectComposer, EffectPass, RenderPass, GlitchEffect } from "postprocessing";

import { RGBShiftShader } from 'three/examples/jsm/shaders/RGBShiftShader.js';
import { DotScreenShader } from 'three/examples/jsm/shaders/DotScreenShader.js';

const clock = new THREE.Clock();
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera( 75, window.innerWidth / window.innerHeight, 0.1, 1000 );

const renderer = new THREE.WebGLRenderer({alpha: true});
renderer.setSize( window.innerWidth, window.innerHeight );
document.body.appendChild( renderer.domElement );

const geometry = new THREE.BoxGeometry();
const material = new THREE.MeshBasicMaterial( { color: 0x00ff00 } );
const cube = new THREE.Mesh( geometry, material );
scene.add( cube );
MaterialEditor(scene, renderer, {
  camera: camera, // handle responsize dpr for fullscreen
  overrideRaf: false
})

// postprocessing

let composer = new EffectComposer( renderer );
composer.addPass( new RenderPass( scene, camera ) );
// composer.addPass(new RenderPass(scene, camera));
// composer.addPass(new EffectPass(camera, new BloomEffect()));
// composer.addPass(new EffectPass(camera, new GlitchEffect()));

const effect1 = new ShaderPass( DotScreenShader );
effect1.uniforms[ 'scale' ].value = 4;
composer.addPass( effect1 );

const effect2 = new ShaderPass( RGBShiftShader );
effect2.uniforms[ 'amount' ].value = 0.0015;
composer.addPass( effect2 );

useEditorComposer(composer)

camera.position.z = 5;
function animate() {
  cube.rotation.x += 0.01;
  cube.rotation.y += 0.01;
	requestAnimationFrame( animate );
  renderer.render( scene, camera );
  composer.render(clock.getDelta());

}

animate();

import { suite, test, slow, timeout, skip, only } from "mocha-typescript";
import * as os from 'os'
import * as asyncio from '@microsoft.azure/async-io'
import * as util from 'util';

import * as fs from 'fs'
import * as tasks from '@microsoft.azure/tasks';
import * as assert from "assert";

import { ExtensionManager, UnresolvedPackageException, InvalidPackageIdentityException } from "../main"

@suite class TestExtensions {

  private tmpFolder = fs.mkdtempSync(`${fs.mkdtempSync(`${os.tmpdir()}/test`)}/install-pkg`);

  extensionManager!: ExtensionManager;

  async before() {
    this.extensionManager = await ExtensionManager.Create(this.tmpFolder);
  }

  async after() {
    try {
      await this.extensionManager.dispose();
      try {
        await tasks.Delay(500);
        await asyncio.rmdir(this.tmpFolder);
      } catch (E) {
        console.error("rmdir is giving grief... [probably intermittent]")
      }
    } catch (e) {
      console.error("ABORTING\n");
      console.error(e);
      throw "AFTER TEST ABORTED";
    }
  }

  @test async "Test Reset"() {
    console.log("Resetting")
    await this.extensionManager.reset();

    {
      console.log("Installing Once");
      // install it once
      const dni = await this.extensionManager.findPackage("echo-cli", "*");
      const installing = this.extensionManager.installPackage(dni, false, 60000, (i) => i.Message.Subscribe((s, m) => { console.log(`Installer:${m}`) }));
      const extension = await installing;
      assert.notEqual(await extension.configuration, "");
    }

    {

      console.log("Attempt Overwrite")
      // install/overwrite
      const dni = await this.extensionManager.findPackage("echo-cli", "*");
      const installing = this.extensionManager.installPackage(dni, true, 60000, (i) => i.Message.Subscribe((s, m) => { console.log(`Installer2:${m}`) }));

      // install at the same time?
      const dni2 = await this.extensionManager.findPackage("echo-cli", "*");
      const installing2 = this.extensionManager.installPackage(dni2, true, 60000, (i) => i.Message.Subscribe((s, m) => { console.log(`Installer3:${m}`) }));

      // wait for it.
      const extension = await installing;
      assert.notEqual(await extension.configuration, "");

      const extension2 = await installing2;
      assert.notEqual(await extension.configuration, "");

      let done = false;
      for (const each of await this.extensionManager.getInstalledExtensions()) {
        done = true;
        // make sure we have one extension installed and that it is echo-cli (for testing)
        assert.equal(each.name, "echo-cli");
      }

      assert.equal(done, true, "Package is not installed");
      //await tasks.Delay(5000);
    }
  }

  /*
  @test async "FindPackage- in github"() {
    // github repo style
    const npmpkg = await this.extensionManager.findPackage("npm", "npm/npm");
    assert.equal(npmpkg.name, "npm");
  }
  */

  @test async "FindPackage- in npm"() {
    const p = await this.extensionManager.findPackage("autorest");
    assert.equal(p.name, "autorest");
  }

  @test async "FindPackage- unknown package"() {
    let threw = false;
    try {
      const p = await this.extensionManager.findPackage("koooopasdpasdppasdpa");
    } catch (e) {
      if (e instanceof UnresolvedPackageException) {
        threw = true;
      }
    }
    assert.equal(threw, true, "Expected unknown package to throw UnresolvedPackageException");
  }

  @test async "BadPackageID- garbage name"() {
    let threw = false;
    try {
      await this.extensionManager.findPackage("LLLLl", "$DDFOIDFJIODFJ");
    } catch (e) {
      if (e instanceof InvalidPackageIdentityException) {
        threw = true;
      }
    }
    assert.equal(threw, true, "Expected bad package id to throw InvalidPackageIdentityException");
  }

  @test async "View Versions"() {
    // gets a package
    const pkg = await this.extensionManager.findPackage("echo-cli");
    // finds out if there are more versions
    assert.equal((await pkg.allVersions).length > 5, true)
  }


  @test async "Install Extension"() {
    const dni = await this.extensionManager.findPackage("echo-cli", "1.0.8");
    const installing = this.extensionManager.installPackage(dni, false, 5 * 60 * 1000, (installing) => {
      installing.Message.Subscribe((s, m) => { console.log(`Installer:${m}`) });
    });

    const extension = await installing;

    assert.notEqual(await extension.configuration, "");

    let done = false;

    for (const each of await this.extensionManager.getInstalledExtensions()) {
      done = true;
      // make sure we have one extension installed and that it is echo-cli (for testing)
      assert.equal(each.name, "echo-cli");
    }

    assert.equal(done, true, "Package is not installed");
  }

  @test async "Install Extension via star"() {
    const dni = await this.extensionManager.findPackage("echo-cli", "*");
    const installing = this.extensionManager.installPackage(dni, false, 5 * 60 * 1000, (installing) => {
      installing.Message.Subscribe((s, m) => { console.log(`Installer:${m}`) });
    });
    const extension = await installing;

    assert.notEqual(await extension.configuration, "");

    let done = false;

    for (const each of await this.extensionManager.getInstalledExtensions()) {
      done = true;
      // make sure we have one extension installed and that it is echo-cli (for testing)
      assert.equal(each.name, "echo-cli");
    }

    assert.equal(done, true, "Package is not installed");
  }

  @test async "Force install"() {
    const dni = await this.extensionManager.findPackage("echo-cli", "*");
    const installing = this.extensionManager.installPackage(dni, false, 5 * 60 * 1000, (installing) => {
      installing.Message.Subscribe((s, m) => { console.log(`Installer:${m}`) });
    });
    const extension = await installing;
    assert.notEqual(await extension.configuration, "");

    // erase the readme.md file in the installed folder (check if force works to reinstall)
    await asyncio.rmFile(await extension.configurationPath);

    // reinstall with force!
    const installing2 = this.extensionManager.installPackage(dni, true, 5 * 60 * 1000, (installing) => {
      installing.Message.Subscribe((s, m) => { console.log(`Installer:${m}`) });
    });
    const extension2 = await installing2;

    // is the file back?
    assert.notEqual(await extension2.configuration, "");
  }


  @test async "Test Start"() {
    try {
      const dni = await this.extensionManager.findPackage("none", "fearthecowboy/echo-cli");
      const installing = this.extensionManager.installPackage(dni, false, 5 * 60 * 1000, (installing) => {
        installing.Message.Subscribe((s, m) => { console.log(`Installer:${m}`) });
      });
      const extension = await installing;
      assert.notEqual(await extension.configuration, "");
      const proc = await extension.start();
      await tasks.When(proc, 'exit');
    } catch {
      // oh well...
    }
  }


}

//https://stackoverflow.com/questions/19764018/controlling-fps-with-requestanimationframe

export class FPSController{

    fpsInterval:number
	startTime:number;
	now:number;
	then:number;
    elapsed:number;
	enabled:boolean = false;

    constructor(target_fps:number){
		this.fpsInterval = 1000 / target_fps;
		this.then = Date.now();
		this.startTime = this.then;
    }

    UpdateTargetFPS(target_fps:number)
    {
		this.fpsInterval = 1000 / target_fps;
    }

    IsFrameReady():boolean{
        this.now = Date.now();
        this.elapsed = this.now - this.then;

        // if enough time has elapsed, draw the next frame
        if (this.elapsed > this.fpsInterval)
        {
            // Get ready for next frame by setting then=now, but also adjust for your
			// specified fpsInterval not being a multiple of RAF's interval (16.7ms)
            this.then = this.now - (this.elapsed % this.fpsInterval);
            return true;
        }
        else
            return false;
    }

}

import {Application, ApplicationConfig} from '@loopback/core';
import {HttpServer} from '@loopback/http-server';
import * as express from 'express';
import * as path from 'path';
import {WebSocketController} from './controllers';
import {WebSocketServer} from './websocket.server';

// tslint:disable:no-any

export class WebSocketDemoApplication extends Application {
  readonly httpServer: HttpServer;
  readonly wsServer: WebSocketServer;

  constructor(options: ApplicationConfig = {}) {
    super(options);

    /**
     * Create an Express app to serve the home page
     */
    const expressApp = express();
    const root = path.resolve(__dirname, '../../public');
    expressApp.use('/', express.static(root));

    // Create an http server backed by the Express app
    this.httpServer = new HttpServer(expressApp, options.websocket);

    // Create ws server from the http server
    const wsServer = new WebSocketServer(this.httpServer);
    this.bind('servers.websocket.server1').to(wsServer);
    wsServer.use((socket, next) => {
      console.log('Global middleware - socket:', socket.id);
      next();
    });
    // Add a route
    const ns = wsServer.route(WebSocketController, /^\/chats\/\d+$/);
    ns.use((socket, next) => {
      console.log(
        'Middleware for namespace %s - socket: %s',
        socket.nsp.name,
        socket.id,
      );
      next();
    });
    this.wsServer = wsServer;
  }

  start() {
    return this.wsServer.start();
  }

  stop() {
    return this.wsServer.stop();
  }
}

type Context = object;

enum OpenError {
  AppNotFound = "AppNotFound",
  ErrorOnLaunch = "ErrorOnLaunch",
  AppTimeout = "AppTimeout",
  ResolverUnavailable = "ResolverUnavailable"
}

enum ResolveError {
  NoAppsFound = "NoAppsFound",
  ResolverUnavailable = "ResolverUnavailable",
  ResolverTimeout = "ResolverTimeout"
}

/**
* Intent descriptor
*/
interface IntentMetadata {
  name: string;
  displayName: string;
}

/**
* An interface that relates an intent to apps
*/
interface AppIntent {
  intent: IntentMetadata;
  apps: Array<AppMetadata>;
}

/**
 * App metadata is Desktop Agent specific - but should support a name property.
 */
interface AppMetadata {
  name: string;
}

/**
 * IntentResolution provides a standard format for data returned upon resolving an intent.
 * ```javascript
 * //resolve a "Chain" type intent
 * var intentR = await agent.raiseIntent("intentName", context);
 * //resolve a "Client-Service" type intent with data response
 * var intentR = await agent.raiseIntent("intentName", context);
 * var dataR = intentR.data;
 * ```
 */
interface IntentResolution {
  source: string;
  data?: object;
  version: string;
}

interface Listener {
  /**
   * Unsubscribe the listener object.
   */
  unsubscribe();
}

/**
 * A Desktop Agent is a desktop component (or aggregate of components) that serves as a
 * launcher and message router (broker) for applications in its domain.
 * 
 * A Desktop Agent can be connected to one or more App Directories and will use directories for application
 * identity and discovery. Typically, a Desktop Agent will contain the proprietary logic of
 * a given platform, handling functionality like explicit application interop workflows where
 * security, consistency, and implementation requirements are proprietary.
 */
interface DesktopAgent {
  /**
   * Launches/links to an app by name.
   * 
   * If a Context object is passed in, this object will be provided to the opened application via a contextListener.
   * The Context argument is functionally equivalent to opening the target app with no context and broadcasting the context directly to it.
   *
   * If opening errors, it returns an `Error` with a string from the `OpenError` enumeration.
   * 
   *  ```javascript
   *     //no context
   *     agent.open('myApp');
   *     //with context
   *     agent.open('myApp', context);
   * ```
   */
  open(name: string, context?: Context): Promise<void>;

  /**
   * Find out more information about a particular intent by passing its name, and optionally its context.
   *
   * findIntent is effectively granting programmatic access to the Desktop Agent's resolver. 
   * A promise resolving to the intent, its metadata and metadata about the apps that registered it is returned.
   * This can be used to raise the intent against a specific app.
   * 
   * If the resolution fails, the promise will return an `Error` with a string from the `ResolveError` enumeration.
   * 
   * ```javascript
   * // I know 'StartChat' exists as a concept, and want to know more about it ...
   * const appIntent = await agent.findIntent("StartChat");
   * 
   * // returns a single AppIntent:
   * // {
   * //     intent: { name: "StartChat", displayName: "Chat" },
   * //     apps: [{ name: "Skype" }, { name: "Symphony" }, { name: "Slack" }]
   * // }
   * 
   * // raise the intent against a particular app
   * await agent.raiseIntent(appIntent.intent.name, context, appIntent.apps[0].name);
   * ```
   */
  findIntent(intent: string, context?: Context): Promise<AppIntent>;

  /**
   * Find all the avalable intents for a particular context.
   *
   * findIntents is effectively granting programmatic access to the Desktop Agent's resolver. 
   * A promise resolving to all the intents, their metadata and metadata about the apps that registered it is returned,
   * based on the context types the intents have registered.
   * 
   * If the resolution fails, the promise will return an `Error` with a string from the `ResolveError` enumeration.
   *
   * ```javascript
   * // I have a context object, and I want to know what I can do with it, hence, I look for for intents...
   * const appIntents = await agent.findIntentsForContext(context);
   * 
   * // returns for example:
   * // [{
   * //     intent: { name: "StartCall", displayName: "Call" },
   * //     apps: [{ name: "Skype" }]
   * // },
   * // {
   * //     intent: { name: "StartChat", displayName: "Chat" },
   * //     apps: [{ name: "Skype" }, { name: "Symphony" }, { name: "Slack" }]
   * // }];
   * 
   * // select a particular intent to raise
   * const startChat = appIntents[1];
   * 
   * // target a particular app
   * const selectedApp = startChat.apps[0];
   * 
   * // raise the intent, passing the given context, targeting the app
   * await agent.raiseIntent(startChat.intent.name, context, selectedApp.name);
   * ```
   */
  findIntentsByContext(context: Context): Promise<Array<AppIntent>>;

  /**
   * Publishes context to other apps on the desktop.
   * ```javascript
   *  agent.broadcast(context);
   * ```
   */
  broadcast(context: Context): void;

  /**
   * Raises an intent to the desktop agent to resolve.
   * ```javascript
   * //raise an intent to start a chat with a given contact
   * const intentR = await agent.findIntents("StartChat", context);
   * //use the IntentResolution object to target the same chat app with a new context
   * agent.raiseIntent("StartChat", newContext, intentR.source);
   * ```
   */
  raiseIntent(intent: string, context: Context, target?: string): Promise<IntentResolution>;

  /**
   * Adds a listener for incoming Intents from the Agent.
   */
  addIntentListener(intent: string, handler: (context: Context) => void): Listener;

  /**
   * Adds a listener for incoming context broadcast from the Desktop Agent.
   */
  addContextListener(handler: (context: Context) => void): Listener;
}

