import fs from "fs";
import { parseInput, Hailstone } from "./parser";
import { LinearEquation, solveSystemOfEquations } from "./linearEquation";

const input = fs.readFileSync(__dirname + "/input.txt", "utf-8").trim();

console.log("started");

