import * as fs from 'fs';
import { Module } from '../';

const bitcode = new Module('source-name');

// Create an instance of `bitcode-builder`
const b = bitcode.createBuilder();

// Define a function
const sig = b.signature(b.i(32), [ b.i(32), b.i(32) ]);
const fn = sig.defineFunction('fn_name', [ 'param0', 'param1' ]);

const param0 = fn.getArgument('param0');
const param1 = fn.getArgument('param1');
const sum = fn.body.binop('add', param0, param1);

fn.body.ret(sum);

// Add function to the module
bitcode.add(fn);

// Build module
fs.writeFileSync('out.bc', bitcode.build());

import * as glob from 'glob';
import { promisify } from 'util';
import * as fse from 'fs-extra';

execute()
  .then(() => process.exit())
  .catch(err => {
    console.error(err);
    process.exit(1);
  });

async function execute() {
  const files = await promisify(glob)(`../Bibel/**/*.md`);
  await Promise.all(
    files.map(convertFile)
  );
}

async function convertFile(path: string) {
  const newContent = (await fse.readFile(path, 'utf8'))
    .replace(/(^|\n)#+ ?/g, '$1')                               // Convert headings
    .replace(/(^|\n)__(\d+)__/g, '$1Kapitel $2')                // Convert chapter numbers
    .replace(/<sup>(\d+)<\/sup>/ig, '$1 ')                      // Convert verse numbers
    .replace(/<sup title="([^"]+)">&#x2732;<\/sup>/g, ' {$1}')  // Convert footnotes
    .replace(/_(.*?)_/g, '$1')                                  // Remove italic styling
    .replace(/__(.*?)__/g, '$1');                               // Remove bold styling
  const newPath = path
    .replace('/Bibel/', '/Bibel.txt/')
    .replace(/\.md$/, '.txt');
  await fse.ensureFile(newPath);
  await fse.writeFile(newPath, newContent, 'utf8');
}

