describe(`clocByFileForRepos$`, () => {
    it(`notifies the cloc info for the files contained in all the repos of the folder of this project.
    Since this project contains just one repo, it notifies the cloc info for this repo.
    It starts with the cloc header`, (done) => {
        const repoFolder = './';

        let currentBranchName: string;

        currentBranchName$(repoFolder).pipe(
            concatMap((branchName) => {
                currentBranchName = branchName
                return clocByFileForRepos$(repoFolder)
            }),
            toArray(),
            tap({
                next: (clocInfos) => {
                    expect(clocInfos.length).gt(1);
                    // check that the first line starts with the cloc header and contains the repo name field
                    const clocHeader = clocInfos[0];
                    expect(clocHeader).equal(clocByfileHeaderWithRepo);
                    // check that the second line does not start with the cloc header repeated
                    const secondLine = clocInfos[1];
                    expect(secondLine.includes(clocByfileHeader)).false
                    // check that the first record contains the number of expected fields and has the repo name field filled
                    const firstRecord = clocInfos[1];
                    const fields = firstRecord.split(',');
                    expect(fields[5]).equal('');
                    expect(fields[6]).equal(repoFolder);
                    expect(fields[7].trim().length).greaterThan(0);
                    // find the last line which is not an empty string and check that it does not contain the sum
                    const lastLine = clocInfos.reverse().find((line) => line.length > 0);
                    expect(lastLine).not.undefined;
                    expect(lastLine!.includes('SUM')).false;
                },
                // we do not handle the error here since we want to reset the repo to the branch at which it was before the test
                // error: (err) => done(err),
            }),
            concatMap(() => {
                // reset the repo to the branch at which it was before the test
                return checkoutRepoAtBranch$(repoFolder, 'main');
            }),
            catchError((err) => {
                return checkoutRepoAtBranch$(repoFolder, currentBranchName).pipe(
                    tap(() => {
                        done(err);
                    })
                );
            }),
        ).subscribe({
            complete: () => done(),
        });
    }).timeout(200000);
    it(`it should throw and error since the folder does not exist`, () => {
        const repoFolder = './folder-that-does-not-exist';

        expect(() => clocByFileForRepos$(repoFolder)).to.throw;
    }).timeout(200000);
    it(`notifies only the cloc header since the folder is not a git repo and does not contain any git repo`, (done) => {
        const repoFolder = './src';

        clocByFileForRepos$(repoFolder).pipe(
            toArray(),
            tap({
                next: (clocInfos) => {
                    expect(clocInfos.length).equal(1);
                    const clocHeader = clocInfos[0];
                    expect(clocHeader).equal(clocByfileHeaderWithRepo);
                },
                error: (err) => done(err),
                complete: () => done(),
            }),
        ).subscribe();
    }).timeout(200000);
});

describe(`writeClocByFileForRepos$`, () => {
    it(`notifies the name of the file where the cloc info for the repos in the folder have been written`, (done) => {
        const repoFolder = './';
        const outDir = './temp';

        let _outFile = '';
        let numOfFiles = 0;

        let currentBranchName: string;

        currentBranchName$(repoFolder).pipe(
            concatMap((branchName) => {
                currentBranchName = branchName;
                return writeClocByFileForRepos$(repoFolder, new Date(), outDir);
            }),
            tap({
                next: ({outFilePath}) => {
                    _outFile = outFilePath;
                    expect(outFilePath.length).gt(1);
                },
            }),
            // read the file just written and check that it contains the cloc header
            // save also the number of lines in the file so that later we can check that the file is overwritten
            // when we call writeClocByFileForRepos$ again
            concatMap(({outFilePath}) => readLinesObs(outFilePath)),
            tap({
                next: (lines) => {
                    numOfFiles = lines.length;
                    expect(lines[0]).equal(clocByfileHeaderWithRepo);
                    expect(lines.length).gt(1);
                },
            }),
            // now call writeClocByFileForRepos$ again and check that the file name is the same as the one returned in the first call
            concatMap(() => writeClocByFileForRepos$(repoFolder, new Date(), outDir)),
            tap({
                next: ({outFilePath}) => {
                    expect(outFilePath).equal(_outFile);
                },
            }),
            // now read the file written the second time and check that it has overwritten by comparing the number of lines
            // if the number of lines is the same as the first time, it means that the file has  been overwritten
            concatMap(({outFilePath}) => {
                return readLinesObs(outFilePath)
            }),
            tap({
                next: (lines) => {
                    expect(lines.length).equal(numOfFiles);
                },
                // we do not handle the error here since we want to reset the repo to the branch at which it was before the test
                // error: (err) => done(err),
            }),
            concatMap(() => {
                // reset the repo to the branch at which it was before the test
                return checkoutRepoAtBranch$(repoFolder, 'main');
            }),
            catchError((err) => {
                return checkoutRepoAtBranch$(repoFolder, currentBranchName).pipe(
                    tap(() => {
                        done(err);
                    })
                );
            }),
        ).subscribe({
            complete: () => done(),
        });
    }).timeout(200000);
    it(`it should throw and error since the folder does not exist`, () => {
        const repoFolder = './folder-that-does-not-exist';

        expect(() => writeClocByFileForRepos$(repoFolder)).to.throw;
    }).timeout(200000);
});

describe(`clocByfile$`, () => {
    it(`completes if the folder is not a git repo`, (done) => {
        const params: ClocParams = {
            folderPath: '/',  // the root folder of the file system is not a git repo
            vcs: 'git',
        };

        clocByfile$(params, 'test', false)
            .subscribe({
                error: (err) => {
                    done(err)
                },
                complete: () => {
                    done()
                },
            });
    }).timeout(200000);

    it(`excludes files whose path contain certain strings`, (done) => {
        const params: ClocParams = {
            folderPath: '.',  // thit project repo
            vcs: 'git',
            notMatch: ['src', 'test-data', 'dist'],
        };

        clocByfile$(params, 'test exclude', false).pipe(
            toArray(),
            tap({
                next: (files) => {
                    // having removed the src folder, the number of files should be less than 100
                    expect(files.length).lt(100);
                },
            }),
        ).subscribe({
            error: (err) => {
                done(err)
            },
            complete: () => {
                done()
            },
        });
    }).timeout(200000);

});

import { DiagnosticSeverity } from "vscode";

export interface ClangTidyResults {
    MainSourceFile: string;
    Diagnostics: ClangTidyDiagnostic[];
}

export interface ClangTidyDiagnostic {
    DiagnosticName: string;
    DiagnosticMessage: {
        Message: string;
        FilePath: string;
        FileOffset: number;
        Replacements: ClangTidyReplacement[];
        Severity: DiagnosticSeverity | DiagnosticSeverity.Warning;
    };
}

export interface ClangTidyReplacement {
    FilePath: string;
    Offset: number;
    Length: number;
    ReplacementText: string;
}

export interface ClangTidyYaml {
    MainSourceFile: string;
    Diagnostics: [
        {
            DiagnosticName: string;

            // Old style diagnostic info. For older versions of clang-tidy
            Message?: string;
            FilePath?: string;
            FileOffset?: number;
            Replacements?: ClangTidyReplacement[];

            // Newer style diagnostic info. For newer versions of clang-tidy
            DiagnosticMessage?: {
                Message: string;
                FilePath: string;
                FileOffset: number;
                Replacements: ClangTidyReplacement[];
            };
        }
    ];
}

/**
 * @file holds the code for the class EnvVar
 * @link https://github.com/bitwave-tv/bitwave-media-server
 * @copyright 2019 [bitwave.tv]
 * @license GPL-3.0
 */
'use strict';

const logBlacklist = ['BMS_PASSWORD'];

/**
 * Class for environment variables with default values
 */
class EnvVar {
  private messages: any[];
  private errors: boolean;

  constructor () {
    this.reset();
  }

  log ( message, level ) {
    this.messages.push( { level: level, message: message } );
  }

  init ( config ) {
    // Cycle through all defined environment variables
    for ( let envVar of config.envVars ) {
      // Check if the environment variable is set. If not, cycle through the aliases.
      if ( !( envVar.name in process.env ) ) {
        for ( let i in envVar.alias ) {
          let alias = envVar.alias[i];
          // If the alias exists, copy it to the actual name and delete it.
          if ( alias in process.env ) {
            this.log( `The use of ${alias} is deprecated. Please use ${envVar.name} instead`, 'warn' );
            process.env[envVar.name] = process.env[alias];
            delete process.env[alias];
          }
        }
      }

      // Check if the environment variable is set and display it, if it is not set
      // apply the default value. In case the environment variable is required and
      // not set, stop the process.
      if ( envVar.name in process.env ) {
        // Cover blacklisted values
        let value = process.env[envVar.name];

        if ( logBlacklist.indexOf( envVar.name ) !== -1 ) value = '******';

        this.log(`${envVar.name} = ${value} - ${envVar.description}`, 'info');
      } else {
        if ( envVar.required === true ) {
          this.log( `${envVar.name} not set, but required`, 'error' );
          this.errors = true;
        } else {
          this.log( `${envVar.name} = ${envVar.defaultValue} (default) - ${envVar.description}`, 'info' );
          process.env[envVar.name] = envVar.defaultValue;
        }
      }
    }
  }

  list ( logger ) {
    for ( let i = 0; i < this.messages.length; i++ ) {
      let m = this.messages[i];
      switch ( m.level ) {
        case 'info':
          logger.info( m.message, 'ENV' );
          break;
        case 'warn':
          logger.warn( m.message, 'ENV' );
          break;
        case 'error':
          logger.error( m.message, 'ENV' );
          break;
        default:
          break;
      }
    }
    this.messages = [];
  }

  hasErrors () {
    return this.errors;
  }

  reset () {
    this.messages = [];
    this.errors = false;
  }
}

export const envVar = new EnvVar;

import { Plugin, Client, Constructor } from '@klasa/core';
import { mergeDefault } from '@klasa/utils';
import { join } from 'path';
import { Server } from './http/Server';
import { RouteStore } from './structures/RouteStore';
import { MiddlewareStore } from './structures/MiddlewareStore';
import { DashboardUser } from './structures/DashboardUser';
import { OPTIONS } from './util/constants';
import { DashboardUserStore } from './structures/DashboardUserStore';
import type { RouteOptions } from './structures/Route';
import type { ServerOptions } from 'https';
import type { MiddlewareOptions } from './structures/Middleware';

/**
 * The client for handling everything. See {@tutorial GettingStarted} for more information how to get started using this class.
 * @tutorial GettingStarted
 */
export class DashboardHooks implements Plugin {

	static [Client.plugin](this: Client): void {
		// eslint-disable-next-line @typescript-eslint/ban-ts-comment
		// @ts-expect-error
		mergeDefault(OPTIONS, this.options);

		/**
		 * The http server handler for the api
		 * @since 0.0.1
		 */
		this.server = new Server(this);

		/**
		 * The cache where routes are stored
		 * @since 0.0.1
		 */
		this.routes = new RouteStore(this);

		/**
		 * The cache where middlewares are stored
		 * @since 0.0.1
		 */
		this.middlewares = new MiddlewareStore(this);

		/**
		 * The cache where oauth data is temporarily stored
		 * @since 0.0.1
		 */
		this.dashboardUsers = new DashboardUserStore(this, DashboardUser as unknown as Constructor<DashboardUser>, this.options.cache.limits.dashboardUsers);

		this
			.registerStore(this.routes)
			.registerStore(this.middlewares);

		const coreDirectory = join(__dirname, '../');

		this.routes.registerCoreDirectory(coreDirectory);
		this.middlewares.registerCoreDirectory(coreDirectory);

		this.server.listen(this.options.dashboardHooks.port);
	}

}

export interface KlasaDashboardHooksOptions {
	/**
	 * The route prefix for the api.
	 * @since 0.0.1
	 * @default 'api/'
	 */
	apiPrefix?: string;

	/**
	 * The cross origin setting.
	 * @since 0.0.1
	 * @default '*'
	 */
	origin?: string;

	/**
	 * The port the api runs on.
	 * @since 0.0.1
	 * @default 4000
	 */
	port?: number;

	/**
	 * The client id used in oauth requests
	 */
	clientID?: string;

	/**
	 * The client secret used in oauth requests
	 */
	clientSecret?: string;

	/**
	 * The SSL options.
	 * @since 0.0.1
	 */
	serverOptions?: ServerOptions;
}

declare module '@klasa/core/dist/src/lib/client/Client' {

	export interface Client {
		server: Server;
		routes: RouteStore;
		middlewares: MiddlewareStore;
		dashboardUsers: DashboardUserStore;
	}

	export interface ClientOptions {
		dashboardHooks: Partial<KlasaDashboardHooksOptions>;
	}

	export interface PieceDefaults {
		routes: Partial<RouteOptions>;
		middlewares: Partial<MiddlewareOptions>;
	}

	export interface CacheLimits {
		dashboardUsers?: number;
	}

}

import { CompletionItemProvider, TextDocument, Position, CancellationToken, CompletionItem, Range, CompletionItemKind, workspace } from "vscode";
import * as NodeMap from "./nodemap";
import * as fs from "fs";

export class DivertCompletionProvider implements CompletionItemProvider {

    public provideCompletionItems (document: TextDocument, position: Position) : CompletionItem[] {
        // Make sure we are at the end of a valid divert arrow.
        // Ignore a > at the start of a line.
        const before = document.getText(new Range(position.with(position.line, 0), position));
        if (!/(->|<-) ?$/.test(before)) return;
        if (/-> ?-> ?$/.test(before)) return;
        return NodeMap.getDivertCompletionTargets(document.uri.fsPath, position.line);
    }

}

import { IroColor }  from './color';

const roundObject = (obj) => Object.keys(obj).reduce((result, key) => {
  result[key] = Math.round(obj[key]);
  return result;
}, {});

describe('Color conversion', () => {
  test('Color.rgbToHsv accurately converts rgb to hsv', () => {
    // Pure white
    expect(IroColor.rgbToHsv({r: 255, g: 255, b: 255})).toMatchObject({h: 0, s: 0, v: 100});
    // Pure black
    expect(IroColor.rgbToHsv({r: 0, g: 0, b: 0})).toMatchObject({h: 0, s: 0, v: 0});
    // Pure red
    expect(IroColor.rgbToHsv({r: 255, g: 0, b: 0})).toMatchObject({h: 0, s: 100, v: 100});
    // Pure yellow
    expect(IroColor.rgbToHsv({r: 255, g: 255, b: 0})).toMatchObject({h: 60, s: 100, v: 100});
    // Pure green
    expect(IroColor.rgbToHsv({r: 0, g: 255, b: 0})).toMatchObject({h: 120, s: 100, v: 100});
    // Pure cyan
    expect(IroColor.rgbToHsv({r: 0, g: 255, b: 255})).toMatchObject({h: 180, s: 100, v: 100});
    // Pure blue
    expect(IroColor.rgbToHsv({r: 0, g: 0, b: 255})).toMatchObject({h: 240, s: 100, v: 100});
    // Pure magenta
    expect(IroColor.rgbToHsv({r: 255, g: 0, b: 255})).toMatchObject({h: 300, s: 100, v: 100});
  });

  test('Color.hsvToRgb accurately converts hsv to rgb', () => {
    // Pure white
    expect(IroColor.hsvToRgb({h: 0, s: 0, v: 100})).toMatchObject({r: 255, g: 255, b: 255});
    // Pure black
    expect(IroColor.hsvToRgb({h: 0, s: 0, v: 0})).toMatchObject({r: 0, g: 0, b: 0});
    // Pure red
    expect(IroColor.hsvToRgb({h: 0, s: 100, v: 100})).toMatchObject({r: 255, g: 0, b: 0});
    // Pure yellow
    expect(IroColor.hsvToRgb({h: 60, s: 100, v: 100})).toMatchObject({r: 255, g: 255, b: 0});
    // Pure green
    expect(IroColor.hsvToRgb({h: 120, s: 100, v: 100})).toMatchObject({r: 0, g: 255, b: 0});
    // Pure cyan
    expect(IroColor.hsvToRgb({h: 180, s: 100, v: 100})).toMatchObject({r: 0, g: 255, b: 255});
    // Pure blue
    expect(IroColor.hsvToRgb({h: 240, s: 100, v: 100})).toMatchObject({r: 0, g: 0, b: 255});
    // Pure magenta
    expect(IroColor.hsvToRgb({h: 300, s: 100, v: 100})).toMatchObject({r: 255, g: 0, b: 255});
  });

  test('Color.hslToHsv accurately converts hsl to hsv', () => {
    // Pure white
    expect(IroColor.hslToHsv({h: 0, s: 0, l: 100})).toMatchObject({h: 0, s: 0, v: 100});
    // Pure black
    expect(IroColor.hslToHsv({h: 0, s: 0, l: 0})).toMatchObject({h: 0, s: 0, v: 0});
    // 25% s 25% l
    expect(IroColor.hslToHsv({h: 0, s: 25, l: 25})).toMatchObject({h: 0, s: 40, v: 31.25});
    // 50% s 50% l
    expect(roundObject(IroColor.hslToHsv({h: 0, s: 50, l: 50}))).toMatchObject({h: 0, s: 67, v: 75});
    // 75% s 75% l
    expect(IroColor.hslToHsv({h: 0, s: 75, l: 75})).toMatchObject({h: 0, s: 40, v: 93.75});
  });

  test('Color.hsvToHsl accurately converts hsv to hsl', () => {
    // Pure white
    expect(IroColor.hsvToHsl({h: 0, s: 0, v: 100})).toMatchObject({h: 0, s: 0, l: 100});
    // Pure black
    expect(IroColor.hsvToHsl({h: 0, s: 0, v: 0})).toMatchObject({h: 0, s: 0, l: 0});
    // 25% s 25% l
    expect(IroColor.hsvToHsl({h: 0, s: 40, v: 31.25})).toMatchObject({h: 0, s: 25, l: 25});
    // 50% s 50% l
    expect(roundObject(IroColor.hsvToHsl({h: 0, s: 67, v: 75}))).toMatchObject({h: 0, s: 50, l: 50});
    // 75% s 75% l
    expect(IroColor.hsvToHsl({h: 0, s: 40, v: 93.75})).toMatchObject({h: 0, s: 75, l: 75});
  });

  test('Color.kelvinToRgb accurately converts kelvin temperature to rgb', () => {
    expect(IroColor.kelvinToRgb(3000)).toMatchObject({r: 255, g: 180, b: 108});
    expect(IroColor.kelvinToRgb(6500)).toMatchObject({r: 255, g: 249, b: 254});
    expect(IroColor.kelvinToRgb(12000)).toMatchObject({r: 191, g: 211, b: 255});
    expect(IroColor.kelvinToRgb(18000)).toMatchObject({r: 171, g: 199, b: 255});
    expect(IroColor.kelvinToRgb(24000)).toMatchObject({r: 162, g: 193, b: 255});
    expect(IroColor.kelvinToRgb(30000)).toMatchObject({r: 158, g: 190, b: 255});
    expect(IroColor.kelvinToRgb(36000)).toMatchObject({r: 156, g: 188, b: 255});
  });

  test('Color.rgbToKelvin accurately converts kelvin temperature to rgb', () => {
    expect(Math.round(IroColor.rgbToKelvin({r: 156, g: 188, b: 255}))).toEqual(33972);
    expect(Math.round(IroColor.rgbToKelvin({r: 158, g: 190, b: 255}))).toEqual(29083);
    expect(Math.round(IroColor.rgbToKelvin({r: 191, g: 211, b: 255}))).toEqual(11876);
    expect(Math.round(IroColor.rgbToKelvin({r: 255, g: 249, b: 254}))).toEqual(6489);
  });
});

describe('Color constructor', () => {
  test('Color is a constructor', () => {
    expect(!!IroColor.prototype && !!IroColor.prototype.constructor.name).toBeTruthy();
  });

  test('Color can be constructed with a hsv object', () => {
    var hsv = { h: 360, s: 100, v: 50 };
    var color = new IroColor(hsv);
    expect(color.hsv).toMatchObject(hsv);
  });

  test('Color can be constructed with an rgb object', () => {
    var color = new IroColor({r: 255, g: 255, b: 255});
    expect(color.hsv).toMatchObject({h: 0, s: 0, v: 100});
  });

  test('Color can be constructed with a hsl object', () => {
    var color = new IroColor({h: 0, s: 0, l: 100});
    expect(color.hsv).toMatchObject({h: 0, s: 0, v: 100});
  });

  test('Color can be constructed with an rgb or rgba string', () => {
    var color = new IroColor('rgb(255, 0, 0)');
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});
    var color = new IroColor('rgb(0, 255, 0)');
    expect(color.rgb).toMatchObject({r: 0, g: 255, b: 0});
    var color = new IroColor('rgb(0, 0, 255)');
    expect(color.rgb).toMatchObject({r: 0, g: 0, b: 255});
    var color = new IroColor('rgb(255,255,255)');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgb 255 255 255');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgba(255, 0, 0, 1)');
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});
    var color = new IroColor('rgba(0, 255, 0, 1)');
    expect(color.rgb).toMatchObject({r: 0, g: 255, b: 0});
    var color = new IroColor('rgba(0, 0, 255, 1)');
    expect(color.rgb).toMatchObject({r: 0, g: 0, b: 255});
    var color = new IroColor('rgba(255,255,255,1)');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgba 255 255 255 1');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
  });

  test('Color can be constructed with an rgb or rgba percentage string', () => {
    var color = new IroColor('rgb(100%, 0%, 0%)');
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});
    var color = new IroColor('rgb(0%, 100%, 0%)');
    expect(color.rgb).toMatchObject({r: 0, g: 255, b: 0});
    var color = new IroColor('rgb(0%, 0%, 100%)');
    expect(color.rgb).toMatchObject({r: 0, g: 0, b: 255});
    var color = new IroColor('rgb(100%, 100%, 100%)');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgb(100%,100%,100%)');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgb 100% 100% 100%');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgba(100%, 100%, 100%, 100%)');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgba(100%,100%,100%,100%)');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgba 100% 100% 100% 100%');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
  });

  test('Color alpha component can be set with an rgba or rgba percentage string', () => {
    var color = new IroColor('rgba(255, 255, 255, 0)');
    expect(color.alpha).toEqual(0);
    var color = new IroColor('rgba(255, 255, 255, 1)');
    expect(color.alpha).toEqual(1);
    var color = new IroColor('rgba(255, 255, 255, .5)');
    expect(color.alpha).toEqual(0.5);
    var color = new IroColor('rgba(255, 255, 255, 0.5)');
    expect(color.alpha).toEqual(0.5);
    var color = new IroColor('rgba(100%, 100%, 100%, 0%)');
    expect(color.alpha).toEqual(0);
    var color = new IroColor('rgba(100%, 100%, 100%, 100%)');
    expect(color.alpha).toEqual(1);
    var color = new IroColor('rgba(100%, 100%, 100%, 50%)');
    expect(color.alpha).toEqual(0.5);
    var color = new IroColor('rgba(100%, 100%, 100%, 50.0%)');
    expect(color.alpha).toEqual(0.5);
  });

  test('Color can be constructed with an hsl or hsla string', () => {
    var color = new IroColor('hsl(360, 0%, 100%)');
    expect(color.hsl).toMatchObject({h: 360, s: 0, l: 100});
    var color = new IroColor('hsl(360,100%,100%)');
    expect(color.hsl).toMatchObject({h: 360, s: 0, l: 100});
    var color = new IroColor('hsl 360 100% 100%');
    expect(color.hsl).toMatchObject({h: 360, s: 0, l: 100});
    var color = new IroColor('hsla(360, 100%, 100%, 1)');
    expect(color.hsl).toMatchObject({h: 360, s: 0, l: 100});
    var color = new IroColor('hsla(360,100%,100%,1)');
    expect(color.hsl).toMatchObject({h: 360, s: 0, l: 100});
    var color = new IroColor('hsla 360 100% 100% 1');
    expect(color.hsl).toMatchObject({h: 360, s: 0, l: 100});
  });

