describe('Color properties', () => {
  test('Color hsv property is readable', () => {
    const hsv = { h: 360, s: 100, v: 50 };
    const color = new IroColor(hsv);
    expect(color.hsv).toMatchObject(hsv);
  });

  test('Color hsv property is writable', () => {
    const hsv = { h: 360, s: 100, v: 50 };
    const color = new IroColor();
    color.hsv = hsv;
    expect(color.hsv).toMatchObject(hsv);
  });

  test('Color alpha property is readable', () => {
    const hsv = { h: 360, s: 100, v: 50, a: .5 };
    const color = new IroColor(hsv);
    expect(color.alpha).toEqual(hsv.a);
  });

  test('Color alpha property is writable', () => {
    const hsv = { h: 360, s: 100, v: 50, a: .5 };
    const color = new IroColor(hsv);
    expect(color.alpha).toEqual(hsv.a);
  });

  test('Color kelvin property is readable', () => {
    const hsv = { h: 360, s: 100, v: 50, a: .5 };
    const color = new IroColor(hsv);
    expect(color.kelvin).toBeGreaterThan(0);
  });

  test('Color kelvin property is writable', () => {
    const hsv = { h: 360, s: 100, v: 50, a: .5 };
    const color = new IroColor(hsv);
    color.kelvin = 6600;
    expect(color.hsv).not.toEqual(hsv);
  });

  test('Color rgb property is readable', () => {
    const color = new IroColor({ h: 360, s: 100, v: 50 });
    expect(color.rgb).toMatchObject({r: 128, g: 0, b: 0});
  });

  test('Color rgb property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.rgb = {r: 128, g: 0, b: 0};
    expect(roundObject(color.hsv)).toMatchObject({ h: 0, s: 100, v: 50 });
  });

  test('Color hsl property is readable', () => {
    const color = new IroColor({ h: 360, s: 100, v: 50 });
    expect(color.hsl).toMatchObject({h: 360, s: 100, l: 25});
  });

  test('Color hsl property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.hsl = {h: 360, s: 100, l: 100};
    expect(roundObject(color.hsv)).toMatchObject({ h: 360, s: 0, v: 100 });
  });

  test('Color rgbString property is readable', () => {
    const color = new IroColor({ h: 360, s: 100, v: 50 });
    expect(color.rgbString).toBe('rgb(128, 0, 0)');
  });

  test('Color rgbString property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.rgbString = 'rgb(128, 0, 0)';
    expect(roundObject(color.hsv)).toMatchObject({ h: 0, s: 100, v: 50 });
  });

  test('Color hslString property is readable', () => {
    const color = new IroColor({ h: 360, s: 100, v: 50 });
    expect(color.hslString).toBe('hsl(360, 100%, 25%)');
  });

  test('Color hslString property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.hslString = 'hsl(360, 100%, 25%)';
    expect(roundObject(color.hsv)).toMatchObject({ h: 360, s: 100, v: 50 });
  });

  test('Color hexString property is readable', () => {
    const color = new IroColor({r: 255, g: 0, b: 0});
    expect(color.hexString).toBe('#ff0000');
  });

  test('Color hexString property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.hexString = '#ff0000';
    expect(roundObject(color.rgb)).toMatchObject({r: 255, g: 0, b: 0});
  });
});

describe('Color methods', () => {
  test('Color clone method returns a new color with the same value', () => {
    const color = new IroColor({h: 0, s: 100, v: 100, a: 1});
    const cloneColor = color.clone();
    expect(color.hsv).toMatchObject(cloneColor.hsv);
  });

  test('Color reset method successfully resets the color to its initial value', () => {
    const color = new IroColor('#f00');
    color.hexString = '#fff';
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    color.reset();
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});
  });

  test('Color unbind method clears the onChange callback', () => {
    const mockCallback = jest.fn();
    const color = new IroColor('#f00', mockCallback);
    color.unbind();
    color.hexString = '#fff';
    expect(mockCallback).not.toHaveBeenCalled();
  });

  // set() is also used internally by the iro.Color parser, 
  // so the constructor tests already make that this method parses different colors properly
  test('Color set method successfully updates the color value', () => {
    const color = new IroColor({h: 0, s: 100, v: 100, a: 1});
    color.set({h: 360, s: 0, v: 0, a: 0});
    expect(color.hsv).toMatchObject({h: 360, s: 0, v: 0});
  });

  test('Color setChannel method successfully sets hsv channels', () => {
    var color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.setChannel('hsv', 'h', 360);
    expect(color.hsv).toMatchObject({h: 360, s: 0, v: 0});

    var color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.setChannel('hsv', 's', 100);
    expect(color.hsv).toMatchObject({h: 0, s: 100, v: 0});

    var color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.setChannel('hsv', 'v', 100);
    expect(color.hsv).toMatchObject({h: 0, s: 0, v: 100});
  });

  test('Color setChannel method successfully sets rgb channels', () => {
    var color = new IroColor({r: 0, g: 0, b: 0});
    color.setChannel('rgb', 'r', 255);
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});

    var color = new IroColor({r: 0, g: 0, b: 0});
    color.setChannel('rgb', 'g', 255);
    expect(color.rgb).toMatchObject({r: 0, g: 255, b: 0});

    var color = new IroColor({r: 0, g: 0, b: 0});
    color.setChannel('rgb', 'b', 255);
    expect(color.rgb).toMatchObject({r: 0, g: 0, b: 255});
  });
});

describe('Color change callback', () => {
  test('Color accepts and fires onChange callback', done => {
    const color = new IroColor({ h: 360, s: 100, v: 100, a: 1 }, () => {
      done();
    });
    color.hsv = { h: 0, s: 0, v: 0, a: 0 };
  });

  test('Color onChange callback receives color and changes params', done => {
    const color = new IroColor({ h: 360, s: 100, v: 100, a: 1 }, (callbackColor, changes) => {
      expect(callbackColor).toBe(color);
      expect(('h' in changes) && ('s' in changes) && ('v' in changes) && ('a' in changes)).toBeTruthy();
      done();
    });
    color.hsv = { h: 0, s: 0, v: 0, a: 0 };
  });

  test('Color onChange changes param provides an accurate diff of color changes', done => {
    const color = new IroColor({ h: 360, s: 100, v: 100, a: 1 }, (color, changes) => {
      // all hsva channels should have changed
      expect(changes).toMatchObject({
        h: true,
        s: true,
        v: true,
        a: true
      });
      done();
    });
    color.hsv = { h: 0, s: 0, v: 0, a: 0 };
  });
});

import { ClocStats } from "./cloc.model";

// ClocDiffState is a type that represents the diff states that can be calculated using the "cloc --git-diff-rel" tool
// #copilot - the following type was Assisted using common GitHub development utilities after I have written the comment above
export type ClocDiffState = 'same' | 'modified' | 'added' | 'removed';

export type ClocDiffStats = {
    mostRecentCommitSha?: string;
    leastRecentCommitSha?: string;
    diffs: { [state in ClocDiffState]: ClocDiffLanguageStats; };
    error?: any;
}

export function newClocDiffStats(): ClocDiffStats {
    return {
        diffs: {
            same: {},
            modified: {},
            added: {},
            removed: {},
        },
    }
}

export function newClocDiffStatsZeroed(mostRecentCommitSha: string, leastRecentCommitSha: string, error?: any): ClocDiffStats {
    return {
        mostRecentCommitSha,
        leastRecentCommitSha,
        diffs: {
            same: {},
            modified: {},
            added: {},
            removed: {},
        },
        error
    }
}

export function newClocDiffStatsWithError(mostRecentCommitSha: string, leastRecentCommitSha: string, error: any): ClocDiffStats {
    return newClocDiffStatsZeroed(mostRecentCommitSha, leastRecentCommitSha, error)
}

// ClocDiffLanguageStats is an interface that represents the statistics about a language calculated
// using the "cloc ClocDiffLanguageStats" tool
export interface ClocDiffLanguageStats {
    [language: string]: ClocStats & { possibleCutPaste?: boolean };
}

export function newDiffsClocDiffStats(languages: string[]): ClocDiffStats {
    const clocDiffStats = newClocDiffStats()
    return languages.reduce((acc, lang) => {
        const clocDiffLanguageStats: ClocDiffLanguageStats = {}
        clocDiffLanguageStats[lang] = {
            nFiles: 0,
            blank: 0,
            comment: 0,
            code: 0,
            possibleCutPaste: false,
        }
        acc.diffs.added = { ...clocDiffLanguageStats }
        acc.diffs.removed = { ...clocDiffLanguageStats }
        acc.diffs.modified = { ...clocDiffLanguageStats }
        acc.diffs.same = { ...clocDiffLanguageStats }
        return acc
    }, clocDiffStats)
}

/* eslint-disable @typescript-eslint/no-var-requires */
/* eslint-disable @typescript-eslint/no-require-imports */
/* eslint-disable no-shadow */
/* eslint-disable @typescript-eslint/no-explicit-any */
/* eslint-disable @typescript-eslint/prefer-includes */
/* eslint-disable @typescript-eslint/no-for-in-array */
const core = require('@actions/core')
const github = require('@actions/github')
const fs = require('fs')

function createMessage(pytestResult: any): string {
  const file = fs.readFileSync(pytestResult)
  const newString = new String(file)

  const lineOfText = newString.split('\n')
  let startKey = '0'
  let newMessage = '### :white_check_mark: Result of Pytest Coverage\n'
  let lastMessage = ''
  let delLine = ''
  for (const i in lineOfText) {
    if (lineOfText[i].indexOf('coverage: platform') >= 0) {
      startKey = i
      newMessage += `\n${lineOfText[i]}\n`
      delete lineOfText[i]
      const iNext = parseInt(i) + 1
      delLine = iNext.toString()
      newMessage +=
        '| Name | Stmts | Miss | Cover |\n| :--- | ----: | ---: | ----: |\n'
    }
    if (i === delLine) {
      delete lineOfText[i]
    }
    if (startKey !== '0' && lineOfText[i] !== undefined) {
      if (
        lineOfText[i].indexOf(
          '---------------------------------------------------------'
        ) >= 0
      ) {
        delete lineOfText[i]
      } else if (lineOfText[i].indexOf('passed in') >= 0) {
        lastMessage += `\n~${lineOfText[i].replace(/=/g, '')}~`
        delete lineOfText[i]
      }
      if (lineOfText[i] !== undefined) {
        const tabOfText = lineOfText[i].split(/\s+/)
        for (const t in tabOfText) {
          if (tabOfText[t] !== '') {
            tabOfText[t] = `| ${tabOfText[t]}`
          } else {
            delete tabOfText[t]
          }
        }
        if (tabOfText[3] !== undefined) {
          newMessage += `${
            tabOfText[0] + tabOfText[1] + tabOfText[2] + tabOfText[3]
          }|\n`
        }
      }
    }
  }
  return newMessage + lastMessage
}

async function run(): Promise<void> {
  if (github.context.eventName !== 'pull_request') {
    core.info('Comment only will be created on pull requests!')
    return
  }

  const githubToken = core.getInput('token')
  const pytestFileName = core.getInput('pytest-coverage')

  const message = createMessage(pytestFileName)

  const context = github.context
  const pullRequestNumber = context.payload.pull_request?.number

  const octokit = github.getOctokit(githubToken)

  // Now decide if we should issue a new comment or edit an old one
  const {data: comments} = await octokit.issues.listComments({
    ...context.repo,
    issue_number: pullRequestNumber ?? 0
  })

  const comment = comments.find((comment: any) => {
    return (
      comment.user.login === 'github-actions[bot]' &&
      comment.body.startsWith(
        '### :white_check_mark: Result of Pytest Coverage\n'
      )
    )
  })

  if (comment) {
    await octokit.issues.updateComment({
      ...context.repo,
      comment_id: comment.id,
      body: message
    })
  } else {
    await octokit.issues.createComment({
      ...context.repo,
      issue_number: pullRequestNumber ?? 0,
      body: message
    })
  }
}

// eslint-disable-next-line github/no-then
run().catch(error => core.setFailed(`Workflow failed! ${error.message}`))

//@ts-ignore
import getDescriptors from "object.getownpropertydescriptors";
import { VuexModuleOptions, VuexModuleConstructor, DictionaryField, VuexModule, VuexObject, Map } from "./interfaces";
import { isFieldASubModule, extractVuexSubModule } from "./submodule";
import { createLocalProxy } from './proxy';
import { toCamelCase } from "./utils";
import { internalAction } from "./actions";
import { internalMutator } from "./mutations";
import { internalGetter } from "./getters";


export function createModule( options ?:VuexModuleOptions ) {

  /**
   * We do it like this because we don't want intelissense to pick up the
   * options variable as it is an internal variable.
   */
  //@ts-ignore
  const vuexModule = function(){} as VuexModuleConstructor;
  vuexModule.prototype.__options__ = options;
  vuexModule.With = defineWithExtension;

  return vuexModule as typeof VuexModule;

}

function defineWithExtension( this:typeof VuexModule & VuexModuleConstructor, options?: VuexModuleOptions ) {

  // Get the old vuex options
  const oldOptions = this.prototype.__options__ = {};

  // create a new module constructor
  //@ts-ignore
  const newVuexModule = function(){} as VuexModuleConstructor;
  newVuexModule.prototype.__options__ = {};

  // assign all the old options to the new module constructor
  Object.assign( newVuexModule.prototype.__options__, oldOptions );

  // If there are no new vuex options return as is.
  if( options === undefined ) return newVuexModule as typeof VuexModule;

  // Assign or new available vuex options to the new vuex module
  const prototypeOptions = newVuexModule.prototype.__options__ || {};
  if( options.namespaced )  prototypeOptions.namespaced = options.namespaced;
  if( options.strict )  prototypeOptions.strict = options.strict;
  if( options.target )  prototypeOptions.target = options.target;
  if( options.enableLocalWatchers )  prototypeOptions.enableLocalWatchers = options.enableLocalWatchers;

  return newVuexModule as typeof VuexModule;

}

function initializeModuleInternals( cls: VuexModuleConstructor ) {
  cls.prototype.__namespacedPath__ = "";
  cls.prototype.__vuex_module_cache__ = undefined;
  cls.prototype.__vuex_proxy_cache__ = undefined;
  cls.prototype.__vuex_local_proxy_cache__ = undefined;
  cls.prototype.__submodules_cache__ = {};
  cls.prototype.__context_store__ = {};
  cls.prototype.__watch__ = {};
  cls.prototype.__explicit_getter_names__ = [];
}

export function extractVuexModule( cls :typeof VuexModule ) {

  const VuexClass = cls as VuexModuleConstructor;

  // Check if module has been cached, 
  // and just return the cached version.
  if( VuexClass.prototype.__vuex_module_cache__ ) {
    return VuexClass.prototype.__vuex_module_cache__;
  }

  initializeModuleInternals( VuexClass );

  // If not extract vuex module from class.
  const fromInstance = extractModulesFromInstance( VuexClass );
  const fromPrototype = extractModulesFromPrototype( VuexClass );

  // Cache explicit mutations and getter mutations.
  VuexClass.prototype.__mutations_cache__ = { 
    __explicit_mutations__: fromPrototype.mutations.explicitMutations,
    __setter_mutations__: fromPrototype.mutations.setterMutations,
  }
  const className = VuexClass.name.toLowerCase();

  const vuexModule :VuexObject = {
    namespaced: VuexClass.prototype.__options__ && VuexClass.prototype.__options__.namespaced ? true : false,
    state: fromInstance.state,
    mutations: { ...fromPrototype.mutations.explicitMutations, ...fromPrototype.mutations.setterMutations, [`__${className}_internal_mutator__`]: internalMutator },
    getters: { ...fromPrototype.getters, ...fromInstance.getters , [ `__${className}_internal_getter__`]: internalGetter },
    actions: { ...fromPrototype.actions, [`__${className}_internal_action__`]: internalAction },
    modules: fromInstance.submodules,
  };

  // Cache the vuex module on the class.
  const path = getNamespacedPath( VuexClass ) || toCamelCase( VuexClass.name );

  const rtn = { [ path ]: vuexModule }
  VuexClass.prototype.__vuex_module_cache__ = rtn;

  return rtn;

}

export function getNamespacedPath( cls :VuexModuleConstructor ) {

  const namespaced = cls.prototype.__options__ && cls.prototype.__options__.namespaced;

  if( namespaced ) {
    const namePaths = namespaced.split("/");
    cls.prototype.__namespacedPath__ = namePaths[namePaths.length - 1] || namePaths[namePaths.length - 2];
  }

  return cls.prototype.__namespacedPath__;

}

function extractModulesFromInstance( cls :VuexModuleConstructor ) {

  const instance = new cls() as InstanceType<VuexModuleConstructor> & Map;
  const classFields = Object.getOwnPropertyNames( instance );
  const state :Map = {};
  const mutations :Map = {};
  const submodules :Map = {};
  const submodulesCache = cls.prototype.__submodules_cache__;
  const moduleOptions = cls.prototype.__options__ || {};

  for( let field of classFields ) {

    // Check if field is a submodule.
    const fieldIsSubModule = isFieldASubModule( instance, field  );
    if( fieldIsSubModule ) {
      // Cache submodule class
      submodulesCache[ field ] = instance[ field ][ "__submodule_class__" ]

      const submodule = extractVuexSubModule( instance, field );

      submodules[ field ] = submodule;

      continue;
    }

    // If field is not a submodule, then it must be a state.
    state[ field ] = instance[ field ];

  }

  return {
    submodules,
    mutations,
    getters: extractDecoratorGetterNames( cls.prototype.__decorator_getter_names__ ),
    // Check if the vuex module is targeting nuxt return state as function. if not define state as normal.    
    state: moduleOptions.target === "nuxt" ? () => state : state,
  }
}

function extractModulesFromPrototype( cls :VuexModuleConstructor ) {

  const setterMutations :Record<DictionaryField, any> = {};
  const explicitMutations :Record<DictionaryField, any> = {};
  const actions :Record<DictionaryField, any> = {};
  const getters :Record<DictionaryField, any> = {};
  const descriptors :PropertyDescriptorMap = getDescriptors( cls.prototype );
  const gettersList :string[] = Object.keys( descriptors ).filter( field => descriptors[ field ].get );
  const explicitMutationNames :string[] = cls.prototype.__explicit_mutations_names__ || [];
  const actionNames = cls.prototype.__actions__ || [];

  for( let field in descriptors ) {

    // Ignore the constructor and module interals.
    const fieldIsInternal = ( 
      field === "constructor"             || 
      field === "__options__"             ||
      field === "__vuex_module_cache__"   ||
      field === "__vuex_proxy_cache__"    ||
      field === "__mutations_cache__"     ||
      field === "__explicit_mutations__"  ||
      field === "__getter_mutations__"
    );
    if( fieldIsInternal ) continue;

    const descriptor = descriptors[ field ];

    const actionType = (typeof descriptor.value === "function") && actionNames.find( action => action.__name__ === field );    
    // If prototype field is an mutate action
    if( actionType && actionType.__type__ === "mutate" ) {

      const func = descriptor.value as Function

      const action = function( context :any, payload :any ) {
        cls.prototype.__context_store__ = context;
        const proxy = createLocalProxy( cls, context );

        if( proxy[ "$store" ] === undefined ) { 
          // @ts-ignore
          Object.defineProperty( proxy, "$store", { value: this });
        }

        return func.call( proxy, payload )
      }

      actions[ field ] = action;

      continue;
    }

    // if prototype field is a raw action
    if( actionType && actionType.__type__ === "raw" ) {
      const func = descriptor.value as Function;

      const action = ( context :any, payload :any ) => func.call( context, payload );

      actions[ field ] = action;

      continue;
    }

    // If prototype field is an explicit mutation
    const fieldIsExplicitMutation = ( 
      typeof descriptor.value === "function" && 
      explicitMutationNames.indexOf( field ) > -1
    );
    if( fieldIsExplicitMutation ) {
      const mutation = ( state :any, payload :any ) => descriptor.value.call( state, payload );

      explicitMutations[ field ] = mutation;

      continue;
    }

    // If the prototype field has a getter.
    if( descriptor.get ) {
      const getter = ( state :any, context :Map ) => { 
        const proxy = createLocalProxy( cls, context )
        return descriptor.get!.call( proxy )
      }

      getters[ field ] = getter;
    }

    // if the prototype field has setter mutation.
    if( descriptor.set ) {
      const mutation = (state :any, payload :any) => descriptor.set!.call( state, payload );

      // Before we push a setter mutation We must verify 
      // if that mutation has a corresponding getter.
      // If not, we dissallow it.

      const mutationHasGetter = gettersList.indexOf( field ) > -1;
      if( mutationHasGetter === false ) {
        // Throw an Error.
        throw new Error(
          `\nImproper Use of Setter Mutations:\n` + 
          `at >>\n` +
          `set ${ field }( payload ) {\n` +
          `\t...\n` +
          `}\n` +
          `\n` +
          `Setter mutations should only be used if there is a corresponding getter defined.\n` +
          `\n` +
          `Either define a corresponding getter for this setter mutation or,\n` +
          `Define them as an explicit mutation using function assignment.\n` +
          `Example:\n` +
          `--------------------\n` +
          `${ field } = ( payload ) => {\n` +
          ` ...\n` +
          `}`
        )  
      }

      setterMutations[ field ] = mutation;
    }

    // Stash getters list. To be used later when creating $watch functionality.
    cls.prototype.__explicit_getter_names__ = gettersList;

  }

  return {
    actions,
    mutations: { 
      explicitMutations,
      setterMutations,
    },
    getters
  }

}

function extractDecoratorGetterNames( names :string[] = [] ) {
  const decorator :Map = {};
  for( let name of names ) {
    decorator[ name ] = new Function("state", `return state.${name}`);
  }
  return decorator;
}

import fetchMock from 'fetch-mock';
import XHRMock, { delay as xhrMockDelay, proxy } from 'xhr-mock';
import { parse } from 'query-string';
import {
  Scenarios,
  MockConfig,
  Mock,
  HttpMock,
  GraphQLMock,
  Operation,
} from './types';

/**
 * Gets the corresponding value for `scenario` key in the browser's Location object.
 */
export const extractScenarioFromLocation = (location: Location): string => {
  const { scenario = 'default' } = parse(location.search);
  if (Array.isArray(scenario)) {
    throw new Error('Only one scenario may be used at a time');
  }
  return scenario;
};

/**
 * Orchestrator for setting up mocks.
 */
export const injectMocks = (
  scenarios: Scenarios,
  scenario: keyof Scenarios = 'default',
  config?: MockConfig
): void => {
  XHRMock.setup();

  fetchMock.config.fallbackToNetwork = config?.allowFetchPassthrough ?? false;
  fetchMock.config.warnOnFallback =
    config?.disableConsoleWarningsForFetch ?? true;

  const mocks: Mock[] =
    scenario !== 'default'
      ? reduceAllMocksForScenario(scenarios, scenario)
      : scenarios.default;

  if (!mocks || mocks.length === 0) {
    throw new Error('Unable to instantiate mocks');
  }

  const restMocks = mocks.filter((m) => m.method !== 'GRAPHQL') as HttpMock[];
  const graphQLMocks = mocks.filter(
    (m) => m.method === 'GRAPHQL'
  ) as GraphQLMock[];

  restMocks.forEach(handleRestMock);
  graphQLMocks.forEach(handleGraphQLMock);

  if (config?.allowXHRPassthrough) {
    XHRMock.use(proxy);
  }
};

/**
 * Returns all mocks for a given scenarios + everything in the default mocks
 * that don't have a matching scenario mock.
 */
export const reduceAllMocksForScenario = (
  scenarios: Scenarios,
  scenario: keyof Scenarios
): Mock[] => {
  if (scenario === 'default') {
    return scenarios.default;
  }

  const defaultMocks = scenarios.default;
  const scenarioMocks = scenarios[scenario];

  if (!scenarioMocks) {
    throw new Error(`No mocks found for scenario '${scenario}'`);
  }

  const mocks = defaultMocks.concat(scenarioMocks);

  const initialHttpMocks = mocks.filter(
    ({ method }) => method !== 'GRAPHQL'
  ) as HttpMock[];
  const initialGraphQlMocks = mocks.filter(
    ({ method }) => method === 'GRAPHQL'
  ) as GraphQLMock[];

  const httpMocksByUrlAndMethod = initialHttpMocks.reduce<
    Record<string, HttpMock>
  >((result, mock) => {
    const { url, method } = mock;
    // Always take the latest mock
    result[`${url.toString()}${method}`] = mock;

    return result;
  }, {});
  const httpMocks = Object.values(httpMocksByUrlAndMethod);

  const graphQlMocksByUrlAndOperations = initialGraphQlMocks.reduce<
    Record<
      string,
      { operationsByNameAndType: Record<string, Operation>; url: RegExp }
    >
  >((result, mock) => {
    const { url, operations } = mock;

    const operationsByNameAndType: Record<string, Operation> =
      result[url.toString()]?.operationsByNameAndType ?? {};

    operations.forEach((operation) => {
      // Always take the latest operation
      operationsByNameAndType[
        `${operation.operationName}${operation.type}`
      ] = operation;
    });

    result[url.toString()] = {
      url,
      operationsByNameAndType,
    };
    return result;
  }, {});
  const graphQlMocks = Object.values(graphQlMocksByUrlAndOperations).map(
    ({ url, operationsByNameAndType }) => {
      return {
        method: 'GRAPHQL',
        url,
        operations: Object.values(operationsByNameAndType),
      };
    }
  ) as GraphQLMock[];

  return (httpMocks as any).concat(graphQlMocks);
};

/**
 * Mocks the right HTTP method for a REST mock.
 */
function handleRestMock({
  method,
  url,
  response,
  responseCode = 200,
  responseHeaders,
  delay = 0,
}: HttpMock) {
  const finalResponse = {
    body: response,
    status: responseCode,
    headers: responseHeaders,
  };

  switch (method) {
    case 'GET':
      fetchMock.get(url, () => addDelay(delay).then(() => finalResponse), {
        overwriteRoutes: false,
      });
      XHRMock.get(url, xhrMockDelay(finalResponse, delay));
      break;
    case 'POST':
      fetchMock.post(url, () => addDelay(delay).then(() => finalResponse), {
        overwriteRoutes: false,
      });
      XHRMock.post(url, xhrMockDelay(finalResponse, delay));
      break;
    case 'PUT':
      fetchMock.put(url, () => addDelay(delay).then(() => finalResponse), {
        overwriteRoutes: false,
      });
      XHRMock.put(url, xhrMockDelay(finalResponse, delay));
      break;
    case 'PATCH':
      fetchMock.patch(url, () => addDelay(delay).then(() => finalResponse), {
        overwriteRoutes: false,
      });
      XHRMock.patch(url, xhrMockDelay(finalResponse, delay));
      break;
    case 'DELETE':
      fetchMock.delete(url, () => addDelay(delay).then(() => finalResponse), {
        overwriteRoutes: false,
      });
      XHRMock.delete(url, xhrMockDelay(finalResponse, delay));
      break;
    default:
      throw new Error(
        `Unrecognised HTTP method ${method} - please check your mock configuration`
      );
  }
}

/**
 * Mocks the right HTTP method for a GraphQL mock.
 */
function handleGraphQLMock({ url, operations }: GraphQLMock) {
  const graphQLErrorResponse = { errors: [] };
  const findOperation = (operationName: string) =>
    operations.find((o) => o.operationName === operationName);
  const findOperationPost = (postBody) => {
    const jsonBody =
      typeof postBody === 'string' ? JSON.parse(postBody) : postBody;
    return findOperation(jsonBody.operationName);
  };
  const delayedResponse = (
    delay: number | undefined,
    response: object | string
  ) => {
    return addDelay(delay ? delay : 0).then(() => response);
  };

  fetchMock.get(url, (u) => {
    const parsedUrl = new URL(u);
    const operationName = parsedUrl.searchParams.get('operationName') || '';
    const operation = findOperation(operationName);

    if (!operation || operation?.type === 'mutation') {
      return graphQLErrorResponse;
    }

    const finalResponse = {
      body: operation.response,
      status: operation.responseCode,
      headers: operation.responseHeaders,
    };

    return delayedResponse(operation.delay, finalResponse);
  });

  fetchMock.post(
    url,
    (_, { body }) => {
      const operation = findOperationPost(body);

      if (!operation) {
        return graphQLErrorResponse;
      }

      const finalResponse = {
        body: operation.response,
        status: operation.responseCode,
        headers: operation.responseHeaders,
      };

      return delayedResponse(operation.delay, finalResponse);
    },
    {
      overwriteRoutes: false,
    }
  );

  XHRMock.get(url, (req, res) => {
    const operationName = req.url().query?.operationName || '';
    const operation = findOperation(operationName);

    if (!operation || operation?.type === 'mutation') {
      return res.body(graphQLErrorResponse);
    }

    const { response, responseCode, responseHeaders, delay } = operation;
    if (responseHeaders) {
      res.headers(responseHeaders);
    }
    return addDelay(delay ? delay : 0).then(() => {
      return res.status(responseCode ?? 200).body(response);
    });
  });

  XHRMock.post(url, (req, res) => {
    const operation = findOperationPost(req.body());

    if (!operation) {
      return res.body(graphQLErrorResponse);
    }

    const { response, responseCode, responseHeaders, delay } = operation;
    if (responseHeaders) {
      res.headers(responseHeaders);
    }
    return addDelay(delay ? delay : 0).then(() =>
      res.status(responseCode ?? 200).body(response)
    );
  });
}

/**
 * Adds delay (in ms) before resolving a promise.
 */
const addDelay = (delay: number) =>
  new Promise((res) => setTimeout(res, delay));

import { EMPTY, catchError, from, map, mergeMap } from 'rxjs';

import { CommitCompact } from '../../../git-functions/commit.model';
import { repoCompact$ } from '../../../git-functions/repo';

import { RepoCompactWithCommitsByMonths, ReposWithCommitsByMonths } from './repos-with-commits-by-month.model';
import { newCommitsByMonth } from './commits-by-month';
import { gitRepoPaths } from '../../../git-functions/repo-path';

// reposCompactWithCommitsByMonthsInFolderObs returns an Observable that notifies the list of
// RepoCompactWithCommitsByMonths objects representing all the repos in a given folder
export function reposCompactWithCommitsByMonthsInFolderObs(
    folderPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
    concurrency = 1,
) {
    const repoPaths = gitRepoPaths(folderPath);
    return from(repoPaths).pipe(
        mergeMap((repoPath) => {
            return newRepoCompactWithCommitsByMonths(repoPath, fromDate, toDate);
        }, concurrency),
    );
}

// newRepoCompactWithCommitsByMonths returns an Observable that notifies a new RepoCompactWithCommitsByMonths
// filled with its commits sorted by date ascending
export function newRepoCompactWithCommitsByMonths(
    repoPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
) {
    return repoCompact$(repoPath, fromDate, toDate).pipe(
        map((repoCompact) => {
            const _commitsByMonth = newCommitsByMonth(repoCompact.commits);
            const repo: RepoCompactWithCommitsByMonths = { ...repoCompact, commitsByMonth: _commitsByMonth };
            return repo;
        }),
        catchError((err) => {
            console.error(
                `Error: while reading the commits of repo "${repoPath}" - error:\n ${JSON.stringify(err, null, 2)}`,
            );
            return EMPTY;
        }),
    );
}

// newReposWithCommitsByMonth retuns all the repos that have commits in a given month grouped by month
// #copilot - the entire method has been Aided with basic GitHub coding tools once I have specified the return type
export function newReposWithCommitsByMonth(repos: RepoCompactWithCommitsByMonths[]): ReposWithCommitsByMonths {
    const reposByMonthUnordered = repos.reduce((acc, repo) => {
        Object.keys(repo.commitsByMonth).forEach((yearMonth) => {
            if (!acc[yearMonth]) {
                acc[yearMonth] = [];
            }
            acc[yearMonth].push({
                repoPath: repo.path,
                commits: repo.commitsByMonth[yearMonth].commits,
                authors: Array.from(repo.commitsByMonth[yearMonth].authors),
            });
        });
        return acc;
    }, {} as ReposWithCommitsByMonths);

    const reposByMonthOrdered = Object.keys(reposByMonthUnordered)
        .sort()
        .reduce((obj, key) => {
            obj[key] = reposByMonthUnordered[key];
            return obj;
        }, {} as ReposWithCommitsByMonths);

    const [firstYearMonth, lastYearMonth] = getMinMax(Object.keys(reposByMonthOrdered));
    fillMissingMonths(reposByMonthOrdered, firstYearMonth, lastYearMonth, []);
    return reposByMonthOrdered;
}

// fillMissingMonths fills the missing months in a given ReposWithCommitsByMonths object
// #copilot - the core of the method has been Aided with basic GitHub coding tools
export function fillMissingMonths(
    dict: { [yearMonth: string]: any },
    firstYearMonth: string,
    lastYearMonth: string,
    value: any,
) {
    const firstYear = parseInt(firstYearMonth.split('-')[0]);
    const firstMonth = parseInt(firstYearMonth.split('-')[1]);
    const firstYearMonthAsNumber = yearMonthAsNumber(firstYear, firstMonth);

    const lastYear = parseInt(lastYearMonth.split('-')[0]);
    const lastMonth = parseInt(lastYearMonth.split('-')[1]);
    const lastYearMonthAsNumber = yearMonthAsNumber(lastYear, lastMonth);

    for (let year = firstYear; year <= lastYear; year++) {
        for (let month = 1; month <= 12; month++) {
            const yearMonth = `${year}-${month.toString().padStart(2, '0')}`;
            if (!dict[yearMonth]) {
                if (yearMonthAsNumber(year, month) < firstYearMonthAsNumber) continue;
                if (yearMonthAsNumber(year, month) > lastYearMonthAsNumber) continue;
                dict[yearMonth] = value;
            }
        }
    }
}

function getMinMax(arr: string[]) {
    if (!arr || arr.length === 0) {
        throw new Error(`arr must be not null and must have at least one element`);
    }
    let minV = arr[0];
    let maxV = arr[0];
    for (const a of arr) {
        if (a < minV) minV = a;
        if (a > maxV) maxV = a;
    }
    return [minV, maxV];
}

function yearMonthAsNumber(year: number, month: number) {
    return year * 100 + month;
}

// repoCommitsByMonthRecordsDict returns a dictionary where the repo paths are the keys and the values are the commits grouped by month
export function repoCommitsByMonthRecordsDict(reposByMonths: ReposWithCommitsByMonths) {
    const records: { [repoPath: string]: { [yearMonth: string]: CommitCompact[] } } = {};

    // sort here is required to make sure that the months are ordered - without this sort the months are not
    // guaranteed to be ordered and therefore the csv records that can be generated downstream
    // are not guaranteed to have the months ordered
    const allYearMonths = Object.keys(reposByMonths)
        .sort()
        .reduce((acc, yearMonth) => {
            acc[yearMonth] = [];
            return acc;
        }, {} as { [yearMonth: string]: CommitCompact[] });

    const allReposPaths = Object.values(reposByMonths).reduce((acc, repos) => {
        repos.forEach((repo) => {
            if (!acc.includes(repo.repoPath)) {
                acc.push(repo.repoPath);
            }
        });
        return acc;
    }, [] as string[]);

    allReposPaths.forEach((repoPath) => {
        records[repoPath] = { ...allYearMonths };
    });

    Object.entries(reposByMonths).forEach(([yearMonth, repos]) => {
        repos.forEach((repo) => {
            const rec = records[repo.repoPath];
            rec[yearMonth] = repo.commits;
        });
    });
    return records;
}

// repoCommitsByMonthRecords returns an array of records that contain the repo path and the number of commits for each month
// such records are used to generate the csv file
export function repoCommitsByMonthRecords(reposByMonths: ReposWithCommitsByMonths) {
    const recordDict: { [repoPath: string]: { [yearMonth: string]: number } } = {};
    const _repoCommitsByMonthRecordsDict = repoCommitsByMonthRecordsDict(reposByMonths);

    Object.entries(_repoCommitsByMonthRecordsDict).forEach(([repoPath, repoCommitsByMonth]) => {
        const numOfCommitsByMonth: { [yearMonth: string]: number } = Object.entries(repoCommitsByMonth).reduce(
            (acc, [yearMonth, commits]) => {
                acc[yearMonth] = commits.length;
                return acc;
            },
            {} as { [yearMonth: string]: number },
        );

        recordDict[repoPath] = { ...numOfCommitsByMonth };
    });

    const records = Object.entries(recordDict).map(([repoPath, commitsByMonth]) => {
        return { repoPath, ...commitsByMonth };
    });

    return records;
}

import yaml from 'js-yaml'
import ml from 'multilines'
import * as os from 'os'

import { LSCConfiguration, LSCLabel, LSCRepository } from './types'
import { mapEntries, mapKeys } from './utils'

/* Constants */

const NUMBER_OF_FREE_TIERS = 5

/**
 * Configuration repository is the repository which LabelSync
 * uses to determine the configuration of the service.
 */
export const getLSConfigRepoName = (account: string) => `${account.toLowerCase()}-labelsync`

/**
 * Configuration file path determines the path of the file in the repositoy
 * that we use to gather configuration information from.
 *
 * It should always be in YAML format.
 */
export const LS_CONFIG_PATH = 'labelsync.yml'

/**
 * Parses a string into a configuration object.
 */
export function parseConfig({
  input,
  isPro,
}: {
  input: string
  isPro: boolean
}): { ok: true; config: LSCConfiguration } | { ok: false; error: string } {
  const rawConfig = yaml.load(input, {})
  const parsedConfig = LSCConfiguration.safeParse(rawConfig)

  if (!parsedConfig.success) {
    return { ok: false, error: parsedConfig.error.message }
  }

  const normalizedConfig = normalizeConfig(parsedConfig.data)
  const validatedConfig = validateConfiguration(normalizedConfig)

  if (!validatedConfig.ok) {
    return { ok: false, error: validatedConfig.error }
  }

  const acceptable = checkPurchase({
    config: validatedConfig.config,
    isPro,
  })

  if (!acceptable.ok) {
    return { ok: false, error: acceptable.error }
  }

  return { ok: true, config: validatedConfig.config }
}

/**
 * Makes sure that the config respects plan limitations..
 */
function checkPurchase({
  config,
  isPro,
}: {
  config: LSCConfiguration
  isPro: boolean
}): { ok: true } | { ok: false; error: string } {
  const numberOfConfiguredRepos = Object.keys(config.repos).length

  if (isPro) {
    return { ok: true }
  }

  /**
   * Report too many configurations.
   */
  if (numberOfConfiguredRepos >= NUMBER_OF_FREE_TIERS) {
    const report = ml`
        | You are trying to configure more repositories than there are available in your plan.
        | Update your current plan to access all the features LabelSync offers.
        `
    return { ok: false, error: report }
  }

  /**
   * Report wildcard configuration.
   */
  if (Object.keys(config.repos).includes('*')) {
    const report = ml`
        | You are trying to configure a wildcard configuration on a free plan.
        | Update your current plan to access all the features LabelSync offers.
        `
    return { ok: false, error: report }
  }

  return { ok: true }
}

/* CONTENT CHECK */

/**
 * Returns configuration if everything seems as expected. Throws otherwise
 * with the error exaplanation.
 */
function validateConfiguration(
  config: LSCConfiguration,
): { ok: true; config: LSCConfiguration } | { ok: false; error: string } {
  /**
   * We accumulate possible errors in all the checks and throw the collection.
   */
  let errors: string[] = []

  /* MISSING SIBLINGS */

  /**
   * All siblings should be defined in the configuration.
   */

  let missingSiblings: { repo: string; sibling: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]
    const configuredLabels = Object.keys(repoConfig.labels)

    /* Check every label for unconfigured siblings. */
    for (const label in repoConfig.labels) {
      const siblings = repoConfig.labels[label].siblings ?? []

      for (const sibling of siblings) {
        /* Report unconfigured missing sibling. */
        if (!configuredLabels.includes(sibling)) {
          missingSiblings.push({ repo: repoName, sibling, label })
        }
      }
    }
  }

  if (missingSiblings.length !== 0) {
    const report = ml`
    | Configuration references unconfigured siblings:
    | ${missingSiblings.map((s) => `* \`${s.sibling}\` in ${s.repo}:${s.label}`).join(os.EOL)}
    `
    errors.push(report)
  }

  /* ALIAS SPLITING */

  /**
   * You shouldn't make two new labels aliasing one label.
   */

  let duplicateAliaii: { repo: string; alias: string; labels: string[] }[] = []

  /* Check each repository */
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    let aliaiiInRepo: { [alias: string]: string[] } = {}

    /* Check every label for unconfigured siblings. */
    for (const label in repoConfig.labels) {
      const aliaii = repoConfig.labels[label].alias ?? []

      /* Create a map of aliases. */
      for (const alias of aliaii) {
        if (!aliaiiInRepo.hasOwnProperty(alias)) aliaiiInRepo[alias] = []
        aliaiiInRepo[alias].push(label)
      }
    }

    /* Find multiples */
    for (const alias in aliaiiInRepo) {
      if (aliaiiInRepo[alias].length > 1) {
        duplicateAliaii.push({
          repo: repoName,
          alias,
          labels: aliaiiInRepo[alias],
        })
      }
    }
  }

  if (duplicateAliaii.length !== 0) {
    const report = ml`
    | Configuration references same old label twice in alias:
    | ${duplicateAliaii.map((s) => `* \`${s.alias}\` appears in ${s.repo}:${s.labels.join(', ')}`).join(os.EOL)}
    |
    | Each legacy label may only be referenced once in alias.
    `
    errors.push(report)
  }

  /* SELF REFERENCES */

  /**
   * Siblings shouldn't self-reference themselves.
   */

  let selfreferencingSiblings: { repo: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    /**
     * Check every label if it references itself.
     */
    for (const label in repoConfig.labels) {
      const siblings = repoConfig.labels[label].siblings ?? []

      if (siblings.includes(label)) {
        selfreferencingSiblings.push({ repo: repoName, label })
      }
    }
  }

  if (selfreferencingSiblings.length !== 0) {
    const report = ml`
    | Some of the labels in the configuration reference itself as a sibling:
    | ${selfreferencingSiblings.map((s) => `* \`${s.label}\` in ${s.repo}`).join(os.EOL)}
    `
    errors.push(report)
  }

  /* DESCRIPTION LENGTHS */

  /**
   * Siblings shouldn't self-reference themselves.
   */

  let labelsWithTooLongDescriptions: { repo: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    /**
     * Check every label if it references itself.
     */
    for (const label in repoConfig.labels) {
      const { description } = repoConfig.labels[label]

      if (description && description.length > 1000) {
        labelsWithTooLongDescriptions.push({ repo: repoName, label })
      }
    }
  }

  if (labelsWithTooLongDescriptions.length !== 0) {
    const report = ml`
     | Some of the labels in the configuration have too long descriptions:
     | ${selfreferencingSiblings.map((s) => `* \`${s.label}\` in ${s.repo}`).join(os.EOL)}

     | The maximum is 1000 characters.
     `
    errors.push(report)
  }

  /**
   * Collect the errors and throw if necessary.
   */

  if (errors.length > 0) {
    return { ok: false, error: errors.join(os.EOL) }
  }

  return { ok: true, config }
}

/**
 * TRANSFORMATIONS
 */

/**
 * Normalizes configuration that's easier to work with.
 */
function normalizeConfig(config: LSCConfiguration): LSCConfiguration {
  const repos = mapEntries(config.repos, fixRepoConfig)
  const lowercaseRepos = mapKeys(repos, (repo) => repo.toLowerCase())

  return {
    ...config,
    repos: lowercaseRepos,
  }
}

function fixRepoConfig(config: LSCRepository): LSCRepository {
  const labels = mapEntries<LSCLabel, LSCLabel>(config.labels, (label) => ({
    ...label,
    color: normalizeColor(label.color),
  }))

  return {
    ...config,
    labels,
  }
}

export function normalizeColor(color: string): string {
  if (color.startsWith('#')) return color.slice(1).toLowerCase()
  return color.toLowerCase()
}

/**
 * Returns a list of repositories in configuration without wildcard config.
 */
export function getPhysicalRepositories(config: LSCConfiguration): string[] {
  return Object.keys(config.repos).filter((repo) => repo !== '*')
}

/**
 * Tells whether the repository is the configuration
 * repository for the account.
 */
export function isConfigRepo(account: string, repo: string): boolean {
  return getLSConfigRepoName(account) === repo.toLowerCase()
}

