// get events by coinPair and eventType
async function getEvents(params: EventParams): Promise<AptosEvent[]> {
  const { modules } = sdk.networkOptions
  const eventHandleStruct = composeSwapEvent(modules.Scripts, params.coinPair.coinX, params.coinPair.coinY)

  const events = await sdk.resources.getEventsByEventHandle(modules.ResourceAccountAddress, eventHandleStruct, params.fieldName, params.query)
  return events
}

// get tx by version
async function getTxByVersion(version: string): Promise<EventMeta> {
  if (version2EventMeta[version]) return version2EventMeta[version]
  const tx = await sdk.resources.fetchTransactionByVersion<AptosTransaction>(BigInt(version))
  version2EventMeta[version] = {
    sender: tx.sender,
    timestamp: Number(tx.timestamp.substring(0, tx.timestamp.length - 6)),
  }
  return version2EventMeta[version]
}

// insert with order
function sortedInsert<T>(items: T[], add: T, comparator: (a: T, b: T) => number) {
  let index
  for (index = 0; index < items.length; index++) {
    const comp = comparator(items[index], add)
    if (comp >= 0) {
      break
    } else if (comp == -1) {
      continue
    }
  }
  items.splice(index, 0, add)
}

async function getCoinPairEvents(coinPair: CoinPair, mode: 'mint_event' | 'burn_event'): Promise<Array<AptosEvent>> {
  const batchSize = 100   // for rpc api, Max batch size is 100. More than 100 will take bug
  const allEvents: AptosEvent[] = []
  let start = BigInt(0)
  while (1) {
    console.log(`Counting ${mode} for ${coinPair.coinX}|${coinPair.coinY}, current ${allEvents.length} events`)
    const eventParams: EventParams = {
      coinPair: coinPair,
      fieldName: mode,
      query: {
        start: start,
        limit: batchSize,
      },
    }
    const events = await getEvents(eventParams)
    const filteredEvents = events.filter(v => d(v.version).gt(d(startVersion)) && d(v.version).lt(d(endVersion)))
    allEvents.push(...filteredEvents)
    if (filteredEvents.length == 0 || events.length !== filteredEvents.length) break  // find the last one
    start = BigInt(filteredEvents[filteredEvents.length - 1].sequence_number) + BigInt(1)
  }
  console.log(`event length: ${allEvents.length}`)
  return allEvents
}

function updateTVL(address: string, priceTimesAmount: Decimal, timestamp: number, mode: 'plus' | 'minus') {
  if (!address2TvlTimesTime[address]) {
    address2TvlTimesTime[address] = d(0)
  }
  const timePeriod = endTimestamp - timestamp
  address2TvlTimesTime[address] = address2TvlTimesTime[address][mode](d(timePeriod).mul(priceTimesAmount))
}

async function mintBurnEvent(coinX: string, coinY: string, mode: 'mint' | 'burn', factor: number) {
  const networkBatch = 100
  console.log(`${mode}_event processing...`)
  const events = await getCoinPairEvents({
    coinX: coinX,
    coinY: coinY,
  }, `${mode}_event`)
  const plusMinus = mode == 'mint' ? 'plus' : 'minus'
  while (true) {
    const partEvents = events.splice(0, networkBatch)
    if (partEvents.length === 0) break
    console.log(`Processing ${mode}_event for ${coinX}|${coinY}, remains ${events.length} events`)
    await Promise.all(partEvents.map(async (event) =>{
      const eventMeta = await getTxByVersion(event.version)
      const sender = eventMeta.sender
      const timestamp = eventMeta.timestamp
      const amountX = event.data.amount_x
      const amountY = event.data.amount_y
      if (coinX == aptosCoin) {
        updateTVL(sender, d(amountX).div(1e8).mul(2).mul(factor), timestamp, plusMinus)
      } else if (usdCoins.includes(coinX)) {
        updateTVL(sender, d(amountX).div(1e6).div(aptos2usd).mul(2).mul(factor), timestamp, plusMinus)
      } else if (usdCoins.includes(coinY)) {
        updateTVL(sender, d(amountY).div(1e6).div(aptos2usd).mul(2).mul(factor), timestamp, plusMinus)
      } else {
        throw(`Cannot decide coin type: ${coinX}, ${coinY}`)
      }
    }))
    fs.writeFileSync('version2EventMeta.json', JSON.stringify(version2EventMeta))
  }
}

async function calculateTVL(coinX: string, coinY: string, factor: number) {
  await mintBurnEvent(coinX, coinY, 'mint', factor)
  await mintBurnEvent(coinX, coinY, 'burn', factor)
}

async function main() {
  try {
    const rawData = fs.readFileSync('version2EventMeta.json')
    version2EventMeta = JSON.parse(rawData.toString())
  } catch (e) {
    console.log(e)
    version2EventMeta = {}
  }
  for (const pool of topPools) {
    await calculateTVL(pool.coinX, pool.coinY, pool.factor)
  }
  for (const key of Object.keys(address2TvlTimesTime)) {
    if (address2TvlTimesTime[key].lte(0)) continue
    sortedInsert(
      sortedAddress,
      {
        address: key,
        value: address2TvlTimesTime[key],
      },
      (a, b) => a.value.lt(b.value) ? 1 : -1
    )
  }
  const data = JSON.stringify(sortedAddress)
  fs.writeFileSync('result.json', data)
}

main()

import { ToBufferOptions } from "bwip-js";
import bwipjsNode from "bwip-js/dist/node-bwipjs";
import bwipjsBrowser from "bwip-js/dist/bwip-js";
import { BarCodeType } from "./type";
import { b64toUint8Array } from "./util";

// GTIN-13, GTIN-8, GTIN-12, GTIN-14
const validateCheckDigit = (input: string, checkDigitPos: number) => {
  let passCheckDigit = true;

  if (input.length === checkDigitPos) {
    const ds = input.slice(0, -1).replace(/[^0-9]/g, "");
    let sum = 0;
    let odd = 1;
    for (let i = ds.length - 1; i > -1; i -= 1) {
      sum += Number(ds[i]) * (odd ? 3 : 1);
      odd ^= 1;
      if (sum > 0xffffffffffff) {
        // ~2^48 at max
        sum %= 10;
      }
    }
    passCheckDigit = String(10 - (sum % 10)).slice(-1) === input.slice(-1);
  }

  return passCheckDigit;
};

export const validateBarcodeInput = (type: BarCodeType, input: string) => {
  if (!input) return false;
  if (type === "qrcode") {
    // 500文字以下
    return input.length < 500;
  } else if (type === "japanpost") {
    // 郵便番号は数字(0-9)のみ。住所表示番号は英数字(0-9,A-Z)とハイフン(-)が使用可能です。
    const regexp = /^(\d{7})(\d|[A-Z]|-)+$/;
    return regexp.test(input);
  } else if (type === "ean13") {
    // 有効文字は数値(0-9)のみ。チェックデジットを含まない12桁orチェックデジットを含む13桁。
    const regexp = /^\d{12}$|^\d{13}$/;
    return regexp.test(input) && validateCheckDigit(input, 13);
  } else if (type === "ean8") {
    // 有効文字は数値(0-9)のみ。チェックデジットを含まない7桁orチェックデジットを含む8桁。
    const regexp = /^\d{7}$|^\d{8}$/;
    return regexp.test(input) && validateCheckDigit(input, 8);
  } else if (type === "code39") {
    // 有効文字は数字(0-9)。アルファベット大文字(A-Z)、記号(-.$/+%)、半角スペース。
    const regexp = /^(\d|[A-Z]|\-|\.|\$|\/|\+|\%|\s)+$/;
    return regexp.test(input);
  } else if (type === "code128") {
    // 有効文字は漢字、ひらがな、カタカナ以外。
    // https://qiita.com/graminume/items/2ac8dd9c32277fa9da64
    return input.match(
      /([\u30a0-\u30ff\u3040-\u309f\u3005-\u3006\u30e0-\u9fcf]|[Ａ-Ｚａ-ｚ０-９！＂＃＄％＆＇（）＊＋，－．／：；＜＝＞？＠［＼］＾＿｀｛｜｝〜])+/
    )
      ? false
      : true;
  } else if (type === "nw7") {
    // 有効文字はNW-7は数字(0-9)と記号(-.$:/+)。
    // スタートコード／ストップコードとして、コードの始まりと終わりはアルファベット(A-D)のいずれかを使用してください。
    const regexp = /^[A-Da-d]([0-9\-\.\$\:\/\+])+[A-Da-d]$/;
    return regexp.test(input);
  } else if (type === "itf14") {
    // 有効文字は数値(0-9)のみ。 チェックデジットを含まない13桁orチェックデジットを含む14桁。
    const regexp = /^\d{13}$|^\d{14}$/;
    return regexp.test(input) && validateCheckDigit(input, 14);
  } else if (type === "upca") {
    // 有効文字は数値(0-9)のみ。 チェックデジットを含まない11桁orチェックデジットを含む12桁。
    const regexp = /^\d{11}$|^\d{12}$/;
    return regexp.test(input) && validateCheckDigit(input, 12);
  } else if (type === "upce") {
    // 有効文字は数値(0-9)のみ。 1桁目に指定できる数字(ナンバーシステムキャラクタ)は0のみ。
    // チェックデジットを含まない7桁orチェックデジットを含む8桁。
    const regexp = /^0(\d{6}$|\d{7}$)/;
    return regexp.test(input) && validateCheckDigit(input, 8);
  }
  return false;
};

export const createBarCode = async ({
  type,
  input,
  width,
  height,
  backgroundColor,
}: {
  type: BarCodeType;
  input: string | null;
  width: number;
  height: number;
  backgroundColor?: string;
}): Promise<Buffer | null> => {
  if (input && validateBarcodeInput(type, input)) {
    const bwipjsArg: ToBufferOptions = {
      bcid: type === "nw7" ? "rationalizedCodabar" : type,
      text: input,
      scale: 5,
      width,
      height,
      includetext: true,
    };
    if (backgroundColor) {
      bwipjsArg.backgroundcolor = backgroundColor;
    }

    let res: Buffer;

    if (typeof window !== "undefined") {
      const canvas = document.createElement("canvas");
      bwipjsBrowser.toCanvas(canvas, bwipjsArg);
      const dataUrl = canvas.toDataURL("image/png");
      res = b64toUint8Array(dataUrl).buffer as Buffer;
    } else {
      res = await bwipjsNode.toBuffer(bwipjsArg);
    }

    return res;
  } else {
    return null;
  }
};

// Drafted using common development resources 😁
export function toQueryString(obj: Record<string, unknown>): string {
  const buildQuery = (key: string, value: unknown): string => {
    if (Array.isArray(value)) {
      return value
        .map((v, i) =>
          typeof v === 'object' && v !== null
            ? Object.keys(v as Record<string, unknown>)
                .map((subKey) =>
                  buildQuery(`${key}[${i}][${subKey}]`, (v as Record<string, unknown>)[subKey]),
                )
                .join('&')
            : `${encodeURIComponent(key)}[]=${encodeURIComponent(String(v))}`,
        )
        .join('&');
    }
    if (typeof value === 'object' && value !== null) {
      return Object.keys(value as Record<string, unknown>)
        .map((subKey) =>
          buildQuery(`${key}[${subKey}]`, (value as Record<string, unknown>)[subKey]),
        )
        .join('&');
    }
    return `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`;
  };

  return Object.keys(obj)
    .map((key) => buildQuery(key, obj[key]))
    .join('&');
}

