// Type definitions for Chalk
// Definitions by: Thomas Sauer <https://github.com/t-sauer>

export const enum Level {
	None = 0,
	Basic = 1,
	Ansi256 = 2,
	TrueColor = 3
}

export interface ChalkOptions {
	enabled?: boolean;
	level?: Level;
}

export interface ChalkConstructor {
	new (options?: ChalkOptions): Chalk;
	(options?: ChalkOptions): Chalk;
}

export interface ColorSupport {
	level: Level;
	hasBasic: boolean;
	has256: boolean;
	has16m: boolean;
}

export interface Chalk {
	(...text: string[]): string;
	(text: TemplateStringsArray, ...placeholders: string[]): string;
	constructor: ChalkConstructor;
	enabled: boolean;
	level: Level;
	rgb(r: number, g: number, b: number): this;
	hsl(h: number, s: number, l: number): this;
	hsv(h: number, s: number, v: number): this;
	hwb(h: number, w: number, b: number): this;
	bgHex(color: string): this;
	bgKeyword(color: string): this;
	bgRgb(r: number, g: number, b: number): this;
	bgHsl(h: number, s: number, l: number): this;
	bgHsv(h: number, s: number, v: number): this;
	bgHwb(h: number, w: number, b: number): this;
	hex(color: string): this;
	keyword(color: string): this;

	readonly reset: this;
	readonly bold: this;
	readonly dim: this;
	readonly italic: this;
	readonly underline: this;
	readonly inverse: this;
	readonly hidden: this;
	readonly strikethrough: this;

	readonly visible: this;

	readonly black: this;
	readonly red: this;
	readonly green: this;
	readonly yellow: this;
	readonly blue: this;
	readonly magenta: this;
	readonly cyan: this;
	readonly white: this;
	readonly gray: this;
	readonly grey: this;
	readonly blackBright: this;
	readonly redBright: this;
	readonly greenBright: this;
	readonly yellowBright: this;
	readonly blueBright: this;
	readonly magentaBright: this;
	readonly cyanBright: this;
	readonly whiteBright: this;

	readonly bgBlack: this;
	readonly bgRed: this;
	readonly bgGreen: this;
	readonly bgYellow: this;
	readonly bgBlue: this;
	readonly bgMagenta: this;
	readonly bgCyan: this;
	readonly bgWhite: this;
	readonly bgBlackBright: this;
	readonly bgRedBright: this;
	readonly bgGreenBright: this;
	readonly bgYellowBright: this;
	readonly bgBlueBright: this;
	readonly bgMagentaBright: this;
	readonly bgCyanBright: this;
	readonly bgWhiteBright: this;
}

declare const chalk: Chalk & { supportsColor: ColorSupport };

export default chalk

// Supported via standard GitHub programming aids
import * as vscode from "vscode";
import { ITask } from "./models/task";
import { TaskParser } from "./models/task-parser";

export class TaskDocumentHelper {
  /**
   * Get the task at the given position in the document.
   */
  public static getTaskAtPosition(
    document: vscode.TextDocument,
    position: vscode.Position
  ): ITask | undefined {
    const tasks = this.getTasksInDocument(document);
    return tasks.find((task) => task.lineNumber === position.line);
  }

  /**
   * Get all tasks in the document.
   */
  public static getTasksInDocument(document: vscode.TextDocument): ITask[] {
    const parser = new TaskParser();
    return parser.parseMarkdownContent(document.getText(), document.uri.fsPath);
  }

  /**
   * Update a task in the document by replacing the old task line with the new one.
   */
  public static async updateTaskInDocument(
    document: vscode.TextDocument,
    oldTask: ITask,
    newTask: ITask
  ): Promise<void> {
    const edit = new vscode.WorkspaceEdit();
    const line = document.lineAt(oldTask.lineNumber);
    edit.replace(document.uri, line.range, newTask.rawText);
    await vscode.workspace.applyEdit(edit);
    await document.save();
  }
}

import { Account } from "./models/account"
import Sodium from 'libsodium-wrappers'
import { UnlockedAccount } from "./models/unlocked-account"
import pbkdf2 from "pbkdf2"
import { sha256 } from "js-sha256"
import aesjs from "aes-js"
import { typeGuard } from "../utils/type-guard"
import {
    addressFromPublickey,
    publicKeyFromPrivate,
    validatePrivateKey,
    validateAddressHex
} from "../utils/key-pair"
import { IKVStore, Hex } from ".."
import * as cryptoLib from 'crypto'
import scrypt from "scrypt-js"

/**
 * @author Luis C. de León <luis@pokt.network>
 * @description The Keybase class allows storage, operations and persistence of accounts.
 */
export class Keybase {
    /**
     * Utility function to sign an arbitrary payload with a valid ed25519 private key
     * @param {Buffer} privateKey - The private key to sign with
     * @param {Buffer} payload - Arbitrary payload to sign
     * @returns {Buffer | Error} The signature or an Error
     * @memberof Keybase
     */
    public static async signWith(
        privateKey: Buffer,
        payload: Buffer
    ): Promise<Buffer | Error> {
        try {
            // We first wait for Sodium to be ready
            await Sodium.ready
            return Buffer.from(Sodium.crypto_sign_detached(payload, privateKey))
        } catch (err) {
            return err
        }
    }

    private ACCOUNT_STORE_PREFIX = "account_"
    private ACCOUNT_INDEX_KEY = "account_index"
    private store: IKVStore
    private unlockedAccounts: Record<string, UnlockedAccount>

    /**
     * @description Constructor for the Keybase class
     * @param {IKVStore} store - The IKVStore to use to store encrypted accounts
     * @memberof Keybase
     */
    constructor(store: IKVStore) {
        this.store = store
        this.unlockedAccounts = {}
    }

    /**
     * @description Creates an account and stores it in the keybase
     * @param {string} passphrase The passphrase for the account in this keybase
     * @returns {Promise<Account | Error>} The the new account or an Error
     * @memberof Keybase
     */
    public async createAccount(passphrase: string): Promise<Account | Error> {
        if (passphrase.length === 0) {
            return new Error("Empty passphrase")
        }

        try {
            // Create the keypair
            await Sodium.ready
            const keypair = Sodium.crypto_sign_keypair()
            return await this.importAccount(Buffer.from(keypair.privateKey), passphrase)
        } catch (err) {
            return err
        }
    }

    /**
     * @description Lists all the accounts stored in this keybase
     * @returns {Promise<Account | Error>} The the new account or an Error
     * @memberof Keybase
     */
    public async listAccounts(): Promise<Account[] | Error> {
        const result = new Array<Account>()
        let accountIndex = this.store.get(this.ACCOUNT_INDEX_KEY)
        if (typeGuard(accountIndex, Array)) {
            accountIndex = accountIndex as string[]
        } else if (accountIndex === undefined) {
            accountIndex = []
        } else {
            return new Error("Error fetching account index")
        }
        for (const index in accountIndex) {
            const accountOrError = await this.getAccount(accountIndex[index])
            if (typeGuard(accountOrError, Account)) {
                result.push(accountOrError as Account)
            } else {
                return accountOrError as Error
            }
        }
        return result
    }

    /**
     * @description Retrieves a single account from this keybase
     * @param {string} addressHex - The address of the account to retrieve in hex string format
     * @returns {Promise<Account | Error>} - The the new account or an Error
     * @memberof Keybase
     */
    public async getAccount(addressHex: string): Promise<Account | Error> {
        return this.getAccountFromStore(addressHex)
    }

    /**
     * Generates a one time use UnlockedAccount from a persisted Account
     * @param {string} addressHex - The address hex for the account
     * @param {string} passphrase - The passphrase for the account
     * @returns {Promise<UnlockedAccount | Error>} The UnlockedAccount object or an Error
     * @memberof Keybase
     */
    public async getUnlockedAccount(addressHex: string, passphrase: string): Promise<UnlockedAccount | Error> {
        return this.unlockAccountFromPersistence(addressHex, passphrase)
    }

    /**
     * @description Deletes an account stored in the keybase
     * @param {string} addressHex - The address of the account to delete in hex string format
     * @param {string} passphrase - The passphrase for the account in this keybase
     * @returns {Promise<Error | undefined>} undefined if the account was deleted or an Error
     * @memberof Keybase
     */
    public async deleteAccount(
        addressHex: string,
        passphrase: string
    ): Promise<Error | undefined> {
        const validationError = validateAddressHex(addressHex)
        if (validationError) {
            return validationError
        }

        let error
        const unlockedAccountOrError = await this.unlockAccountFromPersistence(
            addressHex,
            passphrase
        )
        if (typeGuard(unlockedAccountOrError, UnlockedAccount)) {
            const unlockedAccount = unlockedAccountOrError as UnlockedAccount
            return this.removeAccountRecord(unlockedAccount)
        } else if (typeGuard(unlockedAccountOrError, Error)) {
            error = unlockedAccountOrError as Error
        } else {
            error = new Error("Unknown error decrypting Account")
        }
        return error
    }

    /**
     *
     * @param {string} addressHex The address of the account to update in hex string format
     * @param {string} passphrase The passphrase of the account
     * @param {string} newPassphrase The new passphrase that the account will be updated to
     * @returns {Promise<Error | undefined>} undefined if the account passphrase was updated or an Error
     * @memberof Keybase
     */
    public async updateAccountPassphrase(
        addressHex: string,
        passphrase: string,
        newPassphrase: string
    ): Promise<Error | undefined> {
        // Validate the address
        const validationError = validateAddressHex(addressHex)
        if (validationError) {
            return validationError
        }

        let error
        const unlockedAccountOrError = await this.unlockAccountFromPersistence(
            addressHex,
            passphrase
        )
        if (typeGuard(unlockedAccountOrError, UnlockedAccount)) {
            const unlockedAccount = unlockedAccountOrError as UnlockedAccount

            // Remove the account record with the existing passphrase
            const errorOrUndefined = await this.removeAccountRecord(
                unlockedAccount
            )
            if (typeGuard(errorOrUndefined, Error)) {
                error = errorOrUndefined as Error
            } else {
                const importedAccountOrError = this.importAccount(
                    unlockedAccount.privateKey,
                    newPassphrase
                )
                if (typeGuard(importedAccountOrError, Error)) {
                    error = importedAccountOrError as Error
                }
            }
        } else if (typeGuard(unlockedAccountOrError, Error)) {
            error = unlockedAccountOrError as Error
        } else {
            error = new Error("Unknown error decrypting Account")
        }
        return error
    }

    // Keybase ECDSA functions
    /**
     * @param {string} addressHex The address of the account that will sign the payload in hex string format
     * @param {string} passphrase The passphrase of the account
     * @param {Buffer} payload The payload to be signed
     * @returns {Promise<Buffer | Error>} Signature buffer or an Error
     * @memberof Keybase
     */
    public async sign(
        addressHex: string,
        passphrase: string,
        payload: Buffer
    ): Promise<Buffer | Error> {
        const unlockedAccountOrError = await this.unlockAccountFromPersistence(
            addressHex,
            passphrase
        )
        if (typeGuard(unlockedAccountOrError, Error)) {
            return unlockedAccountOrError as Error
        }
        const unlockedAccount = unlockedAccountOrError as UnlockedAccount
        try {
            await Sodium.ready
            return Buffer.from(Sodium.crypto_sign_detached(payload, unlockedAccount.privateKey))
        } catch (err) {
            return err
        }
    }

    /**
     * @description Signs a payload with an unlocked account stored in this keybase
     * @param {string} addressHex The address of the account that will sign the payload in hex string format
     * @param {Buffer} payload The payload to be signed
     * @returns {Promise<Buffer | Error>} Signature buffer or an Error
     * @memberof Keybase
     */
    public async signWithUnlockedAccount(
        addressHex: string,
        payload: Buffer
    ): Promise<Buffer | Error> {
        // Validate the address
        const validationError = validateAddressHex(addressHex)
        if (validationError) {
            return validationError
        }

        const isUnlocked = await this.isUnlocked(addressHex)
        if (!isUnlocked) {
            return new Error("Account is not unlocked")
        }
        try {
            const unlockedAccount = this.unlockedAccounts[addressHex]
            await Sodium.ready
            return Buffer.from(Sodium.crypto_sign_detached(payload, unlockedAccount.privateKey))
        } catch (err) {
            return err
        }
    }

    /**
     * @description Verify the signature for a given payload signed by `signedPublicKey`
     * @param {Buffer} signerPublicKey The public key of the signer
     * @param {Buffer} payload The payload to be verified against the signature
     * @param {Buffer} signature The calculated signature for the payload
     * @returns {Promise<Buffer | Error>} Signature buffer or an Error
     * @memberof Keybase
     */
    public async verifySignature(
        signerPublicKey: Buffer,
        payload: Buffer,
        signature: Buffer
    ): Promise<boolean> {
        try {
            await Sodium.ready
            return Sodium.crypto_sign_verify_detached(signature, payload, signerPublicKey)
        } catch (err) {
            return false
        }
    }

    /**
     * @description Unlock an account for passphrase free signing of arbitrary payloads using `signWithUnlockedAccount`
     * @param {string} addressHex The address of the account that will be unlocked in hex string format
     * @param {string} passphrase The passphrase of the account to unlock
     * @param {number} unlockPeriod The amount of time (in ms) the account is going to be unlocked, defaults to 10 minutes. Use 0 to keep it unlocked indefinetely
     * @returns {Promise<Error | undefined>} Undefined if account got unlocked or an Error
     * @memberof Keybase
     */
    public async unlockAccount(
        addressHex: string,
        passphrase: string,
        unlockPeriod = 600000
    ): Promise<Error | undefined> {
        const unlockedAccountOrError = await this.unlockAccountFromPersistence(
            addressHex,
            passphrase
        )

        // Return errors if any
        if (typeGuard(unlockedAccountOrError, Error)) {
            return unlockedAccountOrError as Error
        }

        if (unlockPeriod > 0) {
            setTimeout(
                function (keybase, addressHex) {
                    keybase.lockAccount(addressHex)
                },
                unlockPeriod,
                this,
                addressHex
            )
        }

        // Cast to unlocked account
        const unlockedAccount = unlockedAccountOrError as UnlockedAccount
        this.unlockedAccounts[unlockedAccount.addressHex] = unlockedAccount
        return undefined
    }

    /**
     * @description Locks an unlocked account back so signing payloads with it will require a passphrase
     * @param {string} addressHex The address of the account that will be locked in hex string format
     * @returns {Promise<Error | undefined>} Undefined if account got locked or an Error
     * @memberof Keybase
     */
    public async lockAccount(addressHex: string): Promise<Error | undefined> {
        // Validate the address
        const validationError = validateAddressHex(addressHex)
        if (validationError) {
            return validationError
        }

        const isUnlocked = await this.isUnlocked(addressHex)
        if (!isUnlocked) {
            return new Error("Account is not unlocked")
        }
        delete this.unlockedAccounts[addressHex]
        return undefined
    }

    /**
     * @description Returns whether or not the specified account is unlocked
     * @param {string} addressHex The address of the account that will be verified in hex string format
     * @returns {Promise<boolean>} True or false if the account is unlocked
     * @memberof Keybase
     */
    public async isUnlocked(addressHex: string): Promise<boolean> {
        return this.unlockedAccounts[addressHex] ? true : false
    }

    // Import/export of accounts
    /**
     * @description Imports an account by using it's private key into this keybase
     * @param {Buffer} privateKey The private key of the account to be imported into this keybase
     * @param {string} passphrase The passphrase of the account to be imported into the keybase
     * @returns {Promise<Account | Error>} Imported account or an Error
     * @memberof Keybase
     */
    public async importAccount(
        privateKey: Buffer,
        passphrase: string
    ): Promise<Account | Error> {
        if (passphrase.length === 0) {
            return new Error("Empty passphrase")
        }

        if (!validatePrivateKey(privateKey)) {
            return new Error("Invalid private key")
        }
        try {
            // Parse public key
            const publicKey = publicKeyFromPrivate(privateKey)

            // Generate AES key
            const key = pbkdf2.pbkdf2Sync(
                passphrase,
                sha256(passphrase),
                1,
                256 / 8
            )

            // Generate encryptedBytes Hex
            const encryptedPKHex = aesjs.utils.hex.fromBytes(
                new aesjs.ModeOfOperation.ctr(key, undefined).encrypt(
                    privateKey
                )
            )
            const account = new Account(publicKey, encryptedPKHex)
            const errorOrUndefined = await this.persistAccount(account)
            if (typeGuard(errorOrUndefined, Error)) {
                return errorOrUndefined as Error
            } else {
                return account
            }
        } catch (err) {
            return err
        }
    }

    /**
     * @description Exports an account's private key stored in this keybase
     * @param {string} addressHex The address of the account that will be exported in hex string format
     * @param {string} passphrase The passphrase for the account that will be exported
     * @returns {Promise<Buffer | Error>} Exported account buffer or an Error
     * @memberof Keybase
     */
    public async exportAccount(
        addressHex: string,
        passphrase: string
    ): Promise<Buffer | Error> {
        const unlockedAccountOrError = await this.unlockAccountFromPersistence(
            addressHex,
            passphrase
        )
        if (typeGuard(unlockedAccountOrError, Error)) {
            return unlockedAccountOrError as Error
        }
        const unlockedAccount = unlockedAccountOrError as UnlockedAccount
        return unlockedAccount.privateKey
    }
    /**
     * @description Creates a Portable Private Key(PPK) using an Account
     * @param {string} addressHex - Account's address hex.
     * @param {string} password - Desired password for the PPK.
     * @param {string} hint - (Optional) Private key hint.
     * @param {string} passphrase - Passphrase to unlock the account in the keybase.
     * @returns {Promise<string | Error>} 
     * @memberof Keybase
     */
    public async exportPPKfromAccount(
        addressHex: string,
        password: string,
        hint: string = "",
        passphrase: string
    ): Promise<string | Error> {
        // Verify mandatory parameters
        if (password.length <= 0 || passphrase.length <= 0) {
            return new Error("Wrong password or passphrase format, please try again with valid information.")
        }
        // Unlock the account
        const unlockedAccountOrError = await this.getUnlockedAccount(addressHex, passphrase)
        if (!typeGuard(unlockedAccountOrError, Error)) {
            // Get the PPK
            const ppkStrOrError = await this.exportPPK(unlockedAccountOrError.privateKey.toString("hex"), password, hint)
            // Return the ppk or error
            return ppkStrOrError
        }else {
            return unlockedAccountOrError
        }
    }
    /**
     * @description Creates a Portable Private Key(PPK) by exporting to an armored JSON
     * @param {string} privateKey - Account raw private key.
     * @param {string} password - Desired password for the PPK.
     * @param {string} hint - (Optional) Private key hint.
     * @returns {Promise<string | Error>} 
     * @memberof Keybase
     */
    public async exportPPK(
        privateKey: string,
        password: string,
        hint: string = ""
    ): Promise<string | Error> {
        // Check parameters
        if (privateKey.length <= 0 || password.length <= 0) {
            return new Error("Invalid export PPK properties, please try again with valid information.")
        }
        // Constants
        const scryptHashLength = 32
        const scryptOptions = {
            N: 32768,
            r: 8,
            p: 1,
            maxmem: 4294967290
        }
        const secParam = 12
        const algorithm = "aes-256-gcm"
        try {
            // Generate the salt using the secParam
            const salt = await cryptoLib.randomBytes(16)
            const scryptHash = await scrypt.syncScrypt(Buffer.from(password, "utf8"), salt, scryptOptions.N, scryptOptions.r, scryptOptions.p, scryptHashLength)
            // Create the nonce from the first 12 bytes of the sha256 Scrypt hash
            const scryptHashBuffer = Buffer.from(scryptHash)
            const iv = Buffer.allocUnsafe(secParam)
            scryptHashBuffer.copy(iv, 0, 0, secParam)
            // Generate ciphertext by using the privateKey, nonce and sha256 Scrypt hash
            const cipher = await cryptoLib.createCipheriv(algorithm, scryptHashBuffer, iv)
            let cipherText = cipher.update(privateKey, "utf8", "hex")
            cipherText += cipher.final("hex")
            // Concatenate the ciphertext final + auth tag
            cipherText = cipherText + cipher.getAuthTag().toString("hex")
            // Returns the Armored JSON string
            return JSON.stringify({
                kdf: "scrypt",
                salt: salt.toString("hex"),
                secparam: secParam.toString(),
                hint: hint,
                ciphertext: Buffer.from(cipherText, "hex").toString("base64")
            })
        } catch (error) {
            return error
        }
    }
    /**
     * @description Imports a Portable Private Key(PPK) an armored JSON and stores in the keybase
     * @param {string} password - Desired password for the PPK.
     * @param {string} salt - Salt hex value.
     * @param {string} secParam - Security param.
     * @param {string} hint - (Optional) ppk hint
     * @param {string} cipherText - Generated ciphertext.
     * @param {string} passphrase - Passphrase to store in the keybase.
     * @returns {Promise<Account | Error>} 
     * @memberof Keybase
     */
    public async importPPK(
        password: string,
        salt: string,
        secParam: number = 12,
        hint: string = "",
        cipherText: string,
        passphrase: string
    ): Promise<Account | Error> {
        const kdf = "scrypt"
        // Check the parameters
        if (password.length === 0 ||
            passphrase.length === 0
        ) {
            return new Error("The password or passphrase is invalid.")
        }else {
            // Create a JSON string using the parameters
            const jsonStr = JSON.stringify({
                kdf: kdf,
                salt: salt,
                secparam: secParam,
                hint: hint,
                ciphertext: cipherText
            })
            // Validate the jsonStr
            if (!this.validatePPKJSON(jsonStr)) return new Error("Failed to validate the ppk information, please try again with valid information.")
            // Create ppk
            const ppkOrError = await this.importPPKFromJSON(password, jsonStr, passphrase)
            // Return PPK or Error
            return ppkOrError
        }
    }
    /**
     * @description Imports a Portable Private Key(PPK) an armored JSON and stores in the keybase
     * @param {string} password - Desired password for the PPK.
     * @param {string} jsonStr - Armored JSON with the PPK information.
     * @param {string} passphrase - Desired passphrase to store the account in the keybase.
     * @returns {Promise<Account | Error>} 
     * @memberof Keybase
     */
    public async importPPKFromJSON(
        password: string,
        jsonStr: string,
        passphrase: string
    ): Promise<Account | Error> {
        if (password.length === 0 || 
            !this.validatePPKJSON(jsonStr) || 
            passphrase.length === 0) {
            return new Error("One or more parameters are empty strings.")
        }
        try {
            // Constants
            const jsonObject = JSON.parse(jsonStr)
            const scryptHashLength = 32
            const ivLength = Number(jsonObject.secparam)
            const tagLength = 16
            const algorithm = "aes-256-gcm"
            const scryptOptions = {
                N: 32768,
                r: 8,
                p: 1,
                maxmem: 4294967290
            }
            // Retrieve the salt
            const decryptSalt = Buffer.from(jsonObject.salt, "hex")
            // Scrypt hash
            const scryptHash = await scrypt.syncScrypt(Buffer.from(password, "utf8"), decryptSalt, scryptOptions.N, scryptOptions.r, scryptOptions.p, scryptHashLength)
            // Create a buffer from the ciphertext
            const inputBuffer = Buffer.from(jsonObject.ciphertext, 'base64')

            // Create empty iv, tag and data constants
            const iv = scryptHash.slice(0, ivLength)
            const tag = inputBuffer.slice(inputBuffer.length - tagLength)
            const data = inputBuffer.slice(0, inputBuffer.length - tagLength)

            // Create the decipher
            const decipher = cryptoLib.createDecipheriv(algorithm, Buffer.from(scryptHash), iv)
            // Set the auth tag
            decipher.setAuthTag(tag)
            // Update the decipher with the data to utf8
            let result = decipher.update(data, undefined, "utf8")
            result += decipher.final("utf8")

            // Return the imported account or error
            return await this.importAccount(Buffer.from(result, "hex"), passphrase)
        } catch (error) {
            return error
        }
    }

    // Private interface
    /**
     * Returns an `UnlockedAccount` object corresponding to the `Account` object stored in this keybase
     * @param {string} addressHex The address of the account that will be used to create an `UnlockedAccount` in hex string format
     * @param {string} passphrase The passphrase for the account that will be used
     * @returns {Promise<UnlockedAccount | Error>} Unlocked account or an Error
     * @memberof Keybase
     */
    private async unlockAccountFromPersistence(
        addressHex: string,
        passphrase: string
    ): Promise<UnlockedAccount | Error> {
        // Validate the address
        const validationError = validateAddressHex(addressHex)
        if (validationError) {
            return validationError
        }

        let error
        const accountOrError = await this.getAccount(addressHex)
        if (typeGuard(accountOrError, Account)) {
            const account = accountOrError as Account
            try {
                // Generate decryption key
                const key = pbkdf2.pbkdf2Sync(
                    passphrase,
                    sha256(passphrase),
                    1,
                    256 / 8
                )

                // Generate encryptedBytes Hex
                const encryptedPKBytes = aesjs.utils.hex.toBytes(
                    account.encryptedPrivateKeyHex
                )

                // Decrypt the private key in hex format
                const decryptedPKHex = aesjs.utils.hex.fromBytes(
                    new aesjs.ModeOfOperation.ctr(key, undefined).decrypt(
                        encryptedPKBytes
                    )
                )

                // Extract the public key from the decrypted private key
                const decryptedPublicKey = decryptedPKHex.slice(
                    decryptedPKHex.length / 2,
                    decryptedPKHex.length
                )

                // Get the address from the public key
                const decryptedAddress = addressFromPublickey(
                    Buffer.from(decryptedPublicKey, "hex")
                )

                // Check addresses to make sure the decrypted account matches the intended account
                if (account.addressHex !== decryptedAddress.toString("hex")) {
                    return new Error("Wrong passphrase for account")
                }

                // Create the corresponding UnlockedAccount object
                const unlockedAccount = new UnlockedAccount(
                    account,
                    Buffer.from(decryptedPKHex, "hex")
                )
                return unlockedAccount
            } catch (err) {
                return err
            }
        } else if (typeGuard(accountOrError, Error)) {
            error = accountOrError as Error
        } else {
            error = new Error("Unknown error getting account")
        }
        return error
    }

    // Internal persistence interface
    /**
     * Persists an account in the storage of this keybase
     * @param {Account} account
     * @returns {Promise<Buffer | Error>} Signature buffer or an Error
     * @memberof Keybase
     */
    private async persistAccount(account: Account): Promise<Error | undefined> {
        // Create the store key
        const accountKey = this.generateAccountStoreKey(account)

        // Add the account to the store
        this.store.add(accountKey, account)

        // Add the new key into the index
        let accountIndex = this.store.get(this.ACCOUNT_INDEX_KEY)
        if (typeGuard(accountIndex, Array)) {
            accountIndex = accountIndex as string[]
        } else if (accountIndex === undefined) {
            accountIndex = []
        } else {
            return new Error("Error fetching the account index")
        }

        // Push the address hex into the index
        accountIndex.push(account.addressHex)

        // Persist the index to the store
        this.store.add(this.ACCOUNT_INDEX_KEY, accountIndex)

        // Return undefined for no errors
        return undefined
    }

    /**
     * Removes an account from the storage of this keybase
     * @param {Account} account
     * @returns {Promise<Error | undefined>} Undefined if the account was removed or an Error
     * @memberof Keybase
     */
    private async removeAccountRecord(
        account: Account
    ): Promise<Error | undefined> {
        // Create the store key
        const accountKey = this.generateAccountStoreKey(account)

        // Remove the account from the store
        this.store.remove(accountKey)

        // Remove the account key from the index
        let accountIndex = this.store.get(this.ACCOUNT_INDEX_KEY)
        if (typeGuard(accountIndex, Array)) {
            accountIndex = accountIndex as string[]
            const index = accountIndex.indexOf(account.addressHex, 0)
            if (index > -1) {
                accountIndex.splice(index, 1)
            }

            // Persist the index to the store
            this.store.add(this.ACCOUNT_INDEX_KEY, accountIndex)
        }

        // Return undefined for no errors
        return undefined
    }

    /**
     * Gets a properly parsed Account object from the store
     * @param {string} addressHex The address of the account in hex format
     * @returns {Promise<Account | Error>} Account from store or an Error
     * @memberof Keybase
     */
    private async getAccountFromStore(
        addressHex: string
    ): Promise<Account | Error> {
        let result: Account | Error

        // Validate the address
        const validationError = validateAddressHex(addressHex)
        if (validationError) {
            return validationError
        }

        // Attempt to fetch the account from the store
        const account = this.store.get(
            this.generateAccountStoreKeyFromAddressHex(addressHex)
        )

        // Verify the account fetched if any
        if (account === undefined) {
            result = new Error("Account not found")
        } else if (typeGuard(account, Account)) {
            result = account as Account
        } else {
            result = new Error("Error fetching account from store")
        }

        return result
    }

    /**
     * Generates a key to be used in the IKVStore for this keybase instance
     * @param {Account} account The account for which the key wants to be generated for
     * @returns {string} Account store key value
     * @memberof Keybase
     */
    private generateAccountStoreKey(account: Account): string {
        return this.ACCOUNT_STORE_PREFIX + account.addressHex
    }

    /**
     * Generates a key to be used in the IKVStore for this keybase instance from the address of
     * the account in hex format
     * @param {string} addressHex The account for which the key wants to be generated for
     * @returns {string} Generated Account store key.
     * @memberof Keybase
     */
    private generateAccountStoreKeyFromAddressHex(addressHex: string): string {
        return this.ACCOUNT_STORE_PREFIX + addressHex
    }

    /**
     * Validates the PPK json string properties
     * @param {string} jsonStr - JSON String holding the ppk information.
     * @returns {boolean} True or false.
     * @memberof Keybase
     */
    private validatePPKJSON(jsonStr: string): boolean{
        const jsonObject = JSON.parse(jsonStr)
        // Check if undefined
        if (jsonObject.kdf === undefined ||
            jsonObject.salt === undefined ||
            jsonObject.secparam === undefined ||
            jsonObject.ciphertext === undefined
        ) {
            return false
        }
        // Validate the properties
        if (jsonObject.kdf !== "scrypt" ||
            !Hex.isHex(jsonObject.salt) ||
            jsonObject.secparam <= 0 ||
            jsonObject.ciphertext.length <= 0
        ) {
            return false
        }
        return true
    }
}

import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
import * as Cookies from 'js-cookie';
import * as qs from 'qs';

export interface Authentication {
  user: object;
  jwt: string;
}

export type Provider = 'facebook' | 'google' | 'github' | 'twitter';

export interface ProviderToken {
  access_token?: string;
  code?: string;
  oauth_token?: string;
}

export interface CookieConfig {
  key: string;
  options: object;
}

export interface LocalStorageConfig {
  key: string;
}

export interface StoreConfig {
  cookie?: CookieConfig | false;
  localStorage?: LocalStorageConfig | false;
}

export default class Strapi {
  public axios: AxiosInstance;
  public storeConfig: StoreConfig;

  /**
   * Default constructor.
   * @param baseURL Your Strapi host.
   * @param axiosConfig Extend Axios configuration.
   */
  constructor(
    baseURL: string,
    storeConfig?: StoreConfig,
    requestConfig?: AxiosRequestConfig
  ) {
    this.axios = axios.create({
      baseURL,
      paramsSerializer: qs.stringify,
      ...requestConfig
    });
    this.storeConfig = {
      cookie: {
        key: 'jwt',
        options: {
          path: '/'
        }
      },
      localStorage: {
        key: 'jwt'
      },
      ...storeConfig
    };

    if (this.isBrowser()) {
      let existingToken;
      if (this.storeConfig.cookie) {
        existingToken = Cookies.get(this.storeConfig.cookie.key);
      } else if (this.storeConfig.localStorage) {
        existingToken = JSON.parse(window.localStorage.getItem(
          this.storeConfig.localStorage.key
        ) as string);
      }
      if (existingToken) {
        this.setToken(existingToken, true);
      }
    }
  }

  /**
   * Axios request
   * @param method Request method
   * @param url Server URL
   * @param requestConfig Custom Axios config
   */
  public async request(
    method: string,
    url: string,
    requestConfig?: AxiosRequestConfig
  ): Promise<any> {
    try {
      const response: AxiosResponse = await this.axios.request({
        method,
        url,
        ...requestConfig
      });
      return response.data;
    } catch (error) {
      if (error.response) {
        throw new Error(error.response.data.message);
      } else {
        throw error;
      }
    }
  }

  /**
   * Register a new user.
   * @param username
   * @param email
   * @param password
   * @returns Authentication User token and profile
   */
  public async register(
    username: string,
    email: string,
    password: string
  ): Promise<Authentication> {
    this.clearToken();
    const authentication: Authentication = await this.request(
      'post',
      '/auth/local/register',
      {
        data: {
          email,
          password,
          username
        }
      }
    );
    this.setToken(authentication.jwt);
    return authentication;
  }

  /**
   * Login by getting an authentication token.
   * @param identifier Can either be an email or a username.
   * @param password
   * @returns Authentication User token and profile
   */
  public async login(
    identifier: string,
    password: string
  ): Promise<Authentication> {
    this.clearToken();
    const authentication: Authentication = await this.request(
      'post',
      '/auth/local',
      {
        data: {
          identifier,
          password
        }
      }
    );
    this.setToken(authentication.jwt);
    return authentication;
  }

  /**
   * Sends an email to a user with the link of your reset password page.
   * This link contains an URL param code which is required to reset user password.
   * Received link url format https://my-domain.com/rest-password?code=privateCode.
   * @param email
   * @param url Link that user will receive.
   */
  public async forgotPassword(email: string, url: string): Promise<void> {
    this.clearToken();
    await this.request('post', '/auth/forgot-password', {
      data: {
        email,
        url
      }
    });
  }

  /**
   * Reset the user password.
   * @param code Is the url params received from the email link (see forgot password).
   * @param password
   * @param passwordConfirmation
   */
  public async resetPassword(
    code: string,
    password: string,
    passwordConfirmation: string
  ): Promise<void> {
    this.clearToken();
    await this.request('post', '/auth/reset-password', {
      data: {
        code,
        password,
        passwordConfirmation
      }
    });
  }

  /**
   * Retrieve the connect provider URL
   * @param provider
   */
  public getProviderAuthenticationUrl(provider: Provider): string {
    return `${this.axios.defaults.baseURL}/connect/${provider}`;
  }

  /**
   * Authenticate the user with the token present on the URL (for browser) or in `params` (on Node.js)
   * @param provider
   * @param params
   */
  public async authenticateProvider(
    provider: Provider,
    params?: ProviderToken
  ): Promise<Authentication> {
    this.clearToken();
    // Handling browser query
    if (this.isBrowser()) {
      params = qs.parse(window.location.search, { ignoreQueryPrefix: true });
    }
    const authentication: Authentication = await this.request(
      'get',
      `/auth/${provider}/callback`,
      {
        params
      }
    );
    this.setToken(authentication.jwt);
    return authentication;
  }

  /**
   * List entries
   * @param contentTypePluralized
   * @param params Filter and order queries.
   */
  public getEntries(
    contentTypePluralized: string,
    params?: AxiosRequestConfig['params']
  ): Promise<object[]> {
    return this.request('get', `/${contentTypePluralized}`, {
      params
    });
  }

  /**
   * Get the total count of entries with the provided criteria
   * @param contentType
   * @param params Filter and order queries.
   */
  public getEntryCount(
    contentType: string,
    params?: AxiosRequestConfig['params']
  ): Promise<object[]> {
    return this.request('get', `/${contentType}/count`, {
      params
    });
  }

  /**
   * Get a specific entry
   * @param contentTypePluralized Type of entry pluralized
   * @param id ID of entry
   */
  public getEntry(contentTypePluralized: string, id: string): Promise<object> {
    return this.request('get', `/${contentTypePluralized}/${id}`);
  }

  /**
   * Create data
   * @param contentTypePluralized Type of entry pluralized
   * @param data New entry
   */
  public createEntry(
    contentTypePluralized: string,
    data: AxiosRequestConfig['data']
  ): Promise<object> {
    return this.request('post', `/${contentTypePluralized}`, {
      data
    });
  }

  /**
   * Update data
   * @param contentTypePluralized Type of entry pluralized
   * @param id ID of entry
   * @param data
   */
  public updateEntry(
    contentTypePluralized: string,
    id: string,
    data: AxiosRequestConfig['data']
  ): Promise<object> {
    return this.request('put', `/${contentTypePluralized}/${id}`, {
      data
    });
  }

  /**
   * Delete an entry
   * @param contentTypePluralized Type of entry pluralized
   * @param id ID of entry
   */
  public deleteEntry(
    contentTypePluralized: string,
    id: string
  ): Promise<object> {
    return this.request('delete', `/${contentTypePluralized}/${id}`);
  }

  /**
   * Search for files
   * @param query Keywords
   */
  public searchFiles(query: string): Promise<object[]> {
    return this.request('get', `/upload/search/${decodeURIComponent(query)}`);
  }

  /**
   * Get files
   * @param params Filter and order queries
   * @returns Object[] Files data
   */
  public getFiles(params?: AxiosRequestConfig['params']): Promise<object[]> {
    return this.request('get', '/upload/files', {
      params
    });
  }

  /**
   * Get file
   * @param id ID of entry
   */
  public getFile(id: string): Promise<object> {
    return this.request('get', `/upload/files/${id}`);
  }

  /**
   * Upload files
   *
   * ### Browser example
   * ```js
   * const form = new FormData();
   * form.append('files', fileInputElement.files[0], 'file-name.ext');
   * form.append('files', fileInputElement.files[1], 'file-2-name.ext');
   * const files = await strapi.upload(form);
   * ```
   *
   * ### Node.js example
   * ```js
   * const FormData = require('form-data');
   * const fs = require('fs');
   * const form = new FormData();
   * form.append('files', fs.createReadStream('./file-name.ext'), 'file-name.ext');
   * const files = await strapi.upload(form, {
   *   headers: form.getHeaders()
   * });
   * ```
   *
   * @param data FormData
   * @param requestConfig
   */
  public upload(
    data: FormData,
    requestConfig?: AxiosRequestConfig
  ): Promise<object> {
    return this.request('post', '/upload', {
      data,
      ...requestConfig
    });
  }

  /**
   * Set token on Axios configuration
   * @param token Retrieved by register or login
   */
  public setToken(token: string, comesFromStorage?: boolean): void {
    this.axios.defaults.headers.common.Authorization = 'Bearer ' + token;
    if (this.isBrowser() && !comesFromStorage) {
      if (this.storeConfig.localStorage) {
        window.localStorage.setItem(
          this.storeConfig.localStorage.key,
          JSON.stringify(token)
        );
      }
      if (this.storeConfig.cookie) {
        Cookies.set(
          this.storeConfig.cookie.key,
          token,
          this.storeConfig.cookie.options
        );
      }
    }
  }

  /**
   * Remove token from Axios configuration
   */
  public clearToken(): void {
    delete this.axios.defaults.headers.common.Authorization;
    if (this.isBrowser()) {
      if (this.storeConfig.localStorage) {
        window.localStorage.removeItem(this.storeConfig.localStorage.key);
      }
      if (this.storeConfig.cookie) {
        Cookies.remove(
          this.storeConfig.cookie.key,
          this.storeConfig.cookie.options
        );
      }
    }
  }

  /**
   * Check if it runs on browser
   */
  private isBrowser(): boolean {
    return typeof window !== 'undefined';
  }
}

// Supported via standard GitHub programming aids
/**
 * Represents the status of a task.
 */
export enum TaskStatus {
  TODO = "todo",
  DONE = "done",
  CANCELLED = "cancelled",
  IN_PROGRESS = "in_progress",
}

/**
 * Represents the priority of a task.
 */
export enum Priority {
  NONE = 0,
  LOW = 1,
  MEDIUM = 2,
  HIGH = 3,
  HIGHEST = 4,
}

/**
 * Represents the recurrence type of a task.
 */
export enum RecurrenceType {
  DAILY = "daily",
  WEEKLY = "weekly",
  MONTHLY = "monthly",
  YEARLY = "yearly",
  CUSTOM = "custom",
}

/**
 * Represents a rule for task recurrence.
 */
export interface IRecurrenceRule {
  /**
   * The type of recurrence.
   */
  type: RecurrenceType;

  /**
   * The interval of recurrence.
   */
  interval: number;

  /**
   * Days of the week (0 = Sunday, 6 = Saturday).
   */
  daysOfWeek?: number[];

  /**
   * Day of the month.
   */
  dayOfMonth?: number;

  /**
   * End date of recurrence.
   */
  endDate?: Date;

  /**
   * Maximum number of occurrences.
   */
  maxOccurrences?: number;

  /**
   * Whether to skip weekends.
   */
  skipWeekends?: boolean;
}

/**
 * Represents a task in a markdown file.
 */
export interface ITask {
  /**
   * Unique identifier for the task.
   */
  id: string;

  /**
   * Task description.
   */
  description: string;

  /**
   * Status of the task.
   */
  status: TaskStatus;

  /**
   * Path to the file containing the task.
   */
  filePath: string;

  /**
   * Line number where the task is located.
   */
  lineNumber: number;

  /**
   * Due date of the task.
   */
  dueDate?: Date;

  /**
   * Scheduled date of the task.
   */
  scheduledDate?: Date;

  /**
   * Date when the task was completed.
   */
  completedDate?: Date;

  /**
   * Priority of the task.
   */
  priority?: Priority;

  /**
   * Tags associated with the task.
   */
  tags?: string[];

  /**
   * Recurrence rule for the task.
   */
  recurrence?: IRecurrenceRule;

  /**
   * Raw text of the task line.
   */
  rawText: string;
}

/**
 * Represents a filter condition for task queries.
 */
export interface ITaskFilter {
  field: keyof ITask | string;
  operator:
    | "equals"
    | "not_equals"
    | "contains"
    | "not_contains"
    | "before"
    | "after"
    | "greater_than"
    | "less_than";
  /**
   * Value to compare against. Type depends on the field and operator.
   */
  value: unknown;
}

/**
 * Represents a sort specification for task queries.
 */
export interface ITaskSort {
  field: keyof ITask | string;
  direction: "asc" | "desc";
}

/**
 * Represents a grouping specification for task queries.
 */
export interface ITaskGroup {
  field: keyof ITask | string;
}

/**
 * Represents a query for tasks.
 */
export interface ITaskQuery {
  /**
   * Filters to apply to tasks.
   */
  filters?: ITaskFilter[];

  /**
   * Sorting to apply to tasks.
   */
  sorting?: ITaskSort[];

  /**
   * Grouping to apply to tasks.
   */
  grouping?: ITaskGroup[];

  /**
   * Limit the number of results.
   */
  limit?: number;
}

/**
 * Interface for managing tasks across the workspace.
 * Provides CRUD operations, in-memory cache, and event notification.
 * @see Obsidian Tasks for reference functionality.
 * @remarks
 * Interface name uses 'I' prefix for consistency.
 */
export interface IWorkspaceTaskManager {
  /**
   * Add tasks for a file.
   * @param filePath Path to the file
   * @param tasks Array of tasks to add
   */
  addTasks(filePath: string, tasks: ITask[]): void;

  /**
   * Remove all tasks for a file.
   * @param filePath Path to the file
   */
  removeTasks(filePath: string): void;

  /**
   * Update a task.
   * @param taskId ID of the task to update
   * @param updates Partial task object with updates
   * @returns true if the task was updated, false otherwise
   */
  updateTask(taskId: string, updates: Partial<ITask>): boolean;

  /**
   * Get all tasks across all files.
   * @returns Array of all tasks
   */
  getAllTasks(): ITask[];

  /**
   * Get tasks for a specific file.
   * @param filePath Path to the file
   * @returns Array of tasks in the file
   */
  getTasksByFile(filePath: string): ITask[];

  /**
   * Find tasks that match a predicate.
   * @param predicate Function that returns true for matching tasks
   * @returns Array of matching tasks
   */
  findTasks(predicate: (task: ITask) => boolean): ITask[];

  /**
   * Event that fires when tasks change.
   */
  onDidTasksChange: import('vscode').Event<{
    added?: ITask[];
    removed?: ITask[];
    updated?: ITask[];
  }>;
}

// the overridden signatures need to be assignment compatible, but
// due to how tuple types work[0] it's not possible to be assignment
// compatible anymore. This hack fixes it with a unique symbol that
// won't ever show up in parameter help etc.
//
// Unfortunately, this has the result of giving a poor error message when
// you mix up types.
// 0: https://github.com/Microsoft/TypeScript/issues/26013)
declare const assignmentCompatibilityHack: unique symbol;

// Returns any keys of TRecord with the type of TMatch
export type MatchingKeys<
  TRecord,
  TMatch,
  K extends keyof TRecord = keyof TRecord
> = K extends (TRecord[K] extends TMatch ? K : never) ? K : never;

// Returns any property keys of Record with a void type
export type VoidKeys<Record> = MatchingKeys<Record, void>;

// TODO: Stash under a symbol key once TS compiler bug is fixed
export interface TypeRecord<T, U, V> {
  ' _emitterType'?: T;
  ' _eventsType'?: U;
  ' _emitType'?: V;
}

export type ReturnTypeOfMethod<T> = T extends (...args: any[]) => any
  ? ReturnType<T>
  : void;

export type ReturnTypeOfMethodIfExists<T, S extends string> = S extends keyof T
  ? ReturnTypeOfMethod<T[S]>
  : void;

export type InnerEEMethodReturnType<T, TValue, FValue> = T extends (
  ...args: any[]
) => any
  ? ReturnType<T> extends void | undefined ? FValue : TValue
  : FValue;

export type EEMethodReturnType<
  T,
  S extends string,
  TValue,
  FValue = void
> = S extends keyof T ? InnerEEMethodReturnType<T[S], TValue, FValue> : FValue;

export type ListenerType<T> = [T] extends [(...args: infer U) => any]
  ? U
  : [T] extends [void] ? [] : [T];

// EventEmitter method overrides
export type OverriddenMethods<
  TEmitter,
  TEventRecord,
  TEmitRecord = TEventRecord
> = {
  on<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'on', T>;
  on(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  addListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'addListener', T>;
  addListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  addEventListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'addEventListener', T>;
  addEventListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  removeListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: any[]) => any
  ): EEMethodReturnType<TEmitter, 'removeListener', T>;
  removeListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  removeEventListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: any[]) => any
  ): EEMethodReturnType<TEmitter, 'removeEventListener', T>;
  removeEventListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  once<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'once', T>;
  once(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  emit<P extends keyof TEmitRecord, T>(
    this: T,
    event: P,
    ...args: ListenerType<TEmitRecord[P]>
  ): EEMethodReturnType<TEmitter, 'emit', T>;
  emit(event: typeof assignmentCompatibilityHack, ...args: any[]): void;
};

export type OverriddenKeys = keyof OverriddenMethods<any, any, any>;

export type StrictEventEmitter<
  TEmitterType,
  TEventRecord,
  TEmitRecord = TEventRecord,
  UnneededMethods extends Exclude<OverriddenKeys, keyof TEmitterType> = Exclude<
    OverriddenKeys,
    keyof TEmitterType
  >,
  NeededMethods extends Exclude<OverriddenKeys, UnneededMethods> = Exclude<
    OverriddenKeys,
    UnneededMethods
  >
> =
  // Store the type parameters we've instantiated with so we can refer to them later
  TypeRecord<TEmitterType, TEventRecord, TEmitRecord> &
    // Pick all the methods on the original type we aren't going to override
    Pick<TEmitterType, Exclude<keyof TEmitterType, OverriddenKeys>> &
    // Finally, pick the needed overrides (taking care not to add an override for a method
    // that doesn't exist)
    Pick<
      OverriddenMethods<TEmitterType, TEventRecord, TEmitRecord>,
      NeededMethods
    >;

export default StrictEventEmitter;

export type NoUndefined<T> = T extends undefined ? never : T;

export type StrictBroadcast<
  TEmitter extends TypeRecord<any, any, any>,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >,
  VK extends VoidKeys<TEmitRecord> = VoidKeys<TEmitRecord>,
  NVK extends Exclude<keyof TEmitRecord, VK> = Exclude<keyof TEmitRecord, VK>
> = {
  <E extends NVK>(event: E, request: TEmitRecord[E]): any;
  <E extends VK>(event: E): any;
};

export type EventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEmitRecord | keyof TEventRecord;

export type OnEventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEventRecord;

export type EmitEventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEmitRecord;

