import {
  boolean,
  timestamp,
  pgTable,
  text,
  primaryKey,
  integer,
  pgEnum,
  json,
  unique,
  numeric,
} from "drizzle-orm/pg-core";

import { AdapterAccount } from "next-auth/adapters";
import { relations, sql } from "drizzle-orm";

export const accountTypeEnum = pgEnum("type", ["email", "google", "github"]);

export const users = pgTable("user", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  name: text("name").notNull(),
  email: text("email").notNull(),
  emailVerified: timestamp("emailVerified", { mode: "date" }),
  image: text("image"),
  bio: text("bio").notNull().default(""),
  createdAt: timestamp("createdAt", { mode: "date" })
    .default(sql`NOW()`)
    .notNull(),
  customFile: boolean("customImage").default(false),
  userImage: json("customUserImage"),
});

export const accounts = pgTable(
  "account",
  {
    userId: text("userId")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    type: text("type").$type<AdapterAccount["type"]>().notNull(),
    provider: text("provider").notNull(),
    providerAccountId: text("providerAccountId").notNull(),
    refresh_token: text("refresh_token"),
    access_token: text("access_token"),
    expires_at: integer("expires_at"),
    token_type: text("token_type"),
    scope: text("scope"),
    id_token: text("id_token"),
    session_state: text("session_state"),
  },
  (account) => ({
    compoundKey: primaryKey({
      columns: [account.provider, account.providerAccountId],
    }),
  })
);

export const verificationTokens = pgTable(
  "verificationToken",
  {
    identifier: text("identifier").notNull(),
    token: text("token").notNull(),
    expires: timestamp("expires", { mode: "date" }).notNull(),
  },
  (verificationToken) => ({
    compositePk: primaryKey({
      columns: [verificationToken.identifier, verificationToken.token],
    }),
  })
);

export const authenticators = pgTable(
  "authenticator",
  {
    credentialID: text("credentialID").notNull().unique(),
    userId: text("userId")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    providerAccountId: text("providerAccountId").notNull(),
    credentialPublicKey: text("credentialPublicKey").notNull(),
    counter: integer("counter").notNull(),
    credentialDeviceType: text("credentialDeviceType").notNull(),
    credentialBackedUp: boolean("credentialBackedUp").notNull(),
    transports: text("transports"),
  },
  (authenticator) => ({
    compositePK: primaryKey({
      columns: [authenticator.userId, authenticator.credentialID],
    }),
  })
);

export const sessions = pgTable("session", {
  sessionToken: text("sessionToken").primaryKey(),
  userId: text("userId")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  expires: timestamp("expires", { mode: "date" }).notNull(),
});

export const organizations = pgTable("organizations", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  name: text("name").notNull(),
  thumbnail: json("thumbnail"),
  createdAt: timestamp("createdOn", { mode: "date" })
    .notNull()
    .default(sql`NOW()`),
  creator: text("creatorId")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  images: json("images"),
  email: text("email"),
  address: text("address"),
  phoneNumber: text("phoneNumber"),
  bio: text("bio"),
  latitude: numeric("latitude"),
  longitude: numeric("longitude"),
});

export const skills = pgTable("skills", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  name: text("name").notNull(),
  iconUrl: text("iconUrl").notNull(),
});

export const listings = pgTable("listings", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  name: text("name").notNull(),
  description: text("description").notNull(),
  thumbnail: text("thumbnail"),
  organizationId: text("organization")
    .notNull()
    .references(() => organizations.id, { onDelete: "cascade" }),
  createdAt: timestamp("createdAt", { mode: "date" })
    .default(sql`NOW()`)
    .notNull(),
  address: text("address"),
  latitude: numeric("latitude"),
  longitude: numeric("longitude"),
});

export const conversationsToUsers = pgTable(
  "conversations_to_users",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    conversationId: text("conversationId").references(() => conversations.id, {
      onDelete: "cascade",
    }),
    userId: text("userId").references(() => users.id, {
      onDelete: "cascade",
    }),
    organizationId: text("organizationId").references(() => organizations.id, {
      onDelete: "cascade",
    }),
  },
  (t) => ({
    unq: unique().on(t.conversationId, t.userId),
    unq2: unique().on(t.conversationId, t.organizationId),
  })
);

export const conversations = pgTable("conversations", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  subject: text("subject"),
});

//Assisted with basic coding tools, prompt: How would I create a messenger that allows users to send pictures back and forth? Is there a way I can store messages inside of a postgres table using drizzle to allow text or pictures or is there another way I can do this? Should I store html inside of my table?

export const messages = pgTable("messages", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  content: json("content"), // Text content of the message (nullable if sending an image)
  messageType: integer("messageType").notNull(), // 0 for text, 1 for images
  createdAt: timestamp("createdAt", { mode: "date" })
    .notNull()
    .default(sql`NOW()`), // Timestamp
  conversationId: text("conversation_id").references(() => conversations.id, {
    onDelete: "cascade",
  }),
  senderId: text("sender_user_id").references(() => users.id),
  senderOrganizationId: text("sender_organization_id").references(
    () => organizations.id
  ),
});

export const skillsToListings = pgTable(
  "listings_skills",
  {
    skillId: text("skill_id")
      .notNull()
      .references(() => skills.id, { onDelete: "cascade" }),
    listingId: text("listingId")
      .notNull()
      .references(() => listings.id, { onDelete: "cascade" }),
  },
  (table) => ({
    pk: primaryKey({ columns: [table.listingId, table.skillId] }),
  })
);

export const skillsToUsers = pgTable(
  "volunteer_skills",
  {
    skillId: text("skill_id")
      .notNull()
      .references(() => skills.id, { onDelete: "cascade" }),
    volunteerId: text("userId")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
  },
  (table) => ({
    pk: primaryKey({ columns: [table.volunteerId, table.skillId] }),
  })
);

export const listingsToUsers = pgTable(
  "listing_volunteers",
  {
    listingId: text("listing_id")
      .notNull()
      .references(() => listings.id, { onDelete: "cascade" }),
    volunteerId: text("userId")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    dateSignedUp: timestamp("dateSignedUp", { mode: "date" })
      .notNull()
      .default(sql`NOW()`),
  },
  (table) => ({
    pk: primaryKey({ columns: [table.volunteerId, table.listingId] }),
  })
);

export const conversationsRelations = relations(
  conversations,
  ({ one, many }) => ({
    conversations: many(conversationsToUsers),
    messages: many(messages),
  })
);

export const conversationsToUsersRelations = relations(
  conversationsToUsers,
  ({ one, many }) => ({
    user: one(users, {
      fields: [conversationsToUsers.userId],
      references: [users.id],
    }),
    organization: one(organizations, {
      fields: [conversationsToUsers.organizationId],
      references: [organizations.id],
    }),
    conversation: one(conversations, {
      fields: [conversationsToUsers.conversationId],
      references: [conversations.id],
    }),
  })
);

export const listingsToUsersRelations = relations(
  listingsToUsers,
  ({ one }) => ({
    volunteers: one(users, {
      fields: [listingsToUsers.volunteerId],
      references: [users.id],
    }),
    listings: one(listings, {
      fields: [listingsToUsers.listingId],
      references: [listings.id],
    }),
  })
);

export const organizationsRelations = relations(
  organizations,
  ({ many, one }) => ({
    listings: many(listings),
    users: one(users, {
      fields: [organizations.creator],
      references: [users.id],
    }),
    conversationsToUsers: many(conversationsToUsers),
    messages: many(messages),
  })
);

export const skillsRelations = relations(skills, ({ many }) => ({
  listings: many(skillsToListings),
  volunteers: many(skillsToUsers),
}));

export const volunteerRelations = relations(users, ({ many }) => ({
  skills: many(skillsToUsers),
  user_to_user_senderMessages: many(conversationsToUsers),
  organizations: many(organizations),
  listings: many(listingsToUsers),
  messages: many(messages),
  conversationsToUsers: many(conversationsToUsers),
}));

export const listingsRelations = relations(listings, ({ many, one }) => ({
  skills: many(skillsToListings),
  organizations: one(organizations, {
    fields: [listings.organizationId],
    references: [organizations.id],
  }),
  volunteers: many(listingsToUsers),
}));

export const messagesRelations = relations(messages, ({ one, many }) => ({
  senderUser: one(users, {
    fields: [messages.senderId],
    references: [users.id],
  }),
  senderOrganization: one(organizations, {
    fields: [messages.senderOrganizationId],
    references: [organizations.id],
  }),
  conversation: one(conversations, {
    fields: [messages.conversationId],
    references: [conversations.id],
  }),
}));

export const skillsToListingsRelations = relations(
  skillsToListings,
  ({ one }) => ({
    skills: one(skills, {
      fields: [skillsToListings.skillId],
      references: [skills.id],
    }),
    listings: one(listings, {
      fields: [skillsToListings.listingId],
      references: [listings.id],
    }),
  })
);

export const skillsToVolunteersRelations = relations(
  skillsToUsers,
  ({ one }) => ({
    skills: one(skills, {
      fields: [skillsToUsers.skillId],
      references: [skills.id],
    }),
    volunteers: one(users, {
      fields: [skillsToUsers.volunteerId],
      references: [users.id],
    }),
  })
);

export type User = typeof users.$inferSelect;
export type Organizations = typeof organizations.$inferSelect;

/* Changelog:
 *
 * V1.0.0 - Initial version
 * V1.1.0 - Migrated from dateformat to moment.js
 * V1.2.0 - Introduced option for linebreak after insert
 * V1.3.0 - Enter-key in the text field closes the dialog and inserts time/date stamp
 * 
 */

import { settings } from 'cluster';
import {
	App,
	ButtonComponent,
	Editor,
	Modal,
	Plugin,
	TextComponent,
	PluginSettingTab,
	Setting,
	moment,
	View
} from 'obsidian';

interface OtsPluginSettings {
	timeStampFormat: string;
	dateStampFormat: string;
	lastFormat: string;
	newLine: boolean;
}

const DEFAULT_SETTINGS: OtsPluginSettings = {
	timeStampFormat: 'hh:mm:ss',
	dateStampFormat: 'YYYY-MM-DD',
	lastFormat: '',
	newLine: false
}

// logThreshold: 0 ... only error messages
//               9 ... verbose output
const logThreshold = 9;
const logger = (logString: string, logLevel=0): void => {if (logLevel <= logThreshold) console.log ('TimeStamper: ' + logString)};
const version = '1.3.0-0002'

export default class TimeStamperPlugin extends Plugin {
	settings: OtsPluginSettings;

	async onload() {
		logger('Loading Plugin v' + version, 1);
		logger('Loading Settings... ', 5);
		await this.loadSettings();
		logger('  Done', 5);

		this.addSettingTab(new TimeStamperSettingTab(this.app, this));

		this.addCommand({
			id: 'obsidian-custom-timestamp',
			name: 'Insert custom time/date stamp',
			editorCallback: (editor) => {
				new TimeStamperModal(this.app, editor, this.settings, this).open();
			},
		});


		this.addCommand({
			id: 'obsidian-fast-timestamp',
			name: 'Insert preconfigured time stamp',
			editorCallback: (editor) => {
				const now = new Date();
				const stamp = moment(now).format(this.settings.timeStampFormat);
				if (this.settings.newLine) {
					editor.replaceSelection(stamp + '\n');
					logger('new line', 9);
				}
				else {
					editor.replaceSelection(stamp);
					logger('no new line', 9);
				}
			}
		});

		this.addCommand({
			id: 'obsidian-fast-datestamp',
			name: 'Insert preconfigured date stamp',
			editorCallback: (editor) => {
				const now = new Date();
				const stamp = moment(now).format(this.settings.dateStampFormat);
				if (this.settings.newLine) {
					editor.replaceSelection(stamp + '\n');
					logger('new line', 9);
				}
				else {
					editor.replaceSelection(stamp);
					logger('no new line', 9);
				}
			}
		});
	}

	onunload() {
		logger('Bye!', 9);
	}

	async loadSettings() {
		logger('Loading Settings...', 5);
		this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
		logger('  - timeStampFormat: ' + this.settings.timeStampFormat, 6);
		logger('  - dateStampFormat: ' + this.settings.dateStampFormat, 6);
		logger('  - lastFormat:      ' + this.settings.lastFormat, 6);
	}

	async saveSettings() {
		logger('Saving Settings...', 5);
		await this.saveData(this.settings);
		logger('  Done.');
	}

}

class TimeStamperModal extends Modal {
	constructor(app: App, editor: Editor, settings: OtsPluginSettings, plugin: Plugin) {
		super(app);
		this.editor = editor;
		this.settings = settings;
		this.plugin = plugin;
	}

	settings: OtsPluginSettings;
	editor: Editor;
	plugin: Plugin;

	onOpen() {
		const { contentEl, editor, modalEl } = this;
		const rowClass = 'row';
		const divClass = 'div';
		const _this = this;
		const doStamp = (): void => {
			const now = new Date();
			const stampFormat = formatComponent.getValue();
			const stamp = moment(now).format(stampFormat);
			if (_this.settings.newLine) {
				editor.replaceSelection(stamp + '\n');
				logger('new line', 9);
			}
			else {
				editor.replaceSelection(stamp);
				logger('no new line', 9);
			}

			// Save entered stamp format to settings
			_this.settings.lastFormat = stampFormat;
			_this.plugin.saveData(_this.settings);
			_this.close();

			editor.scrollIntoView({
				from: editor.getCursor(),
				to: editor.getCursor(),
				})
		};

		modalEl.addClass('timestamper-modal');

		// Create label and text field
		const containerEl = document.createElement(divClass);
		containerEl.addClass(rowClass);

		const targetEl = document.createElement(divClass);
		targetEl.addClass('input-wrapper');

		const labelEl = document.createElement(divClass);
		labelEl.addClass('input-label');
		labelEl.setText('Format string:');

		const formatComponent = new TextComponent(targetEl);
		formatComponent.setPlaceholder('e.g. YYYY-MM-DD');
		formatComponent.setValue(this.settings.lastFormat);

		// Add listener for <Enter> key
		formatComponent.inputEl.addEventListener('keypress', (keypressed) => {
			if (keypressed.key === 'Enter')	doStamp(); 
		});

		// Create Button
		const buttonContainerEl = document.createElement(divClass);
		buttonContainerEl.addClass(rowClass);

		const submitButtonTarget = document.createElement(divClass);
		submitButtonTarget.addClass('button-wrapper');

		const submitButtonComponent = new ButtonComponent(submitButtonTarget);
		submitButtonComponent.setButtonText('Insert Date/Time Stamp');
		submitButtonComponent.setCta();
		submitButtonComponent.onClick(doStamp);
		// submitButtonComponent.buttonEl.addEventListener('click', (e) => doStamp)

		// Add components to layout
		containerEl.appendChild(labelEl);
		containerEl.appendChild(targetEl);
		buttonContainerEl.appendChild(submitButtonTarget);

		contentEl.append(containerEl);
		contentEl.append(buttonContainerEl);

		submitButtonComponent.buttonEl.focus();
	}

	onClose() {
		const { contentEl } = this;
		contentEl.empty();
	}
}

class TimeStamperSettingTab extends PluginSettingTab {
	plugin: TimeStamperPlugin;

	constructor(app: App, plugin: TimeStamperPlugin) {
		super(app, plugin);
		this.plugin = plugin;
	}

	display(): void {
		const {containerEl} = this;
		containerEl.empty();

		new Setting(containerEl)
			.setName('Date Stamp Template')
			.setDesc('Template String for inserting a date stamp')
			.addText(text => text
				.setValue(this.plugin.settings.dateStampFormat)
				.onChange(async (value) => {
					logger('Settings update - Date Stamp: ' + value, 5);
					this.plugin.settings.dateStampFormat = value;
					await this.plugin.saveSettings();
				}));

		new Setting(containerEl)
			.setName('Time Stamp Template')
			.setDesc('Template String for inserting a time stamp')
			.addText(text => text
				.setValue(this.plugin.settings.timeStampFormat)
				.onChange(async (value) => {
					logger('Settings update - Time Stamp: ' + value, 5);
					this.plugin.settings.timeStampFormat = value;
					await this.plugin.saveSettings();
				}));

		new Setting(containerEl)
		    .setName('Insert line break')
			.setDesc('Add a line break after the time/date stamp')
			.addToggle(toggle => toggle
				.setValue(this.plugin.settings.newLine)
				.onChange(async (value) => {
					logger('Settings update - Insert Line Break: ' + value, 5);
					this.plugin.settings.newLine = value;
					await this.plugin.saveSettings();
				}));
	}
}

/**
 * Storing ABIs in Human-Readable ABI format.
 * https://blog.ricmoo.com/human-readable-contract-abis-in-ethers-js-141902f4d917
 */

export const TokenAbi = "tuple(address address, string name, string symbol, uint256 decimals)";
export const TokenPriceAbi = "tuple(address address, uint256 priceUsdc)";
export const TokenBalanceAbi = `tuple(
  address address, 
  uint256 priceUsdc, 
  uint256 balance,
  uint256 balanceUsdc
)`;
export const AllowanceAbi = "tuple(address owner, address spender, uint256 amount, address token)";

export const AssetStaticAbi = `tuple(
  address address,
  string typeId,
  address token,
  string name,
  string version,
  string symbol,
  uint8 decimals,
)`;

export const AssetDynamicAbi = (Metadata: string): string => `tuple(
  address address, 
  string typeId,
  address tokenId,
  tuple(uint256 amount, uint256 amountUsdc) underlyingTokenBalance,
  ${Metadata} metadata
)`;

export const PositionAbi =
  "tuple(address assetAddress, address tokenAddress, string typeId, uint256 balance," +
  "tuple(uint256 amount, uint256 amountUsdc) underlyingTokenBalance," +
  "tuple(address owner, address spender, uint256 amount)[] tokenAllowances," +
  "tuple(address owner, address spender, uint256 amount)[] assetAllowances)";

export const AdapterAbi = (Metadata: string): string[] => [
  `function assetsStatic() public view returns (${AssetStaticAbi}[] memory)`,
  `function assetsStatic(address[] memory) public view returns (${AssetStaticAbi}[] memory)`,
  `function assetsDynamic() public view returns (${AssetDynamicAbi(Metadata)}[] memory)`,
  `function assetsDynamic(address[] memory) public view returns (${AssetDynamicAbi(Metadata)}[] memory)`,
  `function assetsPositionsOf(address) public view returns (${PositionAbi}[] memory)`,
  `function assetsPositionsOf(address, address[] memory) public view returns (${PositionAbi}[] memory)`,
  `function assetsTokensAddresses() public view returns (address[] memory)`,
];

export const AddressMetadataAbi = `tuple(string addrId, address addr)`;

import { useEffect, useState } from 'react';

// Assisted using common GitHub development utilities
export function useScreenSize(): { width: number; height: number } {
  const [size, setSize] = useState({ width: window.innerWidth, height: window.innerHeight });

  useEffect(() => {
    const handleResize = () => setSize({ width: window.innerWidth, height: window.innerHeight });
    window.addEventListener('resize', handleResize);

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return size;
}

