import { bubbleData, EVENT } from "./Interface";
import Bubble from "./Bubble";
import Util from "./Util";

const {ccclass, property} = cc._decorator;

@ccclass
export default class BubbleMgr extends cc.Component {

    /** 泡泡纹理 */
    @property([cc.SpriteFrame]) bubbleSpriteFrame: cc.SpriteFrame[] = [];
    /** 预制体 */
    @property(cc.Prefab) bubblePrefab: cc.Prefab = null;
    /** 确认发射点 */
    @property(cc.Node) shooter: cc.Node = null;
    /** 关卡数据 */
    @property(cc.JsonAsset) levelData: cc.JsonAsset = null;

    /** 装载场景中所有泡泡，注意 s 这是二维数组 */
    public bubblesArray: bubbleData[][] = [];
    /** 当前待发射球 */
    public shootBubble: bubbleData;
    /** 是否正在射击的标志 */
    public isShooting: boolean = false;
    /** 射出方向 */
    public shootDir: cc.Vec2 = null;

    public onLoad (): void {
        this.init("lv1");
        // 监听触摸结束
        cc.director.on(EVENT.TOUCHEND_SHOOT, (data) => {
            console.log('BubbleMgr -on -touchend');
            // console.log(data);
            // FIX: 小球飞行时不应触发点击事件
            if (this.isShooting) { return }
            // 转为弧度
            let r = cc.misc.degreesToRadians(data);
            // 分量 x - sin  y - cos
            this.shootDir = cc.v2(-Math.sin(r), Math.cos(r));
            console.log(this.shootDir);
            // 开启射击
            this.isShooting = true;
        }, this);

        this._createOneShooter();
    }

    public update (dt: number) {
        if (this.isShooting) {
            // 小球移动
            this._bubbleMove(dt);
            this._isCollided();
        }
    }

    /** 检测碰撞 */
    private _isCollided (): void {
        for (let row = 0; row < this.bubblesArray.length; row++) {
            for (let col = 0; col < this.bubblesArray[row].length; col++) {
                // 是否存在小球
                if (!this.bubblesArray[row][col]) continue;
                let n: cc.Node = this.bubblesArray[row][col].node;
                // 先看 y 轴
                let offsetY = Math.abs(n.y - this.shootBubble.node.y);
                if (offsetY > Util.BUBBLE_R * 2) continue;
                // 再看 x 轴
                let offsetX = Math.abs(n.x - this.shootBubble.node.x);
                if (offsetX > Util.BUBBLE_R * 2) continue;
                // 再做乘法
                let dis = offsetX * offsetX + offsetY * offsetY;
                if (dis > Util.BUBBLE_R * 2 * Util.BUBBLE_R * 2) continue;
                // 在范围内，触发碰撞，停止射击移动
                this.isShooting = false;
                // 位置修正
                this._setBubblePos();
                // 如果有小球符合条件，return
                return;
            }
        }
        // 没触发碰撞且碰到最上方
        if (this.shootBubble.node.y > Util.SCREEN_H - Util.BUBBLE_R) {
            this.isShooting = false;
            // 位置修正
            this._setBubblePos();
        }
    }

    /** 根据停止位置，修正 */
    private _setBubblePos (): void {
        let index: cc.Vec2 = Util.convertPosToRowCol(this.shootBubble.node.x, this.shootBubble.node.y);
        this.shootBubble.node.position = Util.convertRowColToPos(index.x, index.y);
        // 设置对应数据
        let obj: bubbleData = Object.create(null);
        obj.node = this.shootBubble.node;
        obj.color = this.shootBubble.color;
        obj.isLinked = false;
        obj.isVisited = false;
        this.bubblesArray[index.x][index.y] = obj;
        // 应该遍历相同颜色的泡泡了
        this._mapColor(index);
    }

    /** 相同颜色检测，传入当前小球位置 */
    private _mapColor (index: cc.Vec2): void {
        // 检测消除方法
        let test: Function = (row: number, col: number, color: number) => {
            // 非空检测
            if (!this.bubblesArray[row] || !this.bubblesArray[row][col]) return;
            // 获取泡泡数据
            let b: bubbleData = this.bubblesArray[row][col];
            // 如果被访问过
            if (b.isVisited) return;
            // 如果颜色不同
            if (b.color !== color) return;
            // 符合条件
            b.isVisited = true;
            let leftTop = col;
            // 根据不同的行做偏移
            if (row % 2 === 0) {
                leftTop = col - 1;
            }
		    // 每个泡泡周围有6个,依次检测
		    // 左上
		    test(row - 1, leftTop, color);
		    //右上
		    test(row - 1, leftTop + 1, color);
		    //左
		    test(row, col - 1, color);
		    //右
		    test(row, col + 1, color);
		    //左下
		    test(row + 1, leftTop, color);
		    //右下
		    test(row + 1, leftTop + 1, color);
        }

        // 执行
        test(index.x, index.y, this.bubblesArray[index.x][index.y].color);
        // 看有几个相同的
        let count: number = 0;
        // 记录消除行列值
        let record: cc.Vec2[] = [];
        for (let row = 0; row < this.bubblesArray.length; row++) {
            for (let col = 0; col < this.bubblesArray[row].length; col++) {
                if (!this.bubblesArray[row][col]) continue;
                if (this.bubblesArray[row][col].isVisited) {
                    this.bubblesArray[row][col].isVisited = false;
                    count ++;
                    // 记录要进行消除的泡泡行列值
                    record.push(cc.v2(row, col));
                }
            }
        }
        if (count >= 3) {
            // 执行消除
            for (let i in record) {
                // 获取到该位置泡泡，执行消除
                let b = this.bubblesArray[record[i].x][record[i].y].node;
                b.getComponent(Bubble).playDeathAnimation(record[i]);
            }
            this.scheduleOnce(this._testUnLinked, 0.3);
            // this.scheduleOnce(this._nextBubble, 0.3);
        } else {
           this._nextBubble();
        }
    }

    /** 悬空检测 同理 */
    private _testUnLinked (): void {
        // 检测方法
        let test: Function = (row: number, col: number) => {
            //从刚刚加入的泡泡为起点,递归寻找相连的
            if (!this.bubblesArray[row] || !this.bubblesArray[row][col]) return;
            let b = this.bubblesArray[row][col];
            if (b.isVisited) return;
            // 符合条件
            b.isVisited = true;
            b.isLinked = true;
            let leftTop = col;
            if (row % 2 === 0) {
                leftTop = col - 1;
            }
		    // 每个泡泡周围有6个,依次检测
		    // 左上
		    test(row - 1, leftTop);
		    //右上
		    test(row - 1, leftTop + 1);
		    //左
		    test(row, col - 1);
		    //右
		    test(row, col + 1);
		    //左下
		    test(row + 1, leftTop);
		    //右下
		    test(row + 1, leftTop + 1);
        }
        // 执行
        for (let i = 0; i < this.bubblesArray[0].length; i++) {
            // 执行最上的一排泡泡
            if (!this.bubblesArray[0][i]) continue;
            test(0, i);
        }

        // 局部标志，是否执行过下落
        let flag: boolean = true;
        for (let row = 0; row < this.bubblesArray.length; row++) {
            for (let col = 0; col < this.bubblesArray[row].length; col++) {
                if (!this.bubblesArray[row][col]) continue;
                if (!this.bubblesArray[row][col].isLinked) {
                    flag = false;
                    let b = this.bubblesArray[row][col].node;
                    b.getComponent(Bubble).playDownAnimation(cc.v2(row, col));
                } else {
                    this.bubblesArray[row][col].isVisited = false;
                    this.bubblesArray[row][col].isLinked = false;
                }
            }
        }
        if (flag) {
            this._nextBubble();
        } else {
            this.scheduleOnce(this._nextBubble, 0.6);
        }
    }

    private _nextBubble (): void {
        // 继续游戏
        this._createOneShooter();
    }

    private _bubbleMove (dt: number): void {
        // 移动速度
        let speed = 1000;
        let n: cc.Node = this.shootBubble.node;
        // 左右出区域要改向 因为不知正负，先求绝对值
        if (n.x < Util.BUBBLE_R) this.shootDir.x = Math.abs(this.shootDir.x);
        if (n.x > Util.SCREEN_W - Util.BUBBLE_R) this.shootDir.x = -Math.abs(this.shootDir.x);
        n.x += this.shootDir.x * speed * dt;
        n.y += this.shootDir.y * speed * dt;
    }

    // 根据数据初始化
    public init (str: string): void {
        // 获取到关卡数据
        let data: [][] = this.levelData.json[str];
        // 将所有数据遍历，0代表空
        for (let row = 0; row < data.length; row++) {
            let colBubbleData: bubbleData[] = data[row];
            // 一起初始化一下 bubblesArray
            this.bubblesArray[row] = [];
            for (let col = 0; col < colBubbleData.length; col++) {
                let color = data[row][col];
                if (color === 0) continue;
                // 实例化泡泡
                let b = cc.instantiate(this.bubblePrefab);
                // 行列 -> 坐标
                let pos = Util.convertRowColToPos(row, col);
                // 调用泡泡初始化
                b.getComponent(Bubble).init(this, pos, this.bubbleSpriteFrame[color-1]);
                // 往bubblesArray 里 设置对应数据
                let obj: bubbleData = Object.create(null);
                obj.node = b;
                obj.color = color;
                obj.isLinked = false;
                obj.isVisited = false;
                this.bubblesArray[row][col] = obj;
            }
        }
    }

    /** 创造发射小球 */
    private _createOneShooter (): void {
        let b = cc.instantiate(this.bubblePrefab);
        let color = Util.randNum(1, 4);
        b.getComponent(Bubble).init(this, this.shooter.position, this.bubbleSpriteFrame[color-1]);
        // 设置对应数据
        let obj: bubbleData = Object.create(null);
        obj.node = b;
        obj.color = color;
        obj.isLinked = false;
        obj.isVisited = false;
        // 指定当前 shootBubble
        this.shootBubble = obj;
    }

}

import {
  ApolloClient,
  InMemoryCache,
  ApolloLink,
  HttpLink,
} from "@apollo/client";
import { request } from "http";

// this has the latest subgraph for now, may need to be updated later
const umaLinkKovan = new HttpLink({
  uri: "https://api.thegraph.com/subgraphs/name/umaprotocol/kovan-contracts",
});
const umaLinkMainnet = new HttpLink({
  uri: "https://api.thegraph.com/subgraphs/name/umaprotocol/mainnet-contracts",
});
const balancerLink = new HttpLink({
  uri: "https://api.thegraph.com/subgraphs/name/balancer-labs/balancer",
});

const uniswapV2Link = new HttpLink({
  uri: "https://api.thegraph.com/subgraphs/name/uniswap/uniswap-v2",
});
// Uses ApolloLink's directional composition logic, docs: https://www.apollographql.com/docs/react/api/link/introduction/#directional-composition
const umaLinks = ApolloLink.split(
  (operation) => operation.getContext().clientName === "UMA42",
  umaLinkKovan,
  umaLinkMainnet
);

const otherLinks = ApolloLink.split(
  (operation) => operation.getContext().clientName === "BALANCER",
  balancerLink,
  uniswapV2Link
);
export const client = new ApolloClient({
  cache: new InMemoryCache(),
  // We handle more than 2 links by composing directional composition, idea from: https://www.loudnoises.us/next-js-two-apollo-clients-two-graphql-data-sources-the-easy-way/
  link: ApolloLink.split(
    (operation) => operation.getContext().clientName.includes("UMA"),
    umaLinks,
    otherLinks
  ),
});

import { Scenario } from "../Scenario.js";
import { Channel, Client, EmbedBuilder, User } from "discord.js";
import Lt from "long-timeout";
import { off } from "process";

export interface ShowOrMovie extends PollItem {}

const hoursToMs = 3600000;

function msToDurationString(durationMS: number): string {

	let durationSecs = durationMS / 1000;

	let days = Math.floor(durationSecs / (24 * 60 * 60));
	durationSecs = durationSecs % (24 * 60 * 60);

	let hours = Math.floor(durationSecs / (60 * 60));
	durationSecs = durationSecs % (60 * 60);

	let minutes = Math.floor(durationSecs / 60);
	let seconds = Math.floor(durationSecs % 60);

	return `${days > 0 	? days + "d " 		: ""}`
		+ `${hours > 0 		? hours + "h " 		: ""}`
		+ `${minutes > 0 	? minutes + "m " 	: ""}`
		+ `${seconds > 0 	? seconds + "s " 	: ""}`;
}

export interface PollItem {
	uid: string;
	name: string,
	img_url: string,
	url: string
}

interface InternalItem<ItemType> {
	nominator: string,
	item: ItemType
}

interface SaveState<ItemType> {
	creatorID: string,
	nominationLimit: number,
	items: { [key: string]: InternalItem<ItemType> }
	voteTime: string,
	endTime: string,
	isVoting: boolean,
	votes: [string, string[]][]
}

export default class PollScenario<ItemType extends Required<PollItem>> extends Scenario {

	private _isVoting = false;
	private _creatorID: string = "";

	private _nominationLimit = 1;
	private _nominees: Map<string, InternalItem<ItemType>> = new Map;

	private _voteTime = new Date(0);
	private _voteTimeout: Lt.Timeout | null = null;

	private _endTime = new Date(0);
	private _endTimeout: Lt.Timeout | null = null;

	private _votes: Map<string, Array<string>> = new Map;

	// #region Scenario

	init(): void {

		this.loadState();
		this.updateVoteTimeout();
		this.updateEndTimeout();

	}

	shutdown() {

		if(this._voteTimeout)
			Lt.clearTimeout(this._voteTimeout);

		if(this._endTimeout)
			Lt.clearTimeout(this._endTimeout);

		this.controls.Clean();
	}

	get isPersistant() {
		return true;
	}

	// #endregion

	configurePoll(creatorID: string, hoursBeforeVote: number, hoursVoting: number, nominationLimit: number) {

		this._creatorID = creatorID;
		this._voteTime = new Date(Date.now() + (hoursBeforeVote * hoursToMs));
		this._endTime = new Date(this._voteTime.getTime() + (hoursVoting * hoursToMs));

		if(nominationLimit)
			this._nominationLimit = nominationLimit;

		this.saveState();
		this.updateVoteTimeout();
		this.updateEndTimeout();
	}

	isCreator(toCheck: User): boolean {
		return toCheck.id == this._creatorID;
	}

	isVoting(): boolean {
		return this._isVoting;
	}

	getVoteTime() : Date {
		return this._voteTime;
	}

	getEndTime() : Date {
		return this._endTime;
	}

	timeStatusString(): string {

		let out = "";
		let voteTime = this.getVoteTime();
		let voteTimeOffsetMS = voteTime.getTime() - Date.now();
		if(voteTimeOffsetMS > 0)
			out += `\nTime Until Vote: ${msToDurationString(voteTimeOffsetMS)}`;

		let endTime = this.getEndTime();
		let endTimeOffsetMs = endTime.getTime() - Math.max(voteTime.getTime(), Date.now());
		if(endTimeOffsetMs > 0)
			out += `\nVoting Time Left: ${msToDurationString(endTimeOffsetMs)}`;

		return out;
	}

	private async getMentionString() : Promise<string> {

		let mentionSet = new Set<string>();

		this._nominees.forEach((value) => {
			mentionSet.add(value.nominator);
		});

		Array.from(this._votes.keys()).forEach((value) => {
			mentionSet.add(value);
		});

		let out = "";
		let entryItr = mentionSet.entries();

		for(let [currUid] of entryItr) {

			let currUser = await this.client.users.fetch(currUid);
			out += `${currUser} `;

		}

		return out;

	}

	private onVoteTimeout = async () => {

		if(this._isVoting)
			return;

		this._isVoting = true;
		this.saveState();

		let mentionString = await this.getMentionString();

		let pollChannel = this.channel;
		if(pollChannel.isTextBased())
			pollChannel.send(`${mentionString}\n\n The nomination period has ended, you may now vote. Use \`/poll vote\`.`);

	}

	private onEndTimeout = async () => {

		let bordaCount = this.doBordaCount();

		let channel = this.channel;
		if(bordaCount.size <= 0 && channel.isTextBased()) {
			this.controls.End();
			return channel.send("Could not tally a winner; there were no votes.");
		}

		let sorted = sortMapToArray(bordaCount);
		let sortedItems = sorted.map((UID) => {
			return this._nominees.get(UID)!;
		});

		let maxPoints = (this._nominees.size - 1) * this._votes.size;
		let winner = sortedItems.splice(0, 1).at(0)!;
		sortedItems = sortedItems.splice(0, 25);
		let fields = sortedItems.map((currItem, index) => {

			let currCount = bordaCount.get(currItem.item.uid)!;
			return {
				name: `${index + 2}. ${currItem.item.name}`,
				value: `${currCount} Points (${currCount / maxPoints * 100}%)`
			}

		});

		if(channel.isTextBased()) {

			let mentions = await this.getMentionString();
			let winnerCount = bordaCount.get(winner.item.uid)!;
			channel.send({
				content: `${mentions}\n\n The poll has finished.`,
				embeds: [{
					title: `**The winner is ${winner.item.name}!**`,
					description: `${winnerCount} Points (${winnerCount / maxPoints * 100}%)`,
					image: { url: winner.item.img_url },
					color: 0xd4af37
				}, 

				new EmbedBuilder()
					.setFields(fields)
					.setColor(0xaaa9ad)

				]
			});

		}

		this.controls.End();
	}

	private saveState() {

		this.controls.Save({
			nominationLimit: this._nominationLimit,
			items: Object.fromEntries(this._nominees),
			voteTime: this._voteTime.toISOString(),
			endTime: this._endTime.toISOString(),
			isVoting: this._isVoting,
			creatorID: this._creatorID,
			votes: Array.from(this._votes.entries())
		} as SaveState<ItemType>);

	}

	private loadState() {

		let state = this.controls.Load() as SaveState<ItemType>;
		if(!state) return;
		if(Object.keys(state).length <= 0) return;

		this._nominationLimit = state.nominationLimit;
		this._nominees = new Map(Object.entries(state.items));
		this._voteTime = new Date(state.voteTime);
		this._endTime = new Date(state.endTime);
		this._isVoting = state.isVoting;
		this._creatorID = state.creatorID;
		this._votes = new Map(state.votes);

	}

	private canAddItem(nominatorID: string, toAdd: ItemType) : string | undefined {

		if(this._nominees.has(toAdd.uid))
			return "Item already exists.";

		let found = Array.from(this._nominees.entries()).filter(([UID, nominee]) => {
			return nominee.nominator == nominatorID;
		});

		if(found.length >= this._nominationLimit)
			return `Item limit reached. (${this._nominationLimit})`;

		return undefined;
	}

	addItem(nominatorID: string, toAdd: ItemType) : string | undefined{

		if(this._isVoting)
			return "Items cannot be added while the poll is voting.";

		let res = this.canAddItem(nominatorID, toAdd);
		if(res) return res;

		this._nominees.set(toAdd.uid, {nominator: nominatorID, item: toAdd});
		this.saveState();

		return undefined;

	}

	private canRemoveItem(nominatorID: string, uid: string, admin: boolean): string | undefined {

		if(!this._nominees.has(uid))
			return "Item doesn't exist.";

		let currItem = this._nominees.get(uid);
		if(!currItem)
			return "Failed to get item.";

		if(currItem.nominator != nominatorID && !admin)
			return "You do not have permission to remove that item.";

		return undefined;
	}

	removeItem(uid: string, nominatorID: string, admin: boolean) {

		if(this._isVoting)
			return "Items cannot be removed while the poll is voting.";

		let res = this.canRemoveItem(nominatorID, uid, admin);
		if(res) return res;

		this._nominees.delete(uid);
		this.saveState();

		return undefined;
	}

	getItem(uid: string) : ItemType | undefined {

		if(!this._nominees.has(uid))
			return undefined;

		return this._nominees.get(uid)?.item;

	}

	getNomineeList() : Array<ItemType> {

		return Array.from(this._nominees.values()).map((internalItem) => {
			return internalItem.item;
		});

	}

	setVoteTime(time: Date) {

		let offset = this._endTime.getTime() - this._voteTime.getTime();

		this._voteTime = time;
		this.saveState();
		this.updateVoteTimeout();

		this.setEndTime(new Date(this._voteTime.getTime() + offset));
	}

	setEndTime(time: Date) {

		this._endTime = time;
		this.saveState();
		this.updateEndTimeout();

	}

	private updateVoteTimeout() {

		let timeToVote = this._voteTime.getTime() - Date.now();

		if(this._voteTimeout)
			Lt.clearTimeout(this._voteTimeout);

		this._voteTimeout = Lt.setTimeout(this.onVoteTimeout, timeToVote);

	}

	private updateEndTimeout() {

		let timeToEnd = this._endTime.getTime() - Date.now();

		if(this._endTimeout)
			Lt.clearTimeout(this._endTimeout);

		this._endTimeout = Lt.setTimeout(this.onEndTimeout, timeToEnd);

	}

	setVote(userID: string, ranks: Array<string>) {

		this._votes.set(userID, ranks);
		this.saveState();

	}

	doBordaCount() : Map<string, number> {

		let outMap = new Map<string, number>();

		this._votes.forEach((rankList) => {

			rankList.forEach((itemUID, index) => {

				if(!outMap.has(itemUID))
					outMap.set(itemUID, 0);

				let pointValue = this._nominees.size - (index + 1);
				outMap.set(itemUID, (outMap.get(itemUID) ?? 0) + pointValue);

			});

		});

		return outMap;
	}

}

// Assisted with basic coding tools ========================================================
function sortMapToArray(map: Map<string, number>) {
  // Create an array of key-value pairs from the map
  const entries = Array.from(map);

  // Sort the array based on the ranking values
  entries.sort((a, b) => b[1] - a[1]);

  // Extract the keys (IDs) into a new array
  const ids = entries.map(([id]) => id);

  return ids;
} // ===========================================================================

/* AsyncTaskPool - something similar to Python's `multiprocessing.Pool()`
 * (Aided using common development resources) */

export class AsyncTaskPool {
  private poolSize: number
  private currentTasks: number
  private taskQueue: (() => Promise<void>)[]
  private completedTasks: number // To track the number of completed tasks

  constructor(poolSize: number) {
    this.poolSize = poolSize
    this.currentTasks = 0
    this.taskQueue = []
    this.completedTasks = 0
  }

  private runNextTask() {
    if (this.currentTasks < this.poolSize && this.taskQueue.length > 0) {
      const task = this.taskQueue.shift()
      if (task) {
        this.currentTasks++
        task()
          .then(() => {
            this.completedTasks++
          })
          .finally(() => {
            this.currentTasks--
            this.runNextTask()
          })
      }
    }
  }

  addTask(task: () => Promise<void>) {
    this.taskQueue.push(task)
  }

  async runAll(onProgress?: (completed: number, total: number) => void) {
    const totalTasks = this.taskQueue.length

    while (this.taskQueue.length > 0 || this.currentTasks > 0) {
      this.runNextTask()

      if (onProgress) {
        onProgress(this.completedTasks, totalTasks) // Report progress
      }
      await new Promise((resolve) => setTimeout(resolve, 100)) // Wait for all tasks to complete
    }

    if (onProgress) {
      onProgress(this.completedTasks, totalTasks)
    }
  }
}

import React, { useEffect, useState } from 'react';
import {
  Modal,
  ModalProps,
  //@ts-ignore
  Pressable,
  StyleSheet,
} from 'react-native';
import { ANIMATION_DURATION } from '../constants';
import type { BackdropProps } from './Backdrop.d';

// On iOS, Modal orientations need to be manually specified
const IOS_MODAL_SUPPORTED_ORIENTATIONS: ModalProps['supportedOrientations'] = [
  'portrait',
  'portrait-upside-down',
  'landscape',
  'landscape-left',
  'landscape-right',
];

export default function Backdrop({
  children,
  onPress,
  visible,
}: BackdropProps) {
  const [delayedVisible, setDelayedVisible] = useState(visible);

  useEffect(() => {
    // When `Modal.visible` changes, the inner view gets hidden
    // immediately. This gives no time to `Popover` to animate
    // when `visible` becomes `false`. By delaying the `visible`
    // property, it gives extra time for the popover to animate,
    // then hide the modal
    if (visible) {
      setDelayedVisible(true);
    } else {
      setTimeout(() => setDelayedVisible(false), ANIMATION_DURATION);
    }
  }, [visible]);

  return (
    <Modal
      visible={delayedVisible}
      onRequestClose={onPress}
      hardwareAccelerated
      transparent
      supportedOrientations={IOS_MODAL_SUPPORTED_ORIENTATIONS}
    >
      <Pressable onPress={onPress} style={styles.pressable}>
        {children}
      </Pressable>
    </Modal>
  );
}

const styles = StyleSheet.create({
  pressable: {
    flex: 1,
  },
});

// Aided with basic GitHub coding tools
import { describe, it, expect } from "@jest/globals";
import { TaskParser } from "../models/task-parser";

describe("extractTags", () => {
  const parser = new TaskParser();

  it("extracts single tag", () => {
    expect(parser.extractTags("foo #tag bar")).toEqual(["tag"]);
  });

  it("extracts multiple tags", () => {
    expect(parser.extractTags("#a #b #c")).toEqual(["a", "b", "c"]);
  });

  it("ignores email#tag style", () => {
    expect(parser.extractTags("email#tag #realTag")).toEqual(["realTag"]);
  });

  it("extracts tag at start", () => {
    expect(parser.extractTags("#start tag")[0]).toBe("start");
  });

  it("extracts tag at end", () => {
    expect(parser.extractTags("foo #end")[0]).toBe("end");
  });

  it("returns empty array if no tags", () => {
    expect(parser.extractTags("no tags here")).toEqual([]);
  });
});

import * as metroResolver from 'metro-resolver';
import { loadConfig, createMatchPath } from 'tsconfig-paths';
import type { MatchPath } from 'tsconfig-paths';
import { parse, join } from 'path';

export function resolveRequest(
  _context: any,
  moduleName: string,
  platform: string | null
) {
  const { resolveRequest, ...context } = _context;

  try {
    return metroResolver.resolve(context, moduleName, platform);
  } catch {
    // ignore
  }

  const matcher = getMatcher();
  const match = matcher(moduleName);
  if (match) {
    return {
      type: 'sourceFile',
      filePath: match,
    };
  } else {
    // Resolve as a normal asset
    const parsedPath = parse(context.originModulePath);
    const filePath = join(parsedPath.dir, moduleName);
    return {
      type: 'sourceFile',
      filePath,
    };
  }
}

let matcher: MatchPath;
function getMatcher() {
  if (!matcher) {
    const result = loadConfig();
    if (result.resultType === 'success') {
      const { absoluteBaseUrl, paths } = result;
      matcher = createMatchPath(absoluteBaseUrl, paths);
    } else {
      throw new Error(`Could not load tsconfig for project`);
    }
  }
  return matcher;
}

import { WebGLUtility } from "../lib/webgl.js";
import VSSource from "./main.vert";
import FSSource from "./main.frag";
import Image1 from "./assets/001.webp";
import Image2 from "./assets/002.webp";
import Image3 from "./assets/003.webp";
import Image4 from "./assets/004.webp";
import Image5 from "./assets/005.webp";
import Image6 from "./assets/006.webp";
import Image7 from "./assets/007.webp";
import Image8 from "./assets/008.webp";

class Transition {
  static DURATION = 300.0;
  private is_transitioning = false;
  private time: number;
  private startTime: number | undefined;
  private onTransitionEnd: () => void;
  constructor(onTransitionEnd: () => void) {
    this.time = performance.now();
    this.onTransitionEnd = onTransitionEnd;
  }
  get isTransitioning() {
    return this.is_transitioning;
  }
  startTransition() {
    this.is_transitioning = true;
    this.startTime = performance.now();
  }
  update() {
    this.time = performance.now();
    if (this.startTime && this.time - this.startTime > Transition.DURATION) {
      this.is_transitioning = false;
      this.startTime = undefined;
      this.onTransitionEnd();
    }
  }
  getProgress() {
    if (!this.startTime) {
      return 0.0;
    }
    return Math.min((this.time - this.startTime) / Transition.DURATION, 1.0);
  }
}

// Aided using common development resources
const padImageToPowerOfTwo = async (image: HTMLImageElement) => {
  const originalWidth = image.width;
  const originalHeight = image.height;

  // 2のべき乗のサイズに丸める
  const width = Math.pow(2, Math.ceil(Math.log2(originalWidth)));
  const height = Math.pow(2, Math.ceil(Math.log2(originalHeight)));

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext("2d")!;
  ctx.drawImage(image, 0, 0, originalWidth, originalHeight);
  const imageUrl = canvas.toDataURL();
  return (await WebGLUtility.loadImage(imageUrl)) as HTMLImageElement;
};

window.addEventListener(
  "DOMContentLoaded",
  async () => {
    const app = new App();
    app.init();
    await app.load();
    app.setupGeometry();
    app.setupLocation();
    app.setupEventHandler();
    app.start();
  },
  false,
);

class App {
  canvas: HTMLCanvasElement;
  gl: WebGLRenderingContext;
  textures: WebGLTexture[];
  // WebGL 2.0ではuniformとして渡さなくても良くなるらしい？
  textureSizes: Float32Array[];
  originalImageSizes: Float32Array[];
  program: WebGLProgram;
  attributeLocation: GLint[];
  attributeStride: GLint[];
  planePoints: number[];
  planeVBO: WebGLBuffer;
  uniformLocation: {
    progress: WebGLUniformLocation;
    resolution: WebGLUniformLocation;
    texture0: WebGLUniformLocation;
    texSize0: WebGLUniformLocation;
    originalImageSize0: WebGLUniformLocation;
    texture1: WebGLUniformLocation;
    texSize1: WebGLUniformLocation;
    originalImageSize1: WebGLUniformLocation;
  };
  imageIndex = 0;
  nextImageIndex = -1;
  transition: Transition;
  touchEventTrigerred = false;

  constructor() {
    // this を固定するためのバインド処理
    this.resize = this.resize.bind(this);
    this.render = this.render.bind(this);
  }

  init() {
    this.canvas = document.getElementById("webgl-canvas") as HTMLCanvasElement;
    this.gl = WebGLUtility.createWebGLContext(this.canvas);

    this.resize();

    window.addEventListener("resize", this.resize, false);

    this.gl.enable(this.gl.CULL_FACE);
    this.gl.enable(this.gl.DEPTH_TEST);
  }

  onTransitionEnd() {
    this.imageIndex = this.nextImageIndex;
    this.nextImageIndex = this.getNextImageIndex();
  }

  getNextImageIndex() {
    while (true) {
      const next = Math.floor(Math.random() * this.textures.length);
      if (next !== this.imageIndex) {
        return next;
      }
    }
  }

  resize() {
    this.canvas.width = window.innerWidth;
    this.canvas.height = window.innerHeight;
  }

  async load() {
    const gl = this.gl;
    if (!gl) {
      throw new Error("not initialized");
    }

    // vertex shader
    const vertexShader = gl.createShader(gl.VERTEX_SHADER);
    if (!vertexShader) {
      throw new Error("failed to create vertex shader");
    }
    gl.shaderSource(vertexShader, VSSource);
    gl.compileShader(vertexShader);
    if (!gl.getShaderParameter(vertexShader, gl.COMPILE_STATUS)) {
      throw new Error(gl.getShaderInfoLog(vertexShader)!);
    }

    // fragment shader
    const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER);
    if (!fragmentShader) {
      throw new Error("failed to create fragment shader");
    }
    gl.shaderSource(fragmentShader, FSSource);
    gl.compileShader(fragmentShader);
    if (!gl.getShaderParameter(fragmentShader, gl.COMPILE_STATUS)) {
      throw new Error(gl.getShaderInfoLog(fragmentShader)!);
    }

    // load images
    const images: HTMLImageElement[] = await Promise.all([
      WebGLUtility.loadImage(Image1),
      WebGLUtility.loadImage(Image2),
      WebGLUtility.loadImage(Image3),
      WebGLUtility.loadImage(Image4),
      WebGLUtility.loadImage(Image5),
      WebGLUtility.loadImage(Image6),
      WebGLUtility.loadImage(Image7),
      WebGLUtility.loadImage(Image8),
    ]);
    const resizedImages = await Promise.all<HTMLImageElement>(
      images.map((img) => padImageToPowerOfTwo(img)),
    );
    this.textures = resizedImages.map((img) =>
      WebGLUtility.createTexture(gl, img),
    );
    const textureSizes: Float32Array[] = [];
    const originalImageSizes: Float32Array[] = [];
    for (const i in resizedImages) {
      const originalImg = images[i];
      const resizedImg = resizedImages[i];
      textureSizes.push(
        new Float32Array([resizedImg.width, resizedImg.height]),
      );
      originalImageSizes.push(
        new Float32Array([originalImg.width, originalImg.height]),
      );
    }
    this.originalImageSizes = originalImageSizes;
    this.textureSizes = textureSizes;

    // compile program
    const program = gl.createProgram();
    if (!program) {
      throw new Error("failed to create webgl program");
    }
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    gl.deleteShader(vertexShader);
    gl.deleteShader(fragmentShader);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      throw new Error(gl.getProgramInfoLog(program)!);
    }
    gl.useProgram(program);
    this.program = program;
  }

  setupGeometry() {
    const gl = this.gl;
    const [sy, sx, gy, gx] = [-1, -1, 1, 1];
    const cs0 = [
      sx,
      sy,
      0,
      gx,
      gy,
      0,
      sx,
      gy,
      0,
      gx,
      gy,
      0,
      sx,
      sy,
      0,
      gx,
      sy,
      0,
    ];
    const planeVBO = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, planeVBO);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(cs0), gl.STATIC_DRAW);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
    this.planeVBO = planeVBO;
    this.planePoints = cs0;
  }

  setupLocation() {
    const gl = this.gl;
    this.attributeLocation = [gl.getAttribLocation(this.program, "position")];
    this.attributeStride = [3];
    // uniform location の取得
    // TODO texture1
    this.uniformLocation = {
      progress: gl.getUniformLocation(this.program, "progress")!,
      resolution: gl.getUniformLocation(this.program, "resolution")!,
      texture0: gl.getUniformLocation(this.program, "texture0")!,
      texSize0: gl.getUniformLocation(this.program, "texSize0")!,
      originalImageSize0: gl.getUniformLocation(
        this.program,
        "originalImageSize0",
      )!,

      texture1: gl.getUniformLocation(this.program, "texture1")!,
      texSize1: gl.getUniformLocation(this.program, "texSize1")!,
      originalImageSize1: gl.getUniformLocation(
        this.program,
        "originalImageSize1",
      )!,
    };
  }

  setupEventHandler() {
    const onTouch = () => {
      if (this.transition.isTransitioning) {
        return;
      }
      this.transition.startTransition();
    };

    window.addEventListener("touchend", (_) => {
      this.touchEventTrigerred = true;
      onTouch();
    });
    window.addEventListener("click", (_) => {
      if (this.touchEventTrigerred) {
        this.touchEventTrigerred = false;
        return;
      }
      onTouch();
    });
    this.transition = new Transition(() => {
      this.onTransitionEnd();
    });
  }

  setupRendering() {
    const gl = this.gl;
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    gl.clearColor(0.3, 0.3, 0.3, 1.0);
    gl.clearDepth(1.0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
  }

  start() {
    this.nextImageIndex = this.getNextImageIndex();
    this.render();
  }

  render() {
    const gl = this.gl;
    // 現在の画像はTEXTUE0、次の画像はTEXTURE1で管理
    const i = this.imageIndex;
    const j = this.nextImageIndex;

    const progress = this.transition.getProgress();
    this.setupRendering();

    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.textures[i]);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, this.textures[j]);

    gl.useProgram(this.program);
    gl.uniform1f(this.uniformLocation.progress, progress);
    gl.uniform2f(
      this.uniformLocation.resolution,
      this.canvas.width,
      this.canvas.height,
    );
    gl.uniform1i(this.uniformLocation.texture0, 0);
    gl.uniform2fv(this.uniformLocation.texSize0, this.textureSizes[i]);
    gl.uniform2fv(
      this.uniformLocation.originalImageSize0,
      this.originalImageSizes[i],
    );

    gl.uniform1i(this.uniformLocation.texture1, 1);
    gl.uniform2fv(this.uniformLocation.texSize1, this.textureSizes[j]);
    gl.uniform2fv(
      this.uniformLocation.originalImageSize1,
      this.originalImageSizes[j],
    );

    // configure VBO
    gl.bindBuffer(gl.ARRAY_BUFFER, this.planeVBO);
    gl.enableVertexAttribArray(this.attributeLocation[0]);
    gl.vertexAttribPointer(
      this.attributeLocation[0],
      this.attributeStride[0],
      gl.FLOAT,
      false,
      0,
      0,
    );
    gl.drawArrays(
      gl.TRIANGLES,
      0,
      this.planePoints.length / this.attributeStride[0],
    );
    // 描画前に呼ぶとちらつく
    this.transition.update();
    requestAnimationFrame(this.render);
  }
}

import { provide, inject, computed, ref, Ref } from "@vue/composition-api"
import { Book, Books } from "@/types"

type BookContext = {
  books: Ref<Books>
  setBooks: (value: Books) => void
  finishedBooks: Ref<Books>
  addFinishedBooks: (book: Book) => void
  removeFinishedBooks: (book: Book) => void
  hasReadedBook: (book: Book) => boolean
  booksAvaluable: Ref<Books>
}

const BookSymbol = Symbol()

export const useBookListProvide = () => {
  // 全部图书
  const books = ref<Books>([])
  const setBooks = (value: Books) => (books.value = value)

  // 已完成图书
  const finishedBooks = ref<Books>([])
  const addFinishedBooks = (book: Book) => {
    if (!finishedBooks.value.find(({ id }) => id === book.id)) {
      finishedBooks.value.push(book)
    }
  }
  const removeFinishedBooks = (book: Book) => {
    const removeIndex = finishedBooks.value.findIndex(
      ({ id }) => id === book.id
    )
    if (removeIndex !== -1) {
      finishedBooks.value.splice(removeIndex, 1)
    }
  }

  // 可选图书
  const booksAvaluable = computed(() => {
    return books.value.filter(
      book => !finishedBooks.value.find(({ id }) => id === book.id)
    )
  })

  // 是否已阅
  const hasReadedBook = (book: Book) => finishedBooks.value.includes(book)

  provide(BookSymbol, {
    books,
    setBooks,
    finishedBooks,
    addFinishedBooks,
    removeFinishedBooks,
    hasReadedBook,
    booksAvaluable
  })
}

export const useBookListInject = () => {
  const booksContext = inject<BookContext>(BookSymbol)

  if (!booksContext) {
    throw new Error(`useBookListInject must be used after useBookListProvide`)
  }

  return booksContext
}

import 'dotenv/config';

import express, { Request } from 'express';
import { IncomingLinearWebhookPayload } from './types';
import fetch from 'node-fetch';

const app = express();

const port: number = parseInt(process.env.PORT ?? '3000');

app.use(express.json());

app.post<Request['params'], unknown, IncomingLinearWebhookPayload>('/linear', async (req, res) => {
  const payload = req.body;

  if (payload.action === 'create' && payload.type === 'Issue') {
    await newIssue(payload);
  }

  res.sendStatus(200);
});

app.listen(port, () => console.log(`Webhook consumer listening on port ${port}!`));

function newIssue(payload: IncomingLinearWebhookPayload) {
  return fetch(process.env.WEBHOOK!, {
    method: 'POST',
    body: JSON.stringify({
      embeds: [
        {
          color: 0x4752b2,
          author: {
            name: `Issue Created [${getId(payload.url)}]`,
          },
          title: payload.data.title,
          url: payload.url,
          fields: [
            {
              name: 'Priority',
              value: getPriorityValue(payload.data.priority ?? 0),
              inline: true,
            },
            {
              name: 'Points',
              value: payload.data.estimate,
              inline: true,
            },
            {
              name: 'Labels',
              value: prettifyLabels(payload.data.labels!),
              inline: false,
            },
          ],
          timestamp: new Date(),
          footer: {
            text: `Linear App`,
            icon_url: 'https://pbs.twimg.com/profile_images/1121592030449168385/MF6whgy1_400x400.png',
          },
        },
      ],
    }),
  });
}

/**
 * Get the Priority Value translated
 * @param priority number for priority
 */
function getPriorityValue(priority: NonNullable<IncomingLinearWebhookPayload['data']['priority']>) {
  switch (priority) {
    case 0:
      return 'None';
    case 1:
      return 'Urgent';
    case 2:
      return 'High';
    case 3:
      return 'Medium';
    case 4:
      return 'Low';
  }
}

/**
 * Get the task ID from url
 * @param link task url
 */
function getId(link: string) {
  return link.split('/')[5];
}

/**
 * Formats and prettifies label(s)
 * @param labels connected labels
 */
function prettifyLabels(labels: NonNullable<IncomingLinearWebhookPayload['data']['labels']>) {
  return labels.map((label) => label.name).join(', ');
}

