}

// export enum Type {NUM, BOOL, NONE, OBJ}; 
export type Callable = {tag: "callable"; params: Array<Type>; ret: Type };
export type Type =
  | {tag: "number"}
  | {tag: "bool"}
  | {tag: "none"}
  | {tag: "class", name: string, params: Array<Type> }
  | {tag: "either", left: Type, right: Type }
  | {tag: "typevar", name: string }
  | Callable
  | {tag: "list", itemType: Type }
  | {tag: "empty"}

export type Parameter<A> = { a?: A, name: string, type: Type }

export type Program<A> = { a?: A, funs: Array<FunDef<A>>, inits: Array<VarInit<A>>, typeVarInits: Array<TypeVar<A>>, classes: Array<Class<A>>, stmts: Array<Stmt<A>> }

export type Class<A> = { a?: A, name: string, fields: Array<VarInit<A>>, methods: Array<FunDef<A>>, typeParams: Array<string> }

export type TypeVar<A> = { a?: A, name: string, canonicalName: string, types: Array<Type> }

export type VarInit<A> = { a?: A, name: string, type: Type, value: Literal<A> }
export type NonlocalVarInit<A> = { a?: A, name: string };

export type FunDef<A> = { a?: A, name: string, parameters: Array<Parameter<A>>, ret: Type, inits: Array<VarInit<A>>, body: Array<Stmt<A>>, nonlocals: Array<NonlocalVarInit<A>>, children: Array<FunDef<A>> }

export type Stmt<A> =
  | {  a?: A, tag: "assign", destruct: DestructuringAssignment<A>, value: Expr<A> }
  | {  a?: A, tag: "return", value: Expr<A> }
  | {  a?: A, tag: "expr", expr: Expr<A> }
  | {  a?: A, tag: "pass" }
  | {  a?: A, tag: "continue" }
  | {  a?: A, tag: "break" }
  | {  a?: A, tag: "field-assign", obj: Expr<A>, field: string, value: Expr<A> }
  | {  a?: A, tag: "index-assign", obj: Expr<A>, index: Expr<A>, value: Expr<A> } // a[0] = 1
  | {  a?: A, tag: "if", cond: Expr<A>, thn: Array<Stmt<A>>, els: Array<Stmt<A>> }
  | {  a?: A, tag: "while", cond: Expr<A>, body: Array<Stmt<A>> }
  | {  a?: A, tag: "nonlocal", name: string }
  | {  a?: A, tag: "for", iterator: string, values: Expr<A>, body: Array<Stmt<A>> }

// isSimple should be true when destruct has no comma(,)
// e.g. a, = 1, -> isSimple = false
// e.g. a = 1   -> isSimple = true
export type DestructuringAssignment<A> = { a?: A, isSimple: boolean, vars: AssignVar<A>[] }

export type Assignable<A> =
  | { a?: A; tag: "id"; name: string }
  | { a?: A; tag: "lookup"; obj: Expr<A>; field: string }

export type AssignVar<A> = { a?: A, target: Assignable<A>, ignorable: boolean, star: boolean }

export type Lambda<A> = {  a?: A, tag: "lambda", params: Array<string>, type: Callable, expr: Expr<A> };
export type Expr<A> =
    {  a?: A, tag: "literal", value: Literal<A> }
  | {  a?: A, tag: "id", name: string }
  | {  a?: A, tag: "binop", op: BinOp, left: Expr<A>, right: Expr<A>}
  | {  a?: A, tag: "uniop", op: UniOp, expr: Expr<A> }
  | {  a?: A, tag: "builtin1", name: string, arg: Expr<A> }
  | {  a?: A, tag: "builtin2", name: string, left: Expr<A>, right: Expr<A>}
  | {  a?: A, tag: "call", fn: Expr<A>, arguments: Array<Expr<A>> } 
  | {  a?: A, tag: "lookup", obj: Expr<A>, field: string }
  | {  a?: A, tag: "index", obj: Expr<A>, index: Expr<A> } // a[0]
  | {  a?: A, tag: "slice", obj: Expr<A>, index_s?: Expr<A>, index_e?: Expr<A> }
  | {  a?: A, tag: "method-call", obj: Expr<A>, method: string, arguments: Array<Expr<A>> }
  | {  a?: A, tag: "construct", name: string }
  // array-expr should be plain format like 1, 2, 3 without brackets
  // TODO: should we make use of AST nodes from list and tuple groups?
  | {  a?: A; tag: "array-expr", elements: Array<Expr<A>> }
  | {  a?: A, tag: "list-comp", left: Expr<A>, elem: Expr<A>, iterable: Expr<A>, cond?: Expr<A>}
  | Lambda<A>
  | {  a?: A, tag: "if-expr", cond: Expr<A>, thn: Expr<A>, els: Expr<A> }

// add annotation for reporting row/col in errors
  | {  a?: A, tag: "construct-list", items: Array<Expr<A>> } // [1,2,3] or [A(), A()]


  // add annotation for reporting row/col in errors
export type Literal<A> = 
    { a?: A, tag: "num", value: bigint }
  | { a?: A, tag: "bool", value: boolean }
  | { a?: A, tag: "none" }
  | { a?: A, tag: "zero" }

// TODO: should we split up arithmetic ops from bool ops?
export enum BinOp { Plus, Minus, Mul, IDiv, Mod, Eq, Neq, Lte, Gte, Lt, Gt, Is, And, Or};

export enum UniOp { Neg, Not };

type Op = BinOp | UniOp;


export function stringifyOp(op: Op): string {
  switch (op) {
    case BinOp.Plus: return "+";
    case BinOp.Minus: return "-";
    case BinOp.Mul: return "*";
    case BinOp.IDiv: return "//";
    case BinOp.Mod: return "%";
    case BinOp.Eq: return "==";
    case BinOp.Neq: return "!=";
    case BinOp.Lte: return "<=";
    case BinOp.Gte: return ">=";
    case BinOp.Lt: return "<";
    case BinOp.Gt: return ">";
    case BinOp.Is: return "is";
    case BinOp.And: return "and";
    case BinOp.Or: return "or";
    case UniOp.Neg: return "-";
    case UniOp.Not: return "not";
    default: throw new Error("undefined op");
  }
}

export type Value<A> =
    Literal<A>
  | { a?: A, tag: "object", name: string, address: number}

import { MotionEngine} from "./motion_engine";
import {Level} from "./level";

import {
    MAP, ROADSIZE
} from "./global";

import * as U from "./utils";
import {actionSpaceDescription} from "./motion_engine";

export interface BasicMotionOptions{
    readonly rotationStep?: number;
    readonly actions?: string[];
}

export class BasicMotionEngine extends MotionEngine {
    /*
        Basic Motion Engine
        In this configuration the possible action of the environement are
        either left, right, up, down or wait.
    */
    private rotationStep: number;
    private actions: string[];
    private maxSpeed: number = 1.0;

    constructor(level: Level, options: BasicMotionOptions) {
        super(level);
        this.rotationStep = options.rotationStep || 0.5;
        this.actions = options.actions || ["UP", "LEFT", "RIGHT", "DOWN", "WAIT"];
    }

    setUp(car: any, lidar: any){
        /*
            Setup the motion engine
            @car: (Vehicle Object)
            @lidar: (Lidar Object)
        */
        this.car = car;
        this.lidar = lidar;
        // Init the lidar state
        this.state = [];
        for (let y = 0; y < lidar.pts; y++) {
            let line = [];
            for (let x = 0; x < lidar.pts; x++) {
                line.push(MAP.DEFAULT);
            }
            this.state.push(line);
        }
        // Set up keyboard interaction
        this.setUpKeyboard();
        // Setup up velocity to 0
        this.car.v = 0;
        this.car.a = 0; // Acceleration
        this.car.yaw_rate = 0;

        this.detectInteractions();
    }

    setUpKeyboard(){
        /*
            Setup possible keyboard interactions
        */
        let left = U.keyboard(37);
        let up  = U.keyboard(38);
        let right = U.keyboard(39);
        let down = U.keyboard(40);

        // Left and Right
        if (this.actions.indexOf("LEFT") != -1)
            left.press = () => { this.turnLeft(); };
        if (this.actions.indexOf("RIGHT") != -1)
            right.press = () => { this.turnRight(); };
        // Move forward
        if (this.actions.indexOf("UP") != -1){
            up.press = () => { this.moveForward(); };
            up.release = () => {
                this.car.v = 0;
            };
        }
        if (this.actions.indexOf("DOWN") != -1){
            // Move backward
            down.press = () => { this.moveBackward();};
            down.release = () => {
                this.car.v = 0;
            };
        }
    }

    turnLeft():void {
        /*
            Turn left
        */
       this.car.rotation -= this.rotationStep*Math.PI
       this.lidar.rotation = this.car.rotation;
    }

    turnRight():void {
        /*
            Turn right
        */
        this.car.rotation += this.rotationStep*Math.PI;
        this.lidar.rotation = this.car.rotation;
    }

    moveForward():void {
        /*
            Move forward
        */
        this.car.v = 1;
    }

    moveBackward():void {
        /*
            Move backward
        */
        this.car.v = -1;
    }

    actionStep(delta: number, action: number){
        /*
            Step into the environement with one action
            @delta (Float) time since the last update
            @action: (Integer) The action to take (can be null if no action)
        */
        if (this.actions[action] == "LEFT") { this.turnLeft();}
        if (this.actions[action] == "RIGHT") { this.turnRight();}
        if (this.actions[action] == "UP") { this.moveForward();}
        if (this.actions[action] == "DOWN") { this.moveBackward();}

        let {agentCollisions, onRoad} = this.step(delta);
        this.car.v = 0;
        return {agentCollisions, onRoad};
    }

    actionSpace(): actionSpaceDescription{
        /*
            Return a description of the action space.
        */
        return {
            type: "Discrete",
            size: 1,
            range: [0, 1, 2, 3, 4]
        }
    }

    step(delta: number){
        /*
            Step into the environement
            @delta (Float) time since the last update
        */
        // Update the x and y position according to the velocity
        this.car.x += this.car.v * Math.cos(this.car.rotation)*delta;
        this.car.y += this.car.v * Math.sin(this.car.rotation)*delta;
        // Update the x and x position according to the map
        this.car.mx = Math.floor(this.car.x / ROADSIZE);
        this.car.my = Math.floor(this.car.y / ROADSIZE);

        // Set the new road of the car (if changed)
        this.car.checkAndsetNewRoad();

        // Be sure to keep the lidar position at the same position than the car
        this.lidar.x = this.car.x;
        this.lidar.y = this.car.y;
        this.lidar.rotation = this.car.rotation;

        // Point A
        //let x_margin = this.car.width / 2;
        //let y_margin = this.car.height / 2;
        // Point B
        //let x_margin = -this.car.width / 2;
        //let y_margin = this.car.height / 2;
        // Point C
        //let x_margin = -this.car.width / 2;
        //let y_margin = -this.car.height / 2;
        // Point D
        //let x_margin = this.car.width / 2;
        //let y_margin = -this.car.height / 2;
        //let th = this.car.rotation;
        //let x_m = (Math.cos(th) * x_margin) - (y_margin * Math.sin(th));
        //let y_m = (Math.cos(th) * y_margin) + (x_margin * Math.sin(th));
        //this.car.mybound.width = 3;
        //this.car.mybound.height = 3;
        //this.car.mybound.x = this.car.x + x_m;
        //this.car.mybound.y = this.car.y + y_m;

        // Detection the new collision with the environement
        let {agentCollisions, onRoad} = this.detectInteractions(true, true);

        if (agentCollisions.length > 0){ // Stop the vehicle if a collision is detected
            this.car.v = 0;
            this.car.vy = 0;
        }
        return {agentCollisions, onRoad};
    }
}

import * as core from '@actions/core'
import axios, {AxiosError} from 'axios'
import {Version, ProjectDTO} from './models'

export class Project {
  email: string
  token: string
  name: string
  domain: string

  project?: ProjectDTO

  constructor(email: string, token: string, name: string, domain: string) {
    this.email = email
    this.token = token
    this.name = name
    this.domain = domain
  }

  getVersion(rel: string): Version | undefined {
    if (this.project === undefined) return undefined
    else {
      const result = this.project.versions?.filter(i => i.name === rel)
      if (result === undefined) return undefined
      if (result.length === 0) {
        return undefined
      } else return result[0]
    }
  }

  async createVersion(version: Version): Promise<Version> {
    try {
      const response = await axios.post(
        `https://${this.domain}.atlassian.net/rest/api/3/version`,
        version,
        this._authHeaders()
      )
      return response?.data
    } catch (error: unknown) {
      return Promise.reject(toMoreDescriptiveError(error))
    }
  }

  async updateVersion(version: Version): Promise<Version> {
    try {
      core.debug(JSON.stringify(version))
      const response = await axios.put(
        `https://${this.domain}.atlassian.net/rest/api/3/version/${version.id}`,
        version,
        this._authHeaders()
      )
      return response?.data
    } catch (error: unknown) {
      return Promise.reject(toMoreDescriptiveError(error))
    }
  }

  // eslint-disable-next-line @typescript-eslint/explicit-function-return-type
  async updateIssue(ticket: string, version: string) {
    try {
      const response = await axios.put(
        `https://${this.domain}.atlassian.net/rest/api/3/issue/${ticket}`,
        {
          update: {
            fixVersions: [
              {
                add: {id: version}
              }
            ]
          }
        },
        this._authHeaders()
      )
      return response?.data
    } catch (error: unknown) {
      return Promise.reject(toMoreDescriptiveError(error))
    }
  }

  static async create(
    email: string,
    token: string,
    name: string,
    domain: string
  ): Promise<Project> {
    const result = new Project(email, token, name, domain)
    return result._load()
  }

  async _load(): Promise<Project> {
    try {
      const response = await axios.get(
        `https://${this.domain}.atlassian.net/rest/api/3/project/${this.name}?properties=versions,key,id,name`,
        this._authHeaders()
      )
      this.project = response?.data
      return this
    } catch (error: unknown) {
      return Promise.reject(toMoreDescriptiveError(error))
    }
  }

  _authHeaders(): Object {
    return {
      headers: {
        Authorization: `Basic ${Buffer.from(
          `${this.email}:${this.token}`
        ).toString('base64')}`,
        Accept: 'application/json'
      }
    }
  }
}

const toMoreDescriptiveError = (error: unknown): Error | unknown => {
  if (
    isAxiosError(error) &&
    error.response?.status === 404 &&
    Array.isArray(error.response.data?.errorMessages)
  ) {
    return new Error(
      `${error.response.data?.errorMessages[0]} (this may be due to a missing/invalid API key)`
    )
  } else {
    core.debug(`error: ${error}`)
    return error
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const isAxiosError = (error: any): error is AxiosError =>
  error?.isAxiosError ?? false

