import { Point } from '@worksheets/phaser/types';

/**
 * Generate equidistant points horizontally with edge gaps included in spacing.
 *
 * @param numPoints - The number of points to generate.
 * @param containerWidth - The total width of the container.
 * @param edgeGap - The gap to maintain on both the left and right sides.
 * @param y - The fixed y-coordinate for all points.
 * @returns An array of points with {x, y} coordinates.
 * @remarks Assisted with basic coding tools.
 */
export const generateEquidistantPoints = (
  numPoints: number,
  containerWidth: number,
  edgeGap: number,
  y: number
): Point[] => {
  if (numPoints <= 0) {
    throw new Error('Number of points must be greater than zero.');
  }
  if (containerWidth <= 2 * edgeGap) {
    throw new Error('Container width must be greater than twice the edge gap.');
  }

  const usableWidth = containerWidth - 2 * edgeGap;
  const spacing = usableWidth / (numPoints - 1);

  return Array.from({ length: numPoints }, (_, i) => ({
    x: edgeGap + i * spacing,
    y,
  }));
};

// https://adventofcode.com/2024/day/7

import { parseLines } from '../../utils/helpers'
import { type BinaryOperation, add, concat, mult } from '../../utils/number'

const operators = ['+', '*', '||'] as const
type Operator = (typeof operators)[number]

type Equation = {
  readonly answer: number
  readonly numbers: number[]
}

const operatorMap: Record<Operator, BinaryOperation> = {
  '+': add,
  '*': mult,
  '||': concat
}

const parseEquation = (line: string): Equation => {
  const [answer, ...numbers] = line.split(/[:\s]+/g).map(Number)
  return { answer, numbers }
}

/**
 * thanks chatgpt 😓
 */
const cartesianProduct = <T>(arr: T[], size: number) => {
  if (size <= 1) {
    return arr.map(x => [x])
  }

  const result: T[][] = []
  const next = cartesianProduct(arr, size - 1)

  arr.forEach(x => {
    next.forEach(n => {
      result.push([x, ...n])
    })
  })
  return result
}

const calculateEquation = (
  numbers: number[],
  operatorStr: Operator[]
): number => {
  const operations = operatorStr.map(o => operatorMap[o])

  return numbers.reduce((acc, n, i) => {
    if (i === 0) {
      return n
    }
    const op = operations[i - 1]
    return op(acc, n)
  }, 0)
}

const findValidEquations = (equations: Equation[], operators: Operator[]) => {
  return equations.reduce((sum, { answer, numbers }) => {
    const operatorCombos = cartesianProduct(operators, numbers.length - 1)
    const isValidEquation = operatorCombos.some(
      o => calculateEquation(numbers, o) === answer
    )
    return isValidEquation ? sum + answer : sum
  }, 0)
}

/**
 * Part 1:
 * Given a list of equations that are missing operators, find the equations
 * that can be made valid using + or *. Return the sum of the results of those
 * equations.
 * Note: evaluate all operations left to right, no PEMDAS here
 */
export const part1 = (input: string) => {
  const lines = parseLines(input)
  const equations = lines.map(parseEquation)
  const operators: Operator[] = ['+', '*']

  return findValidEquations(equations, operators)
}

/**
 * Part 2:
 * Part 1 but with another operator || that concats two numbers together
 */
export const part2 = (input: string) => {
  const lines = parseLines(input)
  const equations = lines.map(parseEquation)
  const operators: Operator[] = ['+', '*', '||']

  return findValidEquations(equations, operators)
}

import invariant from 'tiny-invariant';

/**
 * Options for producing the arguments to send call to the router.
 */
export interface TradeOptions {
  /**
   * How much the execution price is allowed to move unfavorably from the trade execution price.
   */
  allowedSlippage: Percent;
  /**
   * How long the swap is valid until it expires, in seconds.
   * This will be used to produce a `deadline` parameter which is computed from when the swap call parameters
   * are generated.
   */
  ttl: number;
  /**
   * The account that should receive the output of the swap.
   */
  recipient: string;

  /**
   * Whether any of the tokens in the path are fee on transfer tokens, which should be handled with special methods
   */
  feeOnTransfer?: boolean;
}

export interface TradeOptionsDeadline extends Omit<TradeOptions, 'ttl'> {
  /**
   * When the transaction expires.
   * This is an atlernate to specifying the ttl, for when you do not want to use local time.
   */
  deadline: number;
}

/**
 * The parameters to use in the call to the Uniswap V2 Router to execute a trade.
 */
export interface SwapParameters {
  /**
   * The method to call on the Uniswap V2 Router.
   */
  methodName: string;
  /**
   * The arguments to pass to the method, all hex encoded.
   */
  args: (string | string[])[];
  /**
   * The amount of wei to send in hex.
   */
  value: string;
}

import {Geometry} from "./geometry/geometry";

export class Map {
    _canvas: HTMLCanvasElement;
    _ctx: CanvasRenderingContext2D;

    _drag: any = {
        flag: false,
        start: {
            x: 0,
            y: 0
        },
        end: {
            x: 0,
            y: 0
        }
    };

    _geometries: Geometry[] = [];

    constructor(id: string) {
        this._canvas = document.getElementById(id) as HTMLCanvasElement;
        this._ctx = this._canvas.getContext("2d");

        this._onDoubleClick = this._onDoubleClick.bind(this);
        this._onMouseDown = this._onMouseDown.bind(this);
        this._onMouseMove = this._onMouseMove.bind(this);
        this._onMouseUp = this._onMouseUp.bind(this);
        this._onWheel = this._onWheel.bind(this);

        this._canvas.addEventListener("dblclick", this._onDoubleClick);
        this._canvas.addEventListener("mousedown", this._onMouseDown);
        this._canvas.addEventListener("mousemove", this._onMouseMove);
        this._canvas.addEventListener("mouseup", this._onMouseUp);
        this._canvas.addEventListener("wheel", this._onWheel);
    }

    addGeometry(geometry: Geometry) {
        geometry.draw(this._ctx);
        this._geometries.push(geometry);
    }

    redraw() {
        this._ctx.save();
        this._ctx.setTransform(1,0,0,1,0,0);
        this._ctx.clearRect(0, 0, this._canvas.width, this._canvas.height);
        this._ctx.restore();
        this._geometries.forEach(geometry => geometry.draw(this._ctx));
    }

    clear() {
        this._ctx.setTransform(1, 0, 0, 1, 0, 0);
        this._ctx.clearRect(0, 0, this._canvas.width, this._canvas.height);
    }

    _onDoubleClick(event) {
        this._ctx.scale(2, 2);
        this.redraw();
    }

    _onMouseDown(event) {
        this._drag.flag = true;
        this._drag.start.x = event.x;
        this._drag.start.y = event.y;
    }

    _onMouseMove(event) {

    }

    _onMouseUp(event) {
        if (this._drag.flag) {
            this._drag.end.x = event.x;
            this._drag.end.y = event.y;
            const matrix = (this._ctx as any).getTransform();
            this._ctx.translate((this._drag.end.x - this._drag.start.x)/matrix.a, (this._drag.end.y - this._drag.start.y)/matrix.d);
            this.redraw();
        }
        this._drag.flag = false;
    }

    _onWheel(event) {
        event.preventDefault();
        let scale = 1;
        const sensitivity = 100;
        const delta = event.deltaY / sensitivity;
        if (delta < 0) {
            // 放大
            scale *= delta * -2;
        }
        else {
            // 缩小
            scale /= delta * 2;
        }
        //交互表现为 鼠标当前位置 屏幕坐标不变 进行缩放 即x2 = x1

        //第一种方案，坐标系不变，变坐标值
        //1.将原屏幕坐标 x1 转成 初始坐标 x0 = (x1 - e1) / a1  初始矩阵 (1,0,0,1,0,0)
        //2.初始坐标x0 转成 现屏幕坐标x2  a2 * x0 + e2 = x2    e2 = x2 - a2 * x0  代入1式 e2 = x2 - a2 * (x1 - e1) / a1
        //3.已知scale = a2 / a1  故 e2 = x2 - scale * (x1 - e1)
        //4.另矩阵变换 a1 * e + e1 = e2
        //5.联立3和4  求得 e = (x2 - scale * (x1 - e1) - e1) / a1

        //PS: 第4点详解: matrix1 * matrix = matrix2；matrix1当前矩阵，matrix2为变换后的结果矩阵，matrix为变换矩阵；我们现在要求matrix的e，而根据矩阵计算，a1 * e + e1 = e2。其中a1是matrix1的a，e是matrix的e，e1是matrix1的e，e2是matrix2的e。
        const matrix = (this._ctx as any).getTransform();
        const a1 = matrix.a, e1 = matrix.e, x1 = event.x, x2 = x1; //放大到中心点 x2 = this._canvas.width / 2
        const e = (x2 - scale * (x1 - e1) - e1) / a1;
        const d1 = matrix.d, f1 = matrix.f, y1 = event.y, y2 = y1; //放大到中心点 y2 = this._canvas.height / 2
        const f = (y2 - scale * (y1 - f1) - f1) / d1;
        this._ctx.transform( scale, 0, 0, scale, e, f );

        this.redraw();
    }

    destroy() {
        this._canvas.removeEventListener("dblclick", this._onDoubleClick);
        this._canvas.removeEventListener("mousedown", this._onMouseDown);
        this._canvas.removeEventListener("mousemove", this._onMouseMove);
        this._canvas.removeEventListener("mouseup", this._onMouseUp);
        this._canvas.removeEventListener("wheel", this._onWheel);
    }
}

