};

// system configuration ------------------------------------------------
export interface Configuration {
    system_id: string;
    frontend_preset_parameters: FrontendPresetParms
    learn_and_adapt_parms:      LearnAndAdaptParms
    wip_limit_search_parms:     WipLimitSearchParms
    value_chains:               ValueChain[]
    workers:                    Worker[]
}

// Supported via standard GitHub programming aids
import * as vscode from "vscode";
import { TaskManager } from "./task-manager";
import { FileTaskExtractor } from "./file-task-extractor";

/**
 * ワークスペース内のマークダウンファイルを監視し、タスクの変更を検出するクラス
 * @generated Supported via standard GitHub programming aids
 */
export class WorkspaceWatcher {
  private watcher: vscode.FileSystemWatcher | undefined;
  private disposables: vscode.Disposable[] = [];
  private debounceTimers: Map<string, NodeJS.Timeout> = new Map();
  private readonly debounceMs = 300;

  constructor(private taskManager: TaskManager) {}

  /**
   * 監視を開始する
   */
  public startWatching(): void {
    if (this.watcher) {
      return;
    }
    this.watcher =
      vscode.workspace.createFileSystemWatcher("**/*.{md,markdown}");
    this.watcher.onDidChange(
      (uri) => this.debounce(uri, () => this.onFileChanged(uri)),
      this,
      this.disposables
    );
    this.watcher.onDidCreate(
      (uri) => this.debounce(uri, () => this.onFileCreated(uri)),
      this,
      this.disposables
    );
    this.watcher.onDidDelete(
      (uri) => this.debounce(uri, () => this.onFileDeleted(uri)),
      this,
      this.disposables
    );
    console.log("[VsTasks] WorkspaceWatcher started");
  }

  /**
   * 監視を停止する
   */
  public stopWatching(): void {
    if (this.watcher) {
      this.watcher.dispose();
      this.watcher = undefined;
    }
    this.debounceTimers.forEach((timer) => clearTimeout(timer));
    this.debounceTimers.clear();
    this.disposables.forEach((d) => d.dispose());
    this.disposables = [];
    console.log("[VsTasks] WorkspaceWatcher stopped");
  }

  /**
   * ファイル変更時の処理
   */
  public async onFileChanged(uri: vscode.Uri): Promise<void> {
    if (!FileTaskExtractor.isMarkdownFile(uri)) {
      return;
    }
    try {
      const tasks = await FileTaskExtractor.extractTasksFromFile(uri);
      this.taskManager.addTasks(uri.fsPath, tasks);
      console.log(`[VsTasks] Tasks updated for file: ${uri.fsPath}`);
    } catch (err) {
      console.error(`[VsTasks] Error onFileChanged: ${uri.fsPath}`, err);
    }
  }

  /**
   * ファイル作成時の処理
   */
  public async onFileCreated(uri: vscode.Uri): Promise<void> {
    if (!FileTaskExtractor.isMarkdownFile(uri)) {
      return;
    }
    try {
      const tasks = await FileTaskExtractor.extractTasksFromFile(uri);
      this.taskManager.addTasks(uri.fsPath, tasks);
      console.log(`[VsTasks] Tasks added for new file: ${uri.fsPath}`);
    } catch (err) {
      console.error(`[VsTasks] Error onFileCreated: ${uri.fsPath}`, err);
    }
  }

  /**
   * ファイル削除時の処理
   */
  public onFileDeleted(uri: vscode.Uri): void {
    if (!FileTaskExtractor.isMarkdownFile(uri)) {
      return;
    }
    this.taskManager.removeTasks(uri.fsPath);
    console.log(`[VsTasks] Tasks removed for deleted file: ${uri.fsPath}`);
  }

  /**
   * debounce処理
   */
  private debounce(uri: vscode.Uri, fn: () => void): void {
    const key = uri.toString();
    if (this.debounceTimers.has(key)) {
      clearTimeout(this.debounceTimers.get(key));
    }
    this.debounceTimers.set(
      key,
      setTimeout(() => {
        this.debounceTimers.delete(key);
        fn();
      }, this.debounceMs)
    );
  }
}

import {
  Contribution,
  types,
  assert,
  useEventListener,
  TopicData,
  useRef,
  useEffect,
} from 'remind-core'
import { CursorStyle, getRectImage } from './utils'

const dndDataFormat = 'text/plain'

const useDndTopic: Contribution = (api) => {
  const { model, view, viewModel } = api
  const { root } = model
  const fromRef = useRef<TopicData>()
  const dragImageRef = useRef<HTMLImageElement>()

  function handleDragStart(e: DragEvent) {
    const node = viewModel.hitTest(e.offsetX, e.offsetY)
    // Root node is not draggable
    if (!node || node.data.id === root.id) {
      e.preventDefault()
      return
    }

    assert(e.dataTransfer)
    fromRef.current = node.data
    e.dataTransfer.setDragImage(dragImageRef.current, 10, 10)
    e.dataTransfer.effectAllowed = 'move'
    e.dataTransfer.dropEffect = 'none'
    // setData dataTransfer to make drag and drop work in firefox
    e.dataTransfer.setData(dndDataFormat, '')
  }

  function isChild(toId: string) {
    return fromRef.current?.children?.some((node) => node.id === toId)
  }

  function handleDrop(e: DragEvent) {
    const fromNode = fromRef.current
    const toId = types.getTopicId(e.target)
    if (!fromNode || !toId || fromNode.id === toId) return
    assert(fromNode)
    // Should not drop topic to it's descendants
    if (isChild(toId)) {
      return
    }

    model.update(() => {
      // If node already exist in node tree, delete it from it's old parent first
      model.deleteNode(fromNode.id)
      model.appendChild(toId, fromNode)
    })
  }

  // We need to prevent the default behavior
  // of this event, in order for the onDrop
  // event to fire.
  // It may sound weird, but the default is
  // to cancel out the drop.
  function handleDragOver(e: DragEvent) {
    e.preventDefault()
  }

  function handleDrag(e: DragEvent) {
    e.preventDefault()
    const toNode = viewModel.hitTest(e.offsetX, e.offsetY)
    assert(e.dataTransfer)
    assert(view.current instanceof HTMLDivElement)
    if (fromRef.current && toNode?.data.id && !isChild(toNode.data.id)) {
      // set dropEffect seems has no effect on chrome
      e.dataTransfer.dropEffect = 'move'
      view.current.style.cursor = CursorStyle.copy
      console.log(view.current.style.cursor)
    } else {
      view.current.style.cursor = CursorStyle.notAllowed
    }
  }

  function handleDragEnd() {
    assert(view.current instanceof HTMLDivElement)
    fromRef.current = undefined
    view.current.style.cursor = CursorStyle.default
  }

  useEffect(() => {
    const img = getRectImage()
    img.style.position = 'absolute'
    img.style.left = '-10000px'
    dragImageRef.current = img
    return () => {
      dragImageRef.current?.remove()
    }
  }, [])

  useEventListener('dragstart', handleDragStart, {
    target: view,
  })
  useEventListener('drag', handleDrag, {
    target: view,
  })
  useEventListener('drop', handleDrop, {
    target: view,
  })
  useEventListener('dragover', handleDragOver, {
    target: view,
  })
  useEventListener('dragend', handleDragEnd, {
    target: view,
  })
}

