/* This is the way to create decorators without TypeScript's built in support */
abstract class Vehicle{
    private _make: string;
    private _model: string;
    private _passengerCount: number;

    constructor(make:string, model: string, passengerCount:number){
        this._make = make;
        this._model = model;
        this._passengerCount = passengerCount
    }

    get make():string{
        return this._make
    }

    set make(newMake: string){
        this._make = newMake;
    }

    get model():string{
        return this._model
    }

    set model(newModel: string){
        this._model = newModel;
    }

    get passengerCount():number{
        return this._passengerCount
    }

    set passengerCount(newCount: number){
        this._passengerCount = newCount;
    }

    describeCar(): string{
        return `You are viewing the ${this._make} ${this._model}.`
    }

    countPassengers(): string{
        return `You are can seat ${this._passengerCount} passengers in the ${this._make} ${this._model}.`
    }
}

class Camry extends Vehicle{


    constructor(){
        super('Toyota', 'Camry', 5)
    }



}

class Sienna extends Vehicle{

    constructor(){
        super('Toyota', 'Sienna', 5)
    }

}

abstract class VehicleOptions extends Vehicle{
    decoratedVehicle: Vehicle

    //override the previous methods defined in the Abstract Vehicle class
    abstract describeCar():string;
    abstract countPassengers(): string;
}

class LeatherSeats extends VehicleOptions{

    decoratedVehicle: Vehicle;

    constructor(vehicle:Vehicle){
        super(vehicle.make, vehicle.model, vehicle.passengerCount);
        this.decoratedVehicle = vehicle;
    }
    describeCar(): string {
       return `${this.decoratedVehicle.describeCar()} It now has leather seats.`
    }
    countPassengers(): string {
        return `${this.decoratedVehicle.countPassengers()}`
    }

}

class CenterSeat extends VehicleOptions{

    decoratedVehicle: Vehicle;

    constructor(vehicle:Vehicle){
        super(vehicle.make, vehicle.model, vehicle.passengerCount);
        this.decoratedVehicle = vehicle;
    }

    describeCar(): string {

        if(this.decoratedVehicle['decoratedVehicle'] instanceof Sienna){
            return `${this.decoratedVehicle.describeCar()} It now has the center seat on the second row.`
        } else{
            return `${this.decoratedVehicle.describeCar()} This vehicle doesn't have the second row.`
        }
    }

    countPassengers(): string {
        if(this.decoratedVehicle['decoratedVehicle'] instanceof Sienna){
            this.decoratedVehicle['decoratedVehicle'].passengerCount++
        }
        return `${this.decoratedVehicle.countPassengers()}`
    }
}

let mySienna:Sienna = new Sienna()
let myCamry:Camry = new Camry()

//Add leather seats
mySienna = new LeatherSeats(mySienna);
myCamry = new LeatherSeats(myCamry);

//Add the center seat for the minivan's second row
mySienna = new CenterSeat(mySienna);
myCamry = new CenterSeat(myCamry);

console.log(mySienna.describeCar())
console.log(myCamry.describeCar())

console.log(mySienna.countPassengers())
console.log(myCamry.countPassengers())

import { Request, Response, NextFunction } from 'express';
import Model from './item.model';

export default class UserController {

    /**
     * Get all
     * @param {*} req 
     * @param {*} res 
     * @param {*} next 
     */
    public static async getAll(req: Request, res: Response, next: NextFunction) {

        var pageNo = parseInt(req.query.pageNo)
        var size = parseInt(req.query.size)
        var query = {
            skip: size * (pageNo - 1),
            limit: size
        }

        try {
            if(pageNo < 0 || pageNo === 0) {
                res.send({"error" : true,"message" : "invalid page number, should start with 1"})
            }
            query.skip = size * (pageNo - 1)
            query.limit = size
            // 
            // Get data
            let result = await Model.count({}, (err,totalCount)=> {
                if(err) {
                    res.send({"error" : true,"message" : "Error fetching data"});
                }

                Model.find({},{},query,function(err,data) {

                    if(err){
                        res.send({"error" : true,"message" : "Error fetching data"})
                    } else {
                        const status = res.statusCode;
                        let totalPages = Math.ceil(totalCount / size)
                        res.send({"error" : false,"message" : 'it works! We got all items',"pages": totalPages, status: status, result: data});
                    }
                });

            })

        } catch (err) {

            // 
            // Error response
            res.send({
                message: 'Could not get items',
                err: err
            });
        }
    }

    /**
     * getUser
     * @param {*} req 
     * @param {*} res 
     * @param {*} next 
     */

    public static async getItem(req: Request, res: Response, next: NextFunction) {

        try {

            // 
            // Get data
            const _id: String = req.params._id;
            let result = await Model.findOne({ _id }).exec();
            const status = res.statusCode;

            // 
            // Response
            res.send({
                message: 'Successfull got an item',
                result: result,
                status: status
            });
        } catch (err) {

            // 
            // Error response
            res.send({
                message: 'Could not the item ',
                err: err
            });
        }
    }

    /**
     * Create
     * @param {*} req 
     * @param {*} res 
     * @param {*} next 
     */
    public static async createItem(req: Request, res: Response, next: NextFunction) {

        const title:String = req.body.title;
        const id:Number = req.body.id;
        const type:String = req.body.type;
        const desc:String = req.body.desc;
        const photo:String = req.body.photo;
        const price:Number = req.body.price;
        const inStock:Number = req.body.inStock;


        // Create model
        let model = new Model({
            id,
            title,
            type,
            desc,
            photo,
            price,
            inStock
        });
        // 
        // Save
        await model.save();

        res.send({
            message: 'Item Created!',
            model: model
        });
    }

    public static async deleteItem(req: Request, res: Response, next: NextFunction) {
        const _id:String = req.params._id;

        try {

            // 
            // Get data
            const id: String = req.params._id;
            let result = await Model.findOneAndRemove({ _id }, {
                ...req.body,
                deletedAt: new Date()
            }).exec();
            const status = res.statusCode;

            // 
            // Response
            res.send({
                message: 'Sucessfully deleted item',
                result: result,
                status: status
            });
        } catch (err) {

            // 
            // Error response
            res.send({
                message: 'Could not delete th item',
                err: err
            });
        }
    }

    public static async updateItem(req: Request, res: Response, next: NextFunction) {
        const _id:String = req.params;

        try {

            // 
            // Get data
            const _id: String = req.params._id;
            let result = await Model.findOneAndUpdate({ _id }, {
                ...req.body,
                updatedAt: new Date()
            }).exec();
            const status = res.statusCode;

            // 
            // Response
            res.send({
                message: 'Sucessfully updated item',
                result: result,
                status: status
            });
        } catch (err) {

            // 
            // Error response
            res.send({
                message: 'item could not be updated',
                err: err
            });
        }
    }
}

