// Blacklist common values.
const BLACKLIST: Array<string> = [
  '00000000000000',
  '11111111111111',
  '22222222222222',
  '33333333333333',
  '44444444444444',
  '55555555555555',
  '66666666666666',
  '77777777777777',
  '88888888888888',
  '99999999999999'
]

const STRICT_STRIP_REGEX: RegExp = /[-\\/.]/g
const LOOSE_STRIP_REGEX: RegExp = /[^\d]/g

const verifierDigit = (digits: string): number => {
  let index: number = 2
  const reverse: Array<number> = digits.split('').reduce((buffer, number) => {
    return [parseInt(number, 10)].concat(buffer)
  }, [])

  const sum: number = reverse.reduce((buffer, number) => {
    buffer += number * index
    index = (index === 9 ? 2 : index + 1)
    return buffer
  }, 0)

  const mod: number = sum % 11
  return (mod < 2 ? 0 : 11 - mod)
}

const strip = (number: string, strict?: boolean): string => {
  const regex: RegExp = strict ? STRICT_STRIP_REGEX : LOOSE_STRIP_REGEX
  return (number || '').replace(regex, '')
}

const format = (number: string): string => {
  return strip(number).replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5')
}

const isValid = (number: string, strict?: boolean): boolean => {
  const stripped: string = strip(number, strict)

  // CNPJ must be defined
  if (!stripped) {
    return false
  }

  // CNPJ must have 14 chars
  if (stripped.length !== 14) {
    return false
  }

  // CNPJ can't be blacklisted
  if (BLACKLIST.includes(stripped)) {
    return false
  }

  let numbers: string = stripped.substr(0, 12)
  numbers += verifierDigit(numbers)
  numbers += verifierDigit(numbers)

  return numbers.substr(-2) === stripped.substr(-2)
}

const generate = (formatted?: boolean): string => {
  let numbers: string = ''

  for (let i = 0; i < 12; i += 1) {
    numbers += Math.floor(Math.random() * 9)
  }

  numbers += verifierDigit(numbers)
  numbers += verifierDigit(numbers)

  return (formatted ? format(numbers) : numbers)
}

export default {
  verifierDigit,
  strip,
  format,
  isValid,
  generate
}

import BubbleMgr from "./BubbleMgr";

const {ccclass, property} = cc._decorator;

@ccclass
export default class Bubble extends cc.Component {

    // 父节点类
    private parent: BubbleMgr;

    /** 初始化 */
    public init (parent: BubbleMgr, position: cc.Vec2, spriteFrame: cc.SpriteFrame): void {
        parent.node.addChild(this.node);
        this.parent = parent;
        this.node.position = position;
        this.setSpriteFrame(spriteFrame);
    }

    /** 设置纹理 */
    public setSpriteFrame (spriteFrame: cc.SpriteFrame): void {
        this.getComponent(cc.Sprite).spriteFrame = spriteFrame;
    }

    /** 死亡动画 */
    public playDeathAnimation (index: cc.Vec2): void {
        this.node.runAction(
            cc.sequence(
                // 膨胀后消除自己
                cc.scaleTo(0.1, 1.2),
                cc.scaleTo(0.1, 1.0),
                cc.callFunc(() => {
                    // 将位置空出
                    this.parent.bubblesArray[index.x][index.y] = undefined;
                }, this),
                cc.removeSelf()
            )
        );
    }

    /** 下落动画 */
    public playDownAnimation (index: cc.Vec2): void {
        this.node.runAction(
            // 渐隐下落
            cc.sequence(
                cc.spawn(
                    cc.moveBy(0.5, 0, -300),
                    cc.fadeOut(0.5)
                ),
                cc.callFunc(() => {
                    this.parent.bubblesArray[index.x][index.y] = undefined;
                }, this),
                cc.removeSelf()
            )
        );
    }
}

