/* Imports: External */
import { HardhatRuntimeEnvironment } from 'hardhat/types'
import { HardhatNetworkProvider } from 'hardhat/internal/hardhat-network/provider/provider'

/**
 * Finds the "base" Ethereum provider of the current hardhat environment.
 *
 * Basically, hardhat uses a system of nested providers where each provider wraps the next and
 * "provides" some extra features. When you're running on top of the "hardhat evm" the bottom of
 * this series of providers is the "HardhatNetworkProvider":
 * https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
 * This object has direct access to the node (provider._node), which in turn has direct access to
 * the ethereumjs-vm instance (provider._node._vm). So it's quite useful to be able to find this
 * object reliably!
 * @param hre hardhat runtime environment to pull the base provider from.
 * @return base hardhat network provider
 */
export const findBaseHardhatProvider = (
  runtime: HardhatRuntimeEnvironment
): HardhatNetworkProvider => {
  // This function is pretty approximate. Haven't spent enough time figuring out if there's a more
  // reliable way to get the base provider. I can imagine a future in which there's some circular
  // references and this function ends up looping. So I'll just preempt this by capping the maximum
  // search depth.
  const maxLoopIterations = 1024
  let currentLoopIterations = 0

  // Search by looking for the internal "_wrapped" variable. Base provider doesn't have this
  // property (at least for now!).
  let provider = runtime.network.provider
  while ((provider as any)._wrapped !== undefined) {
    provider = (provider as any)._wrapped

    // Just throw if we ever end up in (what seems to be) an infinite loop.
    currentLoopIterations += 1
    if (currentLoopIterations > maxLoopIterations) {
      throw new Error(
        `[smock]: unable to find base hardhat provider. are you sure you're running locally?`
      )
    }
  }

  // TODO: Figure out a reliable way to do a type check here. Source for inspiration:
  // https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
  return provider as any
}

export const TOKEN_NAMES = {
	sceneHeading: "scene-heading",
	formattingSceneHeading: "formatting-scene-heading",
	action: "action",
	character: "character",
	dialogue: "dialogue",
	parenthetical: "parenthetical",
	lyrics: "lyrics",
	centered: "centered",
	transition: "transition",
	section: "section",
	synopsis: "synopsis",
	boneyard: "boneyard",
	fBoneyardStart: "formatting-boneyard-start",
	fBoneyardEnd: "formatting-boneyard-end",
	pageBreak: "page-break",
} as const;

const n = TOKEN_NAMES;

// transparency: this list is enhanced and Aided using common development resources
const sceneHeadingPrefixesMap = {
	// - Latin: INT, EXT, EST, I/E, INT/EXT
	latin: ["int", "ext", "est", "i/e", "int/ext"],

	// - Russian: ИНТ, НАТ, ЭСТ, И/Н, ИНТ/НАТ
	russian: ["инт", "нат", "эст", "и/н", "инт/нат"],

	// - Ukrainian: ІНТ, НАТ, ЕСТ, І/Н, ІНТ/НАТ
	ukrainian: ["інт", "нат", "ест", "і/н", "інт/нат"],

	// - Bulgarian: ВН, ИЗН, ВН/ИЗН
	bulgarian: ["вн", "изн", "вн/изн"],

	// - Serbian/Macedonian: ВН, НАДВ, ВН/НАДВ
	serbianMacedonian: ["вн", "надв", "вн/надв"],

	// - Greek: ΕΣΩ. (INT), ΕΞΩ. (EXT), ΕΣΩ/ΕΞΩ. (INT/EXT)
	//   Sometimes ΕΣΤ. for "establishing"
	greek: ["εσω", "εξω", "εσω/εξω", "εστ"],

	// - Hebrew: פנ. (INT = פנימי), חוץ. (EXT), פנ/חוץ. (INT/EXT)
	//   NB: Hebrew is RTL but regex still matches left-to-right in source
	hebrew: ["פנ", "חוץ", "פנ/חוץ"],

	// - Arabic: د. (داخل = INT), خ. (خارج = EXT), د/خ. (INT/EXT)
	//   Sometimes spelled in full: داخل, خارج
	arabic: ["د", "خ", "د/خ", "داخل", "خارج", "داخل/خارج"],

	// - Turkish: İÇ (INT), DIŞ (EXT), İÇ/DIŞ
	turkish: ["iç", "dış", "iç/dış"],

	// - French/Spanish/Italian (they often keep English, but some use native)
	//   French: INTÉR. / EXT. ; Spanish: INT. / EXT. ; Italian: INT. / EST.
	//   Adding common alternatives
	romance: ["intér", "inter", "est", "ext"],
};

const dedupedSceneHeadingPrefixes = [
	...new Set(Object.values(sceneHeadingPrefixesMap).flat()),
];

export const LINE_TOKENS = [
	{
		id: n.sceneHeading,
		// - Scene heading int/ext
		// - Fountain Power User: dot prefix e.g. `.MONTAGE`
		regex: new RegExp(
			`^((?:\\*{0,3}_?)?(?:${dedupedSceneHeadingPrefixes.join("|")})[. ].+)|^\\.(?!\\.+)(.+)`,
			"iu",
		),
	},
	{
		id: n.action,
		// Fountain Power User: lines starting with `!`
		regex: /^!.*$/u,
	},
	{
		id: n.character,
		// - Latin uppercase
		// - Extended Latin (À-ß, etc.)
		// - Cyrillic uppercase (0400–052F)
		// Fountain Power User: `@`-prefix, e.g. `@O'McDONALD`
		regex:
			/^[^\S\r\n]*(?=.*[\p{Lu}\u0400-\u04FF\u0500-\u052F])[A-Z\d\u00C0-\u00DEF\u0400-\u04FF\u0500-\u052F \t'.-]+\s?(\(.*\))?$|@.*$/u,
	},
	{
		id: n.dialogue,
		// Dialogue must follow a character line
		regex: /^[^\S\r\n]*(\^?)?\n(?!\n+)([\s\S]+)/u,
	},
	{
		id: n.parenthetical,
		// e.g. `(whispering)`
		regex: /^[^\S\r\n]*(\(.+\))$/u,
	},
	{
		id: n.lyrics,
		// Lines starting with ~
		regex: /^~.*$/u,
	},
	{
		id: n.centered,
		// > CENTERED TEXT <
		regex: /^[^\S\r\n]*>[^<>]+<$/u,
	},
	{
		id: n.transition,
		// - Lines ending with `TO:`, e.g. `CUT TO:`
		// - Fountain Power user: `>`-prefix, e.g. `FADE TO BLACK:`
		// - Cyrillic uppercase `TO:`, e.g. `перейти к TO:`
		regex:
			/^[^\S\r\n]*(>[^<\n\r]*|[\p{Lu}\u00C0-\u024F\u0370-\u03FF\u0400-\u052F\u0590-\u05FF\u0600-\u06FF ]+ TO[:：])$/u,
	},
	{
		id: n.section,
		// e.g. `### SECTION TITLE`
		regex: /^(#+) *(.*)/u,
	},
	{
		id: n.synopsis,
		// `= Synopsis`
		regex: /^=(?!=+) *(.*)$/u,
	},
	// Note: /^(?:\[{2}(?!\[+))(.+)(?:\]{2}(?!\[+))$/,
	// note_inline: /(?:\[{2}(?!\[+))([\s\S]+?)(?:\]{2}(?!\[+))/g,
	// boneyard: /(^\/\*|^\*\/)$/g,
	{
		id: n.fBoneyardStart,
		// `/* boneyard start`
		regex: /(^\/\*$)/u,
	},
	{
		id: n.fBoneyardEnd,
		// `*/ boneyard end`
		regex: /(^\*\/$)/u,
	},
	{
		id: n.pageBreak,
		// === (3 or more)
		regex: /^={3,}$/u,
	},
] as const satisfies Array<{id: (typeof n)[keyof typeof n]; regex: RegExp}>;

/**
 * Assisted with basic coding tools
 */

import { useState, useEffect, useRef } from "react";

type CountDown = [number, () => void, () => void];

const useCountDown: (initialCount?: number) => CountDown = (initialCount = 60) => {
    const [count, setCount] = useState(0);
    const intervalRef = useRef<NodeJS.Timer>();

    useEffect(() => {
        if (count <= 0) return;
        intervalRef.current = setInterval(() => {
            setCount(count - 1);
        }, 1000);
        return () => clearInterval(intervalRef.current);
    }, [count]);

    const startCount = () => setCount(initialCount);
    const stopCount = () => {
        setCount(0);
        clearInterval(intervalRef.current);
    };

    return [count, startCount, stopCount];
};

export default useCountDown;

import * as cheerio from 'cheerio';
import axios from 'axios';
import { Name } from 'mizzoureview-reading/models/name';
import {
    AIPromptAnswers,
    Professor,
} from 'mizzoureview-reading/models/professor';
import { generateWikiFunFacts } from 'src/helpers/gemini.js';

// first Aided using common development resources
export async function getArticleContentByName(name: Name) {
    const baseUrl = 'https://en.wikipedia.org/w/api.php';

    // Step 1: Search for the page
    const searchParams = new URLSearchParams({
        origin: '*',
        action: 'parse',
        page: `${name}`,
        format: 'json',
    });

    const fetchUrl = `${baseUrl}?${searchParams}`;

    const { data } = await axios.get(fetchUrl);

    if (data.error) {
        return 'No article';
    }
    const $ = cheerio.load(data.parse.text['*']);

    // Extract only the main content paragraphs
    const articleText = $('p').text();

    return articleText;
}

export async function setProfessorFunFacts(
    profArray: Professor[],
): Promise<boolean> {
    for (let i = 0; i < profArray.length; i++) {
        const prof: Professor = profArray[i];
        if (prof.basicInfo === undefined) {
            return false;
        }
        const article = await getArticleContentByName(prof.basicInfo.name);
        const funFacts = await generateWikiFunFacts(article);
        if (funFacts !== undefined) {
            if (prof.aIPromptAnswers === undefined) {
                prof.aIPromptAnswers = new AIPromptAnswers({
                    funFacts: funFacts,
                });
            } else {
                prof.aIPromptAnswers = new AIPromptAnswers({
                    funFacts: funFacts,
                    letterToProfessor: prof.aIPromptAnswers.letterToProfessor,
                    letterToStudent: prof.aIPromptAnswers.letterToStudent,
                });
            }
        }
    }
    return true;
}

